-- ----------------------------
-- Table structure for agent_acl
-- ----------------------------
DROP TABLE IF EXISTS `agent_acl`;
CREATE TABLE `agent_acl`  (
                              `id` bigint NOT NULL COMMENT '主键',
                              `agent_id` bigint NOT NULL COMMENT 'Agent ID',
                              `subject_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '授权主体：ROLE/DEPT',
                              `subject_id` bigint NOT NULL COMMENT '角色或部门ID',
                              `permission` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'USE' COMMENT '权限：USE/MANAGE',
                              `effective_time` datetime(0) NULL DEFAULT NULL COMMENT '生效时间',
                              `expire_time` datetime(0) NULL DEFAULT NULL COMMENT '失效时间',
                              `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态：0启用 1停用',
                              `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
                              `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
                              `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                              `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                              `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                              `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                              PRIMARY KEY (`id`) USING BTREE,
                              UNIQUE INDEX `uk_agent_acl_subject`(`agent_id`, `subject_type`, `subject_id`, `permission`) USING BTREE,
                              INDEX `idx_agent_acl_subject`(`subject_type`, `subject_id`) USING BTREE,
                              INDEX `idx_agent_acl_access`(`status`, `subject_type`, `subject_id`, `effective_time`, `expire_time`, `agent_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Agent角色部门授权表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of agent_acl
-- ----------------------------

-- ----------------------------
-- Table structure for agent_info
-- ----------------------------
DROP TABLE IF EXISTS `agent_info`;
CREATE TABLE `agent_info`  (
                               `id` bigint NOT NULL AUTO_INCREMENT COMMENT '智能体ID',
                               `agent_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Agent稳定编码',
                               `agent_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '智能体名称',
                               `agent_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'GENERAL' COMMENT 'Agent类型：GENERAL/KNOWLEDGE/BUSINESS/WORKFLOW',
                               `agent_describe` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '智能体描述（下拉展示用）',
                               `agent_show` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '展示图标/头像URL',
                               `model_id` bigint NOT NULL COMMENT '绑定的聊天模型ID（chat_model.id, category=chat）',
                               `model_select_policy` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'FIXED' COMMENT '模型选择策略：FIXED/ROLE_AUTHORIZED',
                               `knowledge_scope_policy` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ROLE_AUTHORIZED' COMMENT '知识库范围：ROLE_AUTHORIZED/BOUND_INTERSECTION',
                               `enable_thinking` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '是否启用深度思考(ReAct多子Agent)：0 否 1 是',
                               `system_prompt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '自定义系统提示词',
                               `welcome_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '欢迎语',
                               `suggested_questions` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '建议问题JSON数组',
                               `execution_policy` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '执行策略JSON对象',
                               `skill_names` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联磁盘技能名列表（JSON数组，[String]）',
                               `knowledge_ids` varchar(1024) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '关联知识库ID列表（JSON数组，[Long]）',
                               `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '状态：0 正常 1 停用',
                               `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
                               `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0正常 1删除）',
                               `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
                               `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                               `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                               `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                               `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                               PRIMARY KEY (`id`) USING BTREE,
                               UNIQUE INDEX `uk_agent_info_code`(`agent_code`) USING BTREE,
                               INDEX `idx_agent_model_id`(`model_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '智能体信息表' ROW_FORMAT = DYNAMIC;

