-- ----------------------------
-- Table structure for chat_message
-- ----------------------------
DROP TABLE IF EXISTS `chat_message`;
CREATE TABLE `chat_message`  (
                                 `id` bigint NOT NULL COMMENT '主键',
                                 `session_id` bigint NULL DEFAULT NULL COMMENT '会话id',
                                 `user_id` bigint NOT NULL COMMENT '用户id',
                                 `message_seq` int NOT NULL DEFAULT 0 COMMENT '会话内消息序号',
                                 `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '消息内容',
                                 `role` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '对话角色',
                                 `model_id` bigint NULL DEFAULT NULL COMMENT '模型ID',
                                 `total_tokens` bigint NULL DEFAULT 0 COMMENT '总 Token 数',
                                 `input_tokens` bigint NULL DEFAULT 0 COMMENT '输入 Token 数',
                                 `output_tokens` bigint NULL DEFAULT 0 COMMENT '输出 Token 数',
                                 `deduct_tokens` bigint NULL DEFAULT 0 COMMENT '扣减 Token 数',
                                 `model_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型名称',
                                 `model_selection_mode` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'FIXED' COMMENT '模型选择模式：FIXED指定模型/AUTO智能选择',
                                 `model_revision` int NULL DEFAULT NULL COMMENT '实际调用的模型发布修订号快照',
                                 `route_reason_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型路由原因编码，FIXED模式记录FIXED',
                                 `route_policy_revision` int NULL DEFAULT NULL COMMENT 'AUTO路由策略修订号',
                                 `candidate_snapshot_hash` char(64) CHARACTER SET ascii COLLATE ascii_general_ci NULL DEFAULT NULL COMMENT 'AUTO候选模型快照SHA-256',
                                 `call_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'SUCCESS' COMMENT '调用状态',
                                 `request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '调用请求标识',
                                 `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '错误代码',
                                 `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '错误信息',
                                 `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
                                 `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                                 `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                                 `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                                 `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                                 PRIMARY KEY (`id`) USING BTREE,
                                 INDEX `idx_chat_message_session_seq`(`session_id`, `message_seq`) USING BTREE,
                                 INDEX `idx_chat_message_user_time`(`user_id`, `create_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '聊天消息表' ROW_FORMAT = DYNAMIC;

