INSERT INTO `chat_message` VALUES (2097277804252504066, 2097253705920929793, 1377, 40, '我是豆包，是字节跳动开发的人工智能助手。我可以陪你聊天、解答各种问题，还能帮你写文章、做翻译、出主意等等。有什么我可以帮到你的吗？随时告诉我哦！', 'assistant', 2092198049236996097, 641, 253, 388, 641, 'glm-5-2-260617', 'FIXED', NULL, NULL, NULL, NULL, 'SUCCESS', '210b408b-5ffc-4a54-be9c-c85d0401cd47', NULL, NULL, -1, -1, '2026-09-08 18:56:09', -1, '2026-09-08 18:56:09');
