INSERT INTO `chat_message` VALUES (2097277907923116035, 2097253705920929793, 1377, 42, '我是由智谱AI（Zhipu AI）训练的大语言模型，名为GLM。\n\n很高兴为你服务！有什么问题或者需要帮助的地方，尽管告诉我哦。', 'assistant', 2092198049236996097, 1105, 265, 840, 1105, 'glm-5-2-260617', 'FIXED', NULL, NULL, NULL, NULL, 'SUCCESS', 'c970cb6b-9aa8-4acd-8abd-e0f1d53faa86', NULL, NULL, -1, -1, '2026-09-08 18:56:33', -1, '2026-09-08 18:56:33');
