INSERT INTO `chat_message` VALUES (2097581074024079361, 2097571163865210881, 1377, 20, '我是字节跳动研发的人工智能，主要依托字节跳动在技术、数据和应用场景等方面的积累，致力于为用户提供自然语言交互、信息查询、内容创作辅助等多种服务。\n\n如果您有任何问题需要解答，或者有内容创作、日常交流等方面的需求，都可以告诉我，我会尽力为您提供帮助。', 'assistant', 2092197679865614337, 178, 103, 75, 178, 'doubao-seed-character-260628', 'FIXED', NULL, NULL, NULL, NULL, 'SUCCESS', '728d7f08-6dfb-4858-967a-0b196e0fcd51', NULL, NULL, -1, -1, '2026-09-09 15:01:14', -1, '2026-09-09 15:01:14');
