INSERT INTO `chat_message` VALUES (2101980365916323845, 2101974820845109249, 1377, 10, '根据提供的资料，公司的盈利预期如下：\n\n- **净利润预期**：预计公司 2026/2027/2028 年的净利润分别为 61.7/78.4/92.3 亿元，同比增加 353%/27%/18% [C1][C7]。资料中的损益表亦列出 2026F/2027F/2028F 预测净利润分别为 6176/7837/9229 百万元，同比增减 353.48%/26.90%/17.76% [C4][C11]。\n- **每股盈余（EPS）预期**：预计 2026/2027/2028 年的 EPS 分别为 3.0/3.84/4.53 元 [C1][C7]（表格中列出预测 EPS 分别为 3.030/3.844/4.527 元 [C4]）。\n- **市盈率（PE）预期**：A 股按当前价格计算，对应 2026/2027/2028 年的 PE 分别为 12.2/9.6/8.2 倍 [C1][C7]（表格中列出预测 PE 分别为 12.24/9.64/8.19 倍 [C4]）。\n- **投资建议**：建议买进 [C1][C7]。', 'assistant', 2092198049236996097, 5713, 4524, 1189, 5713, 'glm-5-2-260617', 'FIXED', 6, 'FIXED', NULL, NULL, 'SUCCESS', 'e39d1c55-0428-45ad-a984-c92a3a194f3a', NULL, NULL, -1, -1, '2026-09-21 18:22:27', -1, '2026-09-21 18:22:27');
