INSERT INTO `chat_message` VALUES (2101981999316713474, 2101974820845109249, 1377, 12, '根据提供的授权资料，公司基本信息如下 [C1]：\n\n- **产业别**：化工 [C1]\n- **A股价（2026/8/20）**：37.08 [C1]\n- **深证成指（2026/8/20）**：13972.78 [C1]\n- **股价12个月高/低**：64.98/19.68 [C1]\n- **总发行股数（百万）**：2038.56 [C1]\n- **A股数（百万）**：1509.01 [C1]\n- **A市值（亿元）**：559.54 [C1]\n- **主要股东**：徐金富 (34.27%) [C1]\n- **每股净值（元）**：9.95 [C1]\n- **股价/账面净值**：3.73 [C1]\n- **股价涨跌（%）**：一个月 -1.0，三个月 -28.3，一年 81.2 [C1]\n- **近期评等**：出刊日期 2026/5/27，前日收盘 51.99，评等 买进 [C1]\n- **产品组合**：锂电子电池材料 93.1%，日化材料 4.7% [C1]\n- **机构投资者占流通A股比例**：基金 21.1%，一般法人 6.2% [C1]', 'assistant', 2092198049236996097, 7094, 5277, 1817, 7094, 'glm-5-2-260617', 'FIXED', 6, 'FIXED', NULL, NULL, 'SUCCESS', '72f6a642-c3c3-4f1d-b1e7-fe51a2055715', NULL, NULL, -1, -1, '2026-09-21 18:28:56', -1, '2026-09-21 18:28:56');
