INSERT INTO `chat_message` VALUES (2102690874000932865, 2102602145542553602, 1377, 10, '您好！看您连续发了好几条，可能您现在比较着急。但是您**忘记告诉我具体的公司名称了**哦。\n\n请问您想查询的是**哪家公司**（以及位于哪个城市/哪个分公司）？\n\n您可以直接回复我公司的名字（例如：“腾讯深圳总部的地址和交通”），我会立刻为您提供详细的地址和交通路线！', 'assistant', 2092198049236996097, 577, 38, 539, 577, 'glm-5-2-260617', 'FIXED', 7, 'FIXED', NULL, NULL, 'SUCCESS', '06182179-af0e-4074-8af4-1c4b724c1d3c', NULL, NULL, -1, -1, '2026-09-23 17:25:45', -1, '2026-09-23 17:25:45');
INSERT INTO `chat_message` VALUES (2102691589016518657, 2102602145542553602, 1377, 11, '入职资料', 'user', 2092198049236996097, 0, 0, 0, 0, 'glm-5-2-260617', 'FIXED', 7, 'FIXED', NULL, NULL, 'SUCCESS', '16268a92-b3d0-41c5-b8e0-741438b871b5', NULL, NULL, -1, -1, '2026-09-23 17:28:36', -1, '2026-09-23 17:28:36');
INSERT INTO `chat_message` VALUES (2102691717026676738, 2102602145542553602, 1377, 12, '您好！您是准备入职新公司，想确认需要准备哪些**入职资料**吗？\n\n因为您没有提到具体是哪家公司，不同公司的要求可能会有所不同。不过，我可以为您提供一份**最通用、最常见的入职资料清单**供您参考和准备：\n\n**1. 身份与学历证明（必备）**\n*   身份证原件及正反面复印件（通常准备3-5份）。\n*   最高学历、学位证书原件及复印件。\n*   学信网《教育部学历证书电子注册备案表》（部分公司要求提供）。\n\n**2. 资历证明**\n*   上一家公司的《离职证明》原件（非常最重要，通常必须提供，如果是应届生或第一份工作则不需要）。\n*   相关的专业资格证书、职称证书原件及复印件（如适用）。\n\n**3. 财务与税务资料**\n*   本人名下银行卡复印件（需在复印件上写明开户行精确到支行的名称、卡号、本人签名。部分公司会要求特定银行）。\n*   一寸免冠白底或蓝底彩照（通常准备3-4张，用于制作工牌、档案等）。\n\n**4. 健康与体检**\n*   近期入职体检报告（通常要求近三个月内三甲医院或公司指定医院的体检报告，有些公司会在入职当天统一安排）。\n\n**5. 其他可能需要的资料**\n*   户口本复印件（户主页及本人页，有时用于办理社保、公积金）。\n*   紧急联系人信息表（公司通常会提供表格让您填写）。\n*   无犯罪记录证明（部分特殊行业或国企、外企可能会要求到户籍所在地派出所开具）。\n\n---\n\n**💡 核心建议：**\n最准确的做法是**直接查阅HR发给您的《Offer邮件》或《入职通知书》**，里面通常会有非常详细的清单。\n\n如果您是在某家特定公司遇到问题，或者想让我帮您解读HR发给您的入职邮件，可以直接把公司名称或邮件要求发给我，我来帮您具体分析！', 'assistant', 2092198049236996097, 1317, 117, 1200, 1317, 'glm-5-2-260617', 'FIXED', 7, 'FIXED', NULL, NULL, 'SUCCESS', '16268a92-b3d0-41c5-b8e0-741438b871b5', NULL, NULL, -1, -1, '2026-09-23 17:29:06', -1, '2026-09-23 17:29:06');
INSERT INTO `chat_message` VALUES (2102691769136709633, 2102602145542553602, 1377, 13, '麦娇奴的', 'user', 2092198049236996097, 0, 0, 0, 0, 'glm-5-2-260617', 'FIXED', 7, 'FIXED', NULL, NULL, 'SUCCESS', 'ea39b57f-4c6c-4a63-9f14-ab449f3a3f4a', NULL, NULL, -1, -1, '2026-09-23 17:29:19', -1, '2026-09-23 17:29:19');
INSERT INTO `chat_message` VALUES (2102691965702766595, 2102602145542553602, 1377, 14, '您好！您说的“麦娇奴”，通常是指**杭州麦娇奴服饰有限公司**（主营女装、服饰等）。结合您前面问的“地址交通”和“入职资料”，我为您整理了以下信息：\n\n### 一、 公司地址及交通\n麦娇奴的主要办公区和生产基地通常位于**浙江省杭州市**（具体多在余杭区、临平区或江干区等服装产业聚集地，且公司可能有多个厂区或办公区）。\n\n*   **具体地址**：因为企业的厂区或办公地点可能会有搬迁或分部，最准确的地址请您务必查看**HR发给您的Offer邮件**或**入职通知短信**。\n*   **交通建议**：\n    1.  **导航软件**：拿到具体地址后，直接在手机地图（高德地图/百度地图）搜索“麦娇奴（XX区XX路XX号）”。\n    2.  **公共交通**：杭州地铁和公交非常发达，地图软件会自动为您规划最快的公交/地铁路线。如果在余杭/临平一带，通常需要搭乘地铁9号线、1号线等再转公交或骑行。\n    3.  **自驾/打车**：可以直接定位到公司前台或门卫室。\n\n### 二、 入职资料准备（麦娇奴/服装企业通用版）\n针对服装/生产类企业，入职一般需要准备以下资料，建议您提前准备齐全：\n\n1.  **身份证明**：身份证原件及正反面复印件（建议准备3份）。\n2.  **学历证明**：最高学历毕业证原件及复印件。\n3.  **离职证明**：上一家公司的《解除/终止劳动合同证明》原件（应届生或首次工作无需提供，这是为了确保新公司不承担连带用工风险，非常重要）。\n4.  **银行卡**：杭州本地的银行卡复印件（通常要求四大行或杭州银行、招商银行等，具体看HR要求，并在复印件上写明卡号、开户行精确到支行、本人签名）。\n5.  **照片**：1寸或2寸免冠白底/蓝底彩照（通常准备4-6张，用于办理工牌、建档等）。\n6.  **体检报告**：部分岗位（尤其是工厂车间、餐饮等）会要求近三个月内的入职体检报告（通常要求区级及以上医院，包含常规检查）。\n7.  **其他**：如果是设计、打版等技术岗位，可能需要提供作品集或相关资格证书。\n\n---\n\n**💡 温馨提示**：\n由于不同分公司、不同岗位（如门店导购、办公室行政、工厂车间、电商运营）的具体要求会有差异，**强烈建议您**：\n1.  **翻看手机短信或邮箱**：寻找HR发送给您的“入职须知”或Offer邮件。\n2.  **主动联系HR**：直接发微信或打电话问您的招聘负责人：“您好，请问明天入职的具体集合地址是哪里？需要携带哪些原件和复印件？是否有指定的体检医院和银行卡要求？” 这样最稳妥，也能给HR留下做事靠谱的好印象！', 'assistant', 2092198049236996097, 2256, 563, 1693, 2256, 'glm-5-2-260617', 'FIXED', 7, 'FIXED', NULL, NULL, 'SUCCESS', 'ea39b57f-4c6c-4a63-9f14-ab449f3a3f4a', NULL, NULL, -1, -1, '2026-09-23 17:30:05', -1, '2026-09-23 17:30:05');
