INSERT INTO `chat_message` VALUES (2102695397646004226, 2102695309532065793, 1377, 2, '抱歉，我不知道您指的是哪家公司。作为一个人工智能助手，我无法获取您所在公司或您想联系的具体公司的内部联系方式。\n\n如果您能告诉我**具体的公司名称**，我可以尝试帮您在网上搜索一下该公司公开的联系方式。另外，您也可以通过以下途径获取前台电话：\n\n1. **公司官网**：通常在“联系我们”页面会有前台或客服电话。\n2. **地图软件**：在百度地图、高德地图等搜索公司名称，一般会有商家登记的电话。\n3. **内部工具**：如果是您自己的公司，可以查看员工手册、内部通讯录（如钉钉、企业微信）或直接询问身边的同事。', 'assistant', 2092198049236996097, 825, 16, 809, 825, 'glm-5-2-260617', 'FIXED', 7, 'FIXED', NULL, NULL, 'SUCCESS', '6b762cd4-71b3-4635-ae0f-60c725060eb9', NULL, NULL, -1, -1, '2026-09-23 17:43:44', -1, '2026-09-23 17:43:44');
