INSERT INTO `chat_message` VALUES (2102711503630757891, 2102695309532065793, 1377, 14, '之前为你提供的“0755-83825548”是深圳奇沃智联网络科技发展有限公司的前台电话（若你需要的是该公司的联系方式，可尝试拨打）。\n\n如果是其他公司的前台电话，由于不同公司的联系方式不同，建议你通过该公司官网的“联系我们”页面、官方客服渠道，或企查查、天眼查等企业信息平台查询对应公司的公开前台电话。', 'assistant', 2092197679865614337, 371, 271, 100, 371, 'doubao-seed-character-260628', 'AUTO', 18, 'DEFAULT_FALLBACK', 1, '9ef19a973cacaaca55bca6b8cdd59aaa7912d446fa166f368e32b2be97d681e9', 'SUCCESS', '2b34aaa9-a009-42a9-99a1-4a44ad61b1f2', NULL, NULL, -1, -1, '2026-09-23 18:47:44', -1, '2026-09-23 18:47:44');
