INSERT INTO `chat_message` VALUES (2102711690403115012, 2102695309532065793, 1377, 16, '该公司相关的交通信息如下：\n1. 公共交通：\n   - 地铁站点：车公庙站（G出口，1号线/7号线/9号线/11号线）、下沙站（C出口，9号线）、上沙站（A出口，7号线）[C15]；\n   - 公交站点：上沙 / 天安数码城 / 下沙① / 下沙② / 福田体育公园等[C15]。\n2. 自驾：园区内设有露天、地下停车场，需要办理停车月卡的同事，可联系人资行政管理中心开具在职证明后自行到天安管理处办理[C15]。\n\n资料中未提及公司地址的具体内容。', 'assistant', 2092197679865614337, 5725, 5567, 158, 5725, 'doubao-seed-character-260628', 'AUTO', 18, 'DEFAULT_FALLBACK', 1, '9ef19a973cacaaca55bca6b8cdd59aaa7912d446fa166f368e32b2be97d681e9', 'SUCCESS', 'c006efcc-0578-4e86-9bed-68ae8c32ab58', NULL, NULL, -1, -1, '2026-09-23 18:48:28', -1, '2026-09-23 18:48:28');
