INSERT INTO `chat_message` VALUES (2102943077823414275, 2102943044227039234, 1377, 2, '入职所需提交的资料包括：1.居民身份证；2.社保卡；3.最高学历毕业证原件；4.离职证明；5.入职体检证明（区以上公立医院一个月内的体检证明，体检机构和私人医院的报告不符合要求）；6.一寸相片两张；7.本人中国招商银行借记卡[C5]。入职一周内未及时、完整提供报到时所需提交的资料，将视为不符合试用期录用标准[C1]。若入职时已完整提交入职资料，可跳过相关补充说明页面[C2][C3]。', 'assistant', 2092197679865614337, 3350, 3229, 121, 3350, 'doubao-seed-character-260628', 'AUTO', 18, 'DEFAULT_FALLBACK', 1, '9ef19a973cacaaca55bca6b8cdd59aaa7912d446fa166f368e32b2be97d681e9', 'SUCCESS', 'd88e16db-f379-4e0d-bf3f-d24cbd64f30e', NULL, NULL, -1, -1, '2026-09-24 10:07:55', -1, '2026-09-24 10:07:55');
INSERT INTO `chat_message` VALUES (2102943322724630529, 2102943044227039234, 1377, 3, '入职资料补充说明', 'user', 2092197679865614337, 0, 0, 0, 0, 'doubao-seed-character-260628', 'AUTO', 18, 'DEFAULT_FALLBACK', 1, '9ef19a973cacaaca55bca6b8cdd59aaa7912d446fa166f368e32b2be97d681e9', 'SUCCESS', '911aa47f-fc15-4340-8ddf-3f8517d06a56', NULL, NULL, -1, -1, '2026-09-24 10:08:54', -1, '2026-09-24 10:08:54');
INSERT INTO `chat_message` VALUES (2102943347009650689, 2102943044227039234, 1377, 4, '入职资料补充说明如下：\n1. 若入职时已完整提交入职资料，可跳过此页[C5][C7]。\n2. 入职所需提交的资料：①居民身份证；②社保卡；③最高学历毕业证原件；④离职证明；⑤入职体检证明（区以上公立医院一个月内的体检证明，体检机构和私人医院的报告不符合要求）；⑥一寸相片两张；⑦本人中国招商银行借记卡[C15]。\n3. 入职一周内未及时、完整提供报到时所需提交的资料，将视为不符合试用期录用标准[C6]。\n4. 关于本人中国招商银行借记卡的补充：未办理过招商银行借记卡的同事，可联系HR开具在职证明后到天安园区内招商银行办理，该银行地址为天安数码城天祥大厦A座一楼（距公司约400米，中午可办理开卡业务）；银行卡办理完成后，应及时交到11楼人资行政管理中心复印、本人签字、留档；若手机号发生变更，应及时告知HR进行档案更新；若银行卡发生变更，应及时告知财务管理中心-林白，同时将新银行卡交到人资行政管理中心复印、本人签字、留档[C16]。', 'assistant', 2092197679865614337, 5260, 4995, 265, 5260, 'doubao-seed-character-260628', 'AUTO', 18, 'DEFAULT_FALLBACK', 1, '9ef19a973cacaaca55bca6b8cdd59aaa7912d446fa166f368e32b2be97d681e9', 'SUCCESS', '911aa47f-fc15-4340-8ddf-3f8517d06a56', NULL, NULL, -1, -1, '2026-09-24 10:08:59', -1, '2026-09-24 10:08:59');
