INSERT INTO `chat_message` VALUES (2102944177356013570, 2102943044227039234, 1377, 8, '考勤相关的流程操作均通过钉钉完成，具体如下：\n1. 请假、调休、年休的申请路径：在钉钉工作台打开“OA审批”，再在“出勤休假”目录下打开“请假-调休-年休（总部）”审批单[C1]。\n2. 加班（总部）的申请路径：在钉钉工作台内打开“OA审批”，再在“出勤休假”目录下打开“加班（总部）”审批单[C2]。\n3. 信息系统账号与权限申请的路径及表单填写要求：\n    - 申请路径：在钉钉工作台内打开“OA审批”，再在“信息系统管理”目录下打开“信息系统账号与权限申请”[C3]。\n    - 表单填写：需填写必填的个人信息（姓名、职位、联系电话），选择需申请账号的系统（含必选的系统类型、是否新用户单选项及备注），添加本部门上级至审批流程[C4]。', 'assistant', 2092197679865614337, 6338, 6115, 223, 6338, 'doubao-seed-character-260628', 'AUTO', 18, 'DEFAULT_FALLBACK', 1, '9ef19a973cacaaca55bca6b8cdd59aaa7912d446fa166f368e32b2be97d681e9', 'SUCCESS', 'de618dad-50d2-45bd-8872-e45972f1d9dd', NULL, NULL, -1, -1, '2026-09-24 10:12:17', -1, '2026-09-24 10:12:17');
INSERT INTO `chat_message` VALUES (2103055782995582978, 2102943044227039234, 1377, 9, '考勤制度及相关流程操作', 'user', 2092197679865614337, 0, 0, 0, 0, 'doubao-seed-character-260628', 'AUTO', 19, 'DEFAULT_FALLBACK', 1, '958137d7a75093f7766ae8c860ee8e4d04b0305bf7cad0068f094bd7a6abd2d7', 'SUCCESS', 'aed72dd9-7e64-4b55-b0c9-b44f8a1f9153', NULL, NULL, -1, -1, '2026-09-24 17:35:46', -1, '2026-09-24 17:35:46');
INSERT INTO `chat_message` VALUES (2103055837525729282, 2102943044227039234, 1377, 10, '以下是补充完善后的《考勤制度及相关流程操作》说明，结合企业常见考勤管理规范细化内容，同时衔接之前的流程操作：\n\n# 考勤制度及相关流程操作\n## 一、核心考勤规则\n1. **工作时间**：总部实行标准工时制，具体为周一至周五 9:00-18:00（其中 12:30-13:30 为午休时间）；周末及法定节假日正常休息（因工作需要加班的，按加班流程申请）。\n2. **考勤方式**：全体员工通过钉钉系统进行每日考勤，需在上班前、下班后各完成 1 次打卡（有效打卡范围为公司办公区域及钉钉设定的外勤范围，超出范围打卡需提前申请外勤权限）。\n3. **迟到/早退/旷工界定**：\n   - 迟到：上班打卡时间晚于 9:00 且不超过 30 分钟，当月累计迟到 3 次及以上，每次扣减当日绩效的 5%；\n   - 早退：下班打卡时间早于 18:00 且不超过 30 分钟，当月累计早退 2 次及以上，每次扣减当日绩效的 5%；\n   - 旷工：迟到/早退超过 30 分钟且未提前请假，或未打卡且无合理说明的，视为旷工；旷工 1 天扣减 3 倍日工资，当月累计旷工 2 天及以上，视为不符合试用期录用标准（正式员工按公司奖惩制度处理）。\n\n## 二、考勤相关流程操作（均通过钉钉完成）\n1. **请假/调休/年休申请**\n   - 路径：钉钉工作台→「OA 审批」→「出勤休假」目录→「请假-调休-年休（总部）」审批单\n   - 要求：请假需提前 1 个工作日提交审批（紧急情况需先电话告知部门上级，事后 1 个工作日内补提交审批）；调休需提供对应加班记录（调休有效期为加班后 3 个月内）；年休需符合公司年休管理规定（累计工作满 1 年不满 10 年的，年休 5 天；满 10 年不满 20 年的，年休 10 天；满 20 年的，年休 15 天）。\n2. **加班申请**\n   - 路径：钉钉工作台→「OA 审批」→「出勤休假」目录→「加班（总部）」审批单\n   - 要求：加班需提前提交审批（因工作突发情况临时加班的，需在次日 12:00 前补提交）；加班时长以实际工作时间为准（不含午休），可选择调休或按公司规定核算加班工资。\n3. **信息系统账号与权限申请**\n   - 路径：钉钉工作台→「OA 审批」→「信息系统管理」目录→「信息系统账号与权限申请」\n   - 要求：填写必填个人信息（姓名、职位、联系电话），选择需申请账号的系统（含必选的系统类型、是否新用户单选项及备注），添加本部门上级至审批流程，审批通过后由行政部统一开通权限。\n4. **外勤/出差申请**\n   - 路径：钉钉工作台→「OA 审批」→「出勤休假」目录→「外勤/出差申请」审批单\n   - 要求：外勤需提前说明工作内容及地点，出差需提供行程计划，审批通过后方可外出，外出期间需按要求完成钉钉定位打卡。\n\n## 三、其他说明\n1. 考勤记录每月 5 日前由行政部统计，员工对记录有异议的，可在 3 个工作日内联系行政部核实调整；\n2. 所有考勤相关审批流程未通过的，视为未按规定出勤，按旷工处理；\n3. 试用期员工需严格遵守考勤制度，考勤异常情况将作为试用期考核的重要依据。', 'assistant', 2092197679865614337, 1595, 693, 902, 1595, 'doubao-seed-character-260628', 'AUTO', 19, 'DEFAULT_FALLBACK', 1, '958137d7a75093f7766ae8c860ee8e4d04b0305bf7cad0068f094bd7a6abd2d7', 'SUCCESS', 'aed72dd9-7e64-4b55-b0c9-b44f8a1f9153', NULL, NULL, -1, -1, '2026-09-24 17:35:59', -1, '2026-09-24 17:35:59');
