INSERT INTO `chat_message` VALUES (2104813745221517314, 2104782589897838594, 1377, 8, '根据查询结果，北京（北京市）明天（2026-09-30）的天气预报如下：\n- 最高气温：19.9°C\n- 最低气温：14.3°C\n- 降水量：0mm\n- 最大风速：19.9km/h\n- 日出时间：06:09\n- 日落时间：17:59\n- 紫外线指数最大值：5.2\n- 天气代码：2（表示晴天）', 'assistant', 2092197679865614337, 11131, 10787, 344, 11131, 'doubao-seed-character-260628', 'AUTO', 21, 'TOOL_REQUIRED', 1, '0716ab82e00e4622212c88523f946d79717994c52cd633050b46084f84f90c57', 'SUCCESS', '42911537-37ef-4f05-ac72-ee390b98ea0c', NULL, NULL, -1, -1, '2026-09-29 14:01:17', -1, '2026-09-29 14:01:17');
