INSERT INTO `chat_message` VALUES (2104821259954667525, 2104817381112659970, 1377, 8, '请假流程如下：\n1. 操作路径：钉钉工作台打开“OA审批”，在“出勤休假”目录下打开“请假-调休-年休（总部）”审批单[C1]。\n2. 申请时间要求：\n   - 各类请假、调休、年休（病假除外）必须提前24小时提交申请，获批后方可正常休假[C5]；\n   - 总监级及以上员工原则上不得长时间请假（病假除外），各类请假（病假、特殊紧急情况除外）必须提前三天提交申请并获批后方视为有效；申请七天及以上的各类请假必须提前一个月提交申请经总经办获批后方视为有效[C5]；\n   - 如遇其他特殊情况需酌情提交申请并注明原因，经批准后方可生效[C5]。\n3. 违规处理：所有请假、调休申请如未审批通过，申请人已自行休假，均视为旷工处理[C5]。', 'assistant', 2092197679865614337, 6387, 6175, 212, 6387, 'doubao-seed-character-260628', 'AUTO', 21, 'SINGLE_CANDIDATE', 1, 'bc90681cdb396115a41b5247e9035a577c7f729a89a86bab4231722b98b11553', 'SUCCESS', '816b5181-e5a5-4038-9519-4a48d2d202b2', NULL, NULL, -1, -1, '2026-09-29 14:31:09', -1, '2026-09-29 14:31:09');
