INSERT INTO `chat_message` VALUES (2104827256454627333, 2104817381112659970, 1377, 16, '2026-09-30（明天）深圳的天气情况为：最高气温33.9℃，最低气温26.8℃，无降水，最大风速11.3km/h，日出时间为2026-09-30T06:14，日落时间为2026-09-30T18:12，最大紫外线指数为7.95，天气代码为1（对应晴天）。', 'assistant', 2092197679865614337, 22337, 21944, 393, 22337, 'doubao-seed-character-260628', 'AUTO', 21, 'SINGLE_CANDIDATE', 1, 'bc90681cdb396115a41b5247e9035a577c7f729a89a86bab4231722b98b11553', 'SUCCESS', '88e2aef4-aa8d-4bdd-a6d3-6380307d2aab', NULL, NULL, -1, -1, '2026-09-29 14:54:58', -1, '2026-09-29 14:54:58');
