INSERT INTO `chat_message` VALUES (2104827701692579845, 2104817381112659970, 1377, 18, '公司工作时间分为两种工作制：\n1. 双休工作制：上午9:30-12:30，下午14:00-19:00[C1]；\n2. 大小周工作制：上午9:30-12:30，下午14:00-18:30[C1]。\n另外加班时间从晚上20:00开始，半小时为单位计算[C1]。', 'assistant', 2092197679865614337, 5079, 4977, 102, 5079, 'doubao-seed-character-260628', 'AUTO', 21, 'SINGLE_CANDIDATE', 1, 'bc90681cdb396115a41b5247e9035a577c7f729a89a86bab4231722b98b11553', 'SUCCESS', '0543cb1f-195b-4039-a510-80af9543eac6', NULL, NULL, -1, -1, '2026-09-29 14:56:45', -1, '2026-09-29 14:56:45');

-- ----------------------------
-- Table structure for chat_message_citation
-- ----------------------------
DROP TABLE IF EXISTS `chat_message_citation`;
CREATE TABLE `chat_message_citation`  (
                                          `id` bigint NOT NULL COMMENT '引用记录主键',
                                          `message_id` bigint NOT NULL COMMENT '所属助手消息主键',
                                          `citation_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '回答内引用标识，如C1',
                                          `knowledge_id` bigint NOT NULL COMMENT '知识库主键快照',
                                          `index_version_id` bigint NOT NULL COMMENT '索引版本主键快照',
                                          `document_id` bigint NOT NULL COMMENT '文档主键快照',
                                          `document_version_id` bigint NOT NULL COMMENT '文档版本主键快照',
                                          `generation_id` bigint NOT NULL COMMENT 'Qdrant产物代次主键快照',
                                          `chunk_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '稳定片段标识',
                                          `content_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '片段正文SHA-256',
                                          `title` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '引用文档标题快照',
                                          `title_path_json` json NOT NULL COMMENT '结构标题路径JSON快照',
                                          `locator_json` json NOT NULL COMMENT '页码、段落、表格或图片位置JSON快照',
                                          `excerpt` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '回答时使用的片段摘要快照',
                                          `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
                                          `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                                          `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                                          `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                                          `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                                          PRIMARY KEY (`id`) USING BTREE,
                                          UNIQUE INDEX `uk_chat_citation_message_label`(`message_id`, `citation_id`) USING BTREE,
                                          INDEX `idx_chat_citation_knowledge`(`knowledge_id`, `message_id`) USING BTREE,
                                          INDEX `idx_chat_citation_source`(`index_version_id`, `generation_id`, `document_version_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'RAG聊天消息实际引用表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of chat_message_citation
-- ----------------------------
INSERT INTO `chat_message_citation` VALUES (2102711261799772165, 2102711261799772164, 'C9', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, '6197911e7e51acfeb5c47c9ac568c83b0ed2d566a284c1fef0c7caa002b8ac76', 'fc05413ec5b3065ddc071e9ee88ad2f4855f75b5035c5bd27174d16cae0046e9', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 5, \"slideNumber\": 3}', '文档：PowerPoint 演示文稿\n\n公司前台电话：0755-83825548', -1, -1, '2026-09-23 18:46:46', -1, '2026-09-23 18:46:46');
INSERT INTO `chat_message_citation` VALUES (2102711690403115013, 2102711690403115012, 'C15', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, '3fc0d8bffe086662f6b6aaa880f2b149906770a2c5a69a5137a65ad4909a1d34', 'c136fa94b269775ef0b2204b23d85b1088bfd142d1c5ce78a64a304e21f6fb42', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 2, \"slideNumber\": 3}', '文档：PowerPoint 演示文稿\n\n公共交通：\n1. 地铁站点：车公庙站（G出口，1号线/7号线/9号线/11号线）、下沙站（C出口，9号线）、上沙站（A出口，7号线）\n2. 公交站点：上沙 / 天安数码城 / 下沙① / 下沙② / 福田体育公园等。\n自驾：园区内设有露天、地下停车场，需要办理停车月卡的同事，可联系人资行政管理中心开具在职证明后自行到天安管理处办理。', -1, -1, '2026-09-23 18:48:28', -1, '2026-09-23 18:48:28');
INSERT INTO `chat_message_citation` VALUES (2102711835739942916, 2102711835739942915, 'C2', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, '6197911e7e51acfeb5c47c9ac568c83b0ed2d566a284c1fef0c7caa002b8ac76', 'fc05413ec5b3065ddc071e9ee88ad2f4855f75b5035c5bd27174d16cae0046e9', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 5, \"slideNumber\": 3}', '文档：PowerPoint 演示文稿\n\n公司前台电话：0755-83825548', -1, -1, '2026-09-23 18:49:03', -1, '2026-09-23 18:49:03');
