INSERT INTO `chat_message_citation` VALUES (2102943347009650692, 2102943347009650689, 'C15', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, '0e6fa2c1fbd3130aac2db0cd62521f71ae82e16b87e1bd6a45ba33d59e3b54b5', 'caefb2c66761778df9eef25cd7708d6f2eb963828cfc721e39008c911881af52', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 3, \"slideNumber\": 4}', '文档：PowerPoint 演示文稿\n\n1. 居民身份证\n2. 社保卡\n3. 最高学历毕业证原件\n4. 离职证明\n5. 入职体检证明（区以上公立医院一个月内的体验证明，体检机构和私人医院的报告为不符合要求）\n6. 一寸相片两张\n7. 本人中国招商银行借记卡', -1, -1, '2026-09-24 10:08:59', -1, '2026-09-24 10:08:59');
INSERT INTO `chat_message_citation` VALUES (2102943347009650693, 2102943347009650689, 'C6', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, 'cdc51fca8dedbab9fb6fe41fa4b525f1bf757998575ffdc8ed08db284d4402ae', 'be0bed087884cb1a186c6910c7949ee42591a06aa83b6b08929a51343b7572bd', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 2, \"slideNumber\": 4}', '文档：PowerPoint 演示文稿\n\n※ 入职一周内未及时、完整提供报到时所需提交的资料，将视为不符合试用期录用标准 ※\n入职所需提交的资料：', -1, -1, '2026-09-24 10:08:59', -1, '2026-09-24 10:08:59');
INSERT INTO `chat_message_citation` VALUES (2102943347009650694, 2102943347009650689, 'C16', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, '7594f1109678daa5b8bba2142284f23f000a702446f3cb7201b1932632024088', 'b4d51df87f8d45b15444ab1dd7dd66cd01304482a127aa2048c19f5f0fd4cde0', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 2, \"slideNumber\": 5}', '文档：PowerPoint 演示文稿\n\n· 未办理过招商银行借记卡的同事，可联系HR开具在职证明后到天安园区内招商银行办理，\n天安园区招商银行地址：天安数码城天祥大厦A座一楼 （距公司约400米，中午可办理开卡业务）；\n· 银行卡办理完成后，应及时交到11楼人资行政管理中心复印、本人签字、留档；\n· 若手机号发生变更，应及时告知HR进行档案更新；\n· 若银行卡发生变更，应及时告知财务管理中心-林白，同时将新银行卡交到人资行政管理中心复印、本人签字、留档。', -1, -1, '2026-09-24 10:08:59', -1, '2026-09-24 10:08:59');
INSERT INTO `chat_message_citation` VALUES (2102944177356013571, 2102944177356013570, 'C1', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, 'e3eb354d298c13b7e3429119611e11b5c8312a54b66aa8fb396974e93f7d4cc3', '06632811a17d7aed9dd50463eb792076760cd7aff57b0fd0289a8d1bfa525b17', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"IMAGE\", \"container\": \"PPTX\", \"endOffset\": null, \"mediaType\": \"image/png\", \"rowNumber\": null, \"sheetName\": null, \"imageIndex\": 9, \"pageNumber\": null, \"contentHash\": \"ed2076ebf23dc7178416603838cfecd449fbefd7a990af8fee12920d4c55072d\", \"slideNumber\": 8, \"startOffset\": null, \"columnNumber\": null}', '文档：PowerPoint 演示文稿\n表头：图片 2\n\n一、提取的可见文字\n1. 左侧导航栏文字：深圳麦娇...、消息、文档、工作台、通讯录、会议、钉盘、日历\n2. 顶部栏文字：微办公、OA审批\n3. OA审批页顶部导航文字：首页、跨组织审批、统计、插件中心、更多\n4. OA审批内容区文字：1、出勤休假 5、加班（总部）、出差（总部）、公出（总部）、请假-调休-年休（总部）、补卡申请\n5. 标注说明文字：①钉钉工作台打开“OA审批”、②“出勤休假”目录下打开“请假-调休-年休”审批单\n\n二、图表/界面结构、关键对象及关系\n该图为钉钉PC端界面操作指引图，界面分为左右两部分：\n1. 左侧是钉钉功能侧边栏，为纵向导航结构，包含消息、文档、工作台、通讯录、会议、钉盘、日历等功能入口，其中“工作台”被红框标注，是操作第一步的入口。\n2. 右侧是进入工作台后打开的“OA审批”页面，顶部有首页、跨组织审批、统计、插件中心、更多的横向导航栏；下方内容区划分为出勤休假等审批分类，出勤休假分类下包含5类审批申请项：加班（总部）、出差（总部）、公出（总部）、请假-调休-年休（总部）、补卡申请，其中“请假-调休-年休（总部）”被红框标注，是操作第二步的入口。\n3. 操作逻辑关系：第一步点击左侧侧边栏的“工作台”，进入后找到并打开“OA审批”；第二步在OA审批的“出勤休假”目录下，打开“请假-调休-年休”审批单。', -1, -1, '2026-09-24 10:12:17', -1, '2026-09-24 10:12:17');
INSERT INTO `chat_message_citation` VALUES (2102944177356013572, 2102944177356013570, 'C2', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, '2da01f55842dbe0117b3caad9ef23a4352701c0ee486cc6f9662e4d019d35ffb', 'bea6f78733209691e33d5f50b4f7aa0071b7a37386a89eed3b0f91f5424a3baf', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"IMAGE\", \"container\": \"PPTX\", \"endOffset\": null, \"mediaType\": \"image/png\", \"rowNumber\": null, \"sheetName\": null, \"imageIndex\": 7, \"pageNumber\": null, \"contentHash\": \"581d46a4857937abf73fa8677fd68063dd5d701db873e191e890dc495769f3c2\", \"slideNumber\": 7, \"startOffset\": null, \"columnNumber\": null}', '文档：PowerPoint 演示文稿\n表头：图片 5\n\n### 提取的可见文字\n#### 界面原有文字\n左侧导航栏：深圳麦娇...、消息、文档、工作台、通讯录、会议、钉盘、日历、待办\n顶部栏：微办公、OA审批、首页、审批中心、跨组织审批、统计、插件中心\n右侧内容区：全部审批单、常用 2、1、出勤休假 5、加班（总部）、出差（总部）、2.1、事务审批 10\n\n#### 标注说明文字\n①钉钉工作台内打开“OA审批”\n②“出勤休假”目录下打开“加班”审批单\n\n### 界面结构与关键对象说明\n该图是钉钉软件的操作指引截图，用于演示提交加班审批单的前两步操作，整体分为左右两个区域：\n1. 左侧功能导航栏：为钉钉的主导航栏，包含消息、文档、工作台等功能入口，其中“工作台”选项被红色方框标注，是操作的第一步入口。\n2. 右侧内容区：是进入工作台后打开的“OA审批”页面，顶部为OA审批的导航栏，包含首页、审批中心等选项；页面内展示审批单分类，其中“出勤休假”分类下的“加班（总部）”选项被红色方框标注，是操作的第二步入口。\n3. 操作指引关系：通过红色箭头和序号标注，明确操作流程为：先点击左侧导航栏的“工作台”，在工作台内找到并打开“OA审批”应用，再在OA审批的“出勤休假”目录下打开“加班（总部）”审批单。', -1, -1, '2026-09-24 10:12:17', -1, '2026-09-24 10:12:17');
INSERT INTO `chat_message_citation` VALUES (2102944177418928130, 2102944177356013570, 'C3', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, 'be11c31f6a116729e4267dcb2bbc9dd0414080bbf8371f552f8a423f4a94ee77', 'bcb4f0492187f2ecf8babbde0c209677eed7cdaafa81084f35b06634d456d7c2', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"IMAGE\", \"container\": \"PPTX\", \"endOffset\": null, \"mediaType\": \"image/png\", \"rowNumber\": null, \"sheetName\": null, \"imageIndex\": 14, \"pageNumber\": null, \"contentHash\": \"84d3fbfc99a9ed77c11cde0ecc53088a85583ec8fc6a40375b8285a312682b22\", \"slideNumber\": 12, \"startOffset\": null, \"columnNumber\": null}', '文档：PowerPoint 演示文稿\n表头：图片 1\n\n### 可见文字\n顶部区域：\n左上角：深圳麦娇…\n顶部标签：微办公、OA审批\n左侧导航栏：消息、文档、工作台、通讯录、会议、钉盘、日历、待办\n右侧OA审批页面顶部导航：首页、审批中心（角标84）、跨组织审批、统计、插件中心、更多\n信息系统管理分类（右上角角标9）下的功能项：\n信息系统账号与权限申请、固定资产编号、IT物品和笔记本借用单\n业务系统需求反馈、跨境访问申请、IT系统培训申请\nIT设备维修管理流程、电脑共享文件申请、公众平台账号注册或权限申请\n标注说明文字：\n①钉钉工作内打开“OA审批”\n②“信息系统管理”目录下打开“信息系统账号与权限申请”\n4、信息系统管理 9\n\n### 图表/结构/关键对象说明\n这是一张钉钉操作指引截图，用于说明申请信息系统账号与权限的操作路径：\n1.  界面整体分为左侧钉钉主导航栏、右侧OA审批功能页两部分。\n2.  操作路径共2步：\n    - 第一步：在钉钉的工作台模块中，进入OA审批应用；\n    - 第二步：在OA审批的“信息系统管理”分类下，找到并打开“信息系统账号与权限申请”功能。\n3.  图中用红色框分别标注了关键操作入口：左侧导航的“工作台”、OA审批内的“信息系统管理”分类及下属的“信息系统账号与权限申请”项，并用红色箭头串联操作逻辑。\n4.  OA审批页的信息系统管理分类下共包含9个IT相关审批/申请类功能，除标注的功能外，还涵盖资产、借用、需求反馈、访问申请、培训、设备维修、文件共享、公众平台账号等相关事项。', -1, -1, '2026-09-24 10:12:17', -1, '2026-09-24 10:12:17');
INSERT INTO `chat_message_citation` VALUES (2102944177423122434, 2102944177356013570, 'C4', 2102694570000773121, 2102694648803356673, 2102694748522934273, 2102694748648763394, 2102694748711677954, '0d2275809ebd7e292b559fcfe5f8e27f13481befa455fc573a7d3eb308d454f9', '4217a1077dcb8035bee047541ac2abfede5524fa6feb82b2da3d5b39cb6bdfb7', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"IMAGE\", \"container\": \"PPTX\", \"endOffset\": null, \"mediaType\": \"image/png\", \"rowNumber\": null, \"sheetName\": null, \"imageIndex\": 16, \"pageNumber\": null, \"contentHash\": \"aa7696b5cceb6a58c11d2efbd81f23b7fd9f6dd3c0b6a222f348327ef5836ac8\", \"slideNumber\": 13, \"startOffset\": null, \"columnNumber\": null}', '文档：PowerPoint 演示文稿\n表头：图片 1\n\n## 提取的可见文字\n页面标题：信息系统账号与权限申请\n所属公司：深圳麦娇奴服饰有限公司\n表单字段及相关说明：\n1. 填写个人信息（对应字段均为必填项，标有*）：\n   - *姓名：输入框提示文字“请输入”\n   - *职位：输入框提示文字“请输入”\n   - *联系电话：输入框提示文字“请输入数字”\n2. 选择需要申请账号的系统：\n   - *系统类型：选择框提示文字“请选择”\n   - 是否新用户：单选选项，包含“是”“否”两个选项\n   - 备注：输入框提示文字“请输入”\n3. 添加本部门上级至审批流程：\n   - *部门领导：操作按钮为“+ 添加”\n\n## 图表/结构描述\n该图为信息系统账号与权限申请表单页面，整体为纵向表单结构，顶部为表单标题与所属公司名称，下方按功能分为三个部分：\n1. 第一部分为个人信息填写区，包含3个必填文本输入项，区域左侧用红色方框标注，右侧配有红色标注文字“①填写个人信息”；\n2. 第二部分为申请系统选择区，包含1个必选下拉选择项、1组单选项、1个文本输入项，区域右侧配有红色标注文字“②选择需要申请账号的系统”；\n3. 第三部分为审批流程配置区，包含1个必填的人员添加项，区域右侧配有红色标注文字“③添加本部门上级至审批流程”。\n所有必填字段前均标注红色星号，输入类控件均有占位提示文字，清晰展示了该申请表单的填写步骤与所需填写内容。', -1, -1, '2026-09-24 10:12:17', -1, '2026-09-24 10:12:17');
INSERT INTO `chat_message_citation` VALUES (2104821259954667526, 2104821259954667525, 'C1', 2104814417803329538, 2104814528012861441, 2104815932865626114, 2104815933117284353, 2104815933247307779, '8343a8cddbe7eda99dee30c9b040d8dc5ba343b977d994b5101dba23e6d0c4c5', '88058ea8c60db0ce87b6542647f5440acefa7196ed9b9dfe5b104ae700e2b0e3', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"IMAGE\", \"container\": \"PPTX\", \"endOffset\": null, \"mediaType\": \"image/png\", \"rowNumber\": null, \"sheetName\": null, \"imageIndex\": 9, \"pageNumber\": null, \"contentHash\": \"ed2076ebf23dc7178416603838cfecd449fbefd7a990af8fee12920d4c55072d\", \"slideNumber\": 8, \"startOffset\": null, \"columnNumber\": null}', '文档：PowerPoint 演示文稿\n表头：图片 2\n\n### 提取的文字内容\n左侧导航栏文字（从上到下）：\n深圳麦娇...、消息、文档、工作台、通讯录、会议、钉盘、日历\n顶部栏文字：\n微办公、OA审批、首页、审批中心64、跨组织审批、统计、插件中心、更多\n主内容区文字：\n1、出勤休假 5\n加班（总部）、出差（总部）、公出（总部）\n请假-调休-年休（总部）、补卡申请\n标注文字：\n①钉钉工作台打开“OA审批”\n②“出勤休假”目录下打开“请假-调休-年休”审批单\n\n### 图表结构与关键对象描述\n该图是钉钉操作步骤指引图，用于演示提交请假类OA审批的操作路径，整体结构分为左右两部分：\n1. 左侧为钉钉客户端侧边导航栏，共包含9个功能入口，其中「工作台」选项被红框标注，箭头从该选项指向右侧页面，是操作的第一步入口。\n2. 右侧为钉钉工作台内的「OA审批」页面：\n    - 顶部是OA审批的导航栏，包含首页、审批中心（带未读数字标识64）、跨组织审批、统计、插件中心、更多选项，「OA审批」标题被红色箭头指向，对应第一步操作目标。\n    - 主内容区为「出勤休假」分类（共5个审批项），包含加班（总部）、出差（总部）、公出（总部）、请假-调休-年休（总部）、补卡申请5个审批入口；其中「请假-调休-年休（总部）」被红框标注，是第二步操作的目标对象。\n3. 关键操作逻辑：操作路径为从左侧导航栏进入工作台→在工作台打开OA审批应用→在OA审批的出勤休假分类中找到并打开“请假-调休-年休”审批单，图中通过红框、红色箭头、编号标注明确了两步操作的先后顺序与对应对象。', -1, -1, '2026-09-29 14:31:09', -1, '2026-09-29 14:31:09');
INSERT INTO `chat_message_citation` VALUES (2104821260017582081, 2104821259954667525, 'C5', 2104814417803329538, 2104814528012861441, 2104815932865626114, 2104815933117284353, 2104815933247307779, 'a4af46cc1ffb376484b7976766572d0dc3d79d183a4c6496bd94d28cbe7341e1', 'ebd53e89a4e5574ce3e5e6b908fcdf38e06148ee15ebeb52ff01e3c452161d94', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 3, \"slideNumber\": 6}', '文档：PowerPoint 演示文稿\n\n① 各类请假、调休、年休（病假除外）必须提前24小时提交申请，获批后方可正常休假；\n② 所有请假、调休申请如未审批通过，申请人已自行休假，均视为旷工处理；\n③ 总监级及以上员工原则上不得长时间请假（病假除外），各类请假（病假、特殊紧急情况除外）必须提前三天提交申请并获批后方视为有效，申请人方可正常休假。如有申请七天及以上的各类请假必须提前一个月提交申请经总经办获批后方视为有效，申请人方可正常休假；\n④ 如遇其他特殊情况需酌情提交申请并注明原因，经批准后方可生效。', -1, -1, '2026-09-29 14:31:09', -1, '2026-09-29 14:31:09');
INSERT INTO `chat_message_citation` VALUES (2104823415784980486, 2104823415784980485, 'C1', 2104814417803329538, 2104814528012861441, 2104815932865626114, 2104815933117284353, 2104815933247307779, '8343a8cddbe7eda99dee30c9b040d8dc5ba343b977d994b5101dba23e6d0c4c5', '88058ea8c60db0ce87b6542647f5440acefa7196ed9b9dfe5b104ae700e2b0e3', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"IMAGE\", \"container\": \"PPTX\", \"endOffset\": null, \"mediaType\": \"image/png\", \"rowNumber\": null, \"sheetName\": null, \"imageIndex\": 9, \"pageNumber\": null, \"contentHash\": \"ed2076ebf23dc7178416603838cfecd449fbefd7a990af8fee12920d4c55072d\", \"slideNumber\": 8, \"startOffset\": null, \"columnNumber\": null}', '文档：PowerPoint 演示文稿\n表头：图片 2\n\n### 提取的文字内容\n左侧导航栏文字（从上到下）：\n深圳麦娇...、消息、文档、工作台、通讯录、会议、钉盘、日历\n顶部栏文字：\n微办公、OA审批、首页、审批中心64、跨组织审批、统计、插件中心、更多\n主内容区文字：\n1、出勤休假 5\n加班（总部）、出差（总部）、公出（总部）\n请假-调休-年休（总部）、补卡申请\n标注文字：\n①钉钉工作台打开“OA审批”\n②“出勤休假”目录下打开“请假-调休-年休”审批单\n\n### 图表结构与关键对象描述\n该图是钉钉操作步骤指引图，用于演示提交请假类OA审批的操作路径，整体结构分为左右两部分：\n1. 左侧为钉钉客户端侧边导航栏，共包含9个功能入口，其中「工作台」选项被红框标注，箭头从该选项指向右侧页面，是操作的第一步入口。\n2. 右侧为钉钉工作台内的「OA审批」页面：\n    - 顶部是OA审批的导航栏，包含首页、审批中心（带未读数字标识64）、跨组织审批、统计、插件中心、更多选项，「OA审批」标题被红色箭头指向，对应第一步操作目标。\n    - 主内容区为「出勤休假」分类（共5个审批项），包含加班（总部）、出差（总部）、公出（总部）、请假-调休-年休（总部）、补卡申请5个审批入口；其中「请假-调休-年休（总部）」被红框标注，是第二步操作的目标对象。\n3. 关键操作逻辑：操作路径为从左侧导航栏进入工作台→在工作台打开OA审批应用→在OA审批的出勤休假分类中找到并打开“请假-调休-年休”审批单，图中通过红框、红色箭头、编号标注明确了两步操作的先后顺序与对应对象。', -1, -1, '2026-09-29 14:39:43', -1, '2026-09-29 14:39:43');
INSERT INTO `chat_message_citation` VALUES (2104823415784980487, 2104823415784980485, 'C3', 2104814417803329538, 2104814528012861441, 2104815932865626114, 2104815933117284353, 2104815933247307779, 'a4af46cc1ffb376484b7976766572d0dc3d79d183a4c6496bd94d28cbe7341e1', 'ebd53e89a4e5574ce3e5e6b908fcdf38e06148ee15ebeb52ff01e3c452161d94', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 3, \"slideNumber\": 6}', '文档：PowerPoint 演示文稿\n\n① 各类请假、调休、年休（病假除外）必须提前24小时提交申请，获批后方可正常休假；\n② 所有请假、调休申请如未审批通过，申请人已自行休假，均视为旷工处理；\n③ 总监级及以上员工原则上不得长时间请假（病假除外），各类请假（病假、特殊紧急情况除外）必须提前三天提交申请并获批后方视为有效，申请人方可正常休假。如有申请七天及以上的各类请假必须提前一个月提交申请经总经办获批后方视为有效，申请人方可正常休假；\n④ 如遇其他特殊情况需酌情提交申请并注明原因，经批准后方可生效。', -1, -1, '2026-09-29 14:39:43', -1, '2026-09-29 14:39:43');
INSERT INTO `chat_message_citation` VALUES (2104823502196031493, 2104823502196031492, 'C1', 2104814417803329538, 2104814528012861441, 2104815932865626114, 2104815933117284353, 2104815933247307779, 'd76ef1ee62de005fe9f40c1a3e5c0da79df1f1675fa6de8c2ad359e67c861a4c', 'fc05413ec5b3065ddc071e9ee88ad2f4855f75b5035c5bd27174d16cae0046e9', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 5, \"slideNumber\": 3}', '文档：PowerPoint 演示文稿\n\n公司前台电话：0755-83825548', -1, -1, '2026-09-29 14:40:03', -1, '2026-09-29 14:40:03');
INSERT INTO `chat_message_citation` VALUES (2104827701755494401, 2104827701692579845, 'C1', 2104814417803329538, 2104814528012861441, 2104815932865626114, 2104815933117284353, 2104815933247307779, '2a0309edc0a83fc6ae593a911f63dad0ed0529938ef10f3fe6cb4d2b3a38b3e6', '461cc3acf98ea280a44eb5edb661e72dc72425c58d6eb78572598253dc35ff1e', 'PowerPoint 演示文稿', '[]', '{\"kind\": \"PRESENTATION_BLOCK\", \"rowIndex\": null, \"container\": \"PPTX\", \"shapeIndex\": 2, \"slideNumber\": 6}', '文档：PowerPoint 演示文稿\n\n1. 工作时间：① 双休工作制：上午 9:30-12:30，下午 14:00-19:00；\n② 大小周工作制：上午 9:30-12:30，下午 14:00-18:30；\n加班时间从晚上 20:00 开始，半小时为单位计算；\n2. 打卡：① 每天上班打卡 2 次（上、下班各1次，包括请假 / 调休但部分时间有出勤的以及出差、公出）；\n② 2 种打卡方式：前台考勤机人脸识别打卡、手机钉钉人脸识别打卡；\n③ 请务必确保在公出 / 出差前，提交并跟进公出单 / 出差单审批完成（总监级及以上员工除外），审批完成后在外即可正常打卡。\n3. 请假-调休-年休：', -1, -1, '2026-09-29 14:56:45', -1, '2026-09-29 14:56:45');

-- ----------------------------
-- Table structure for chat_session
-- ----------------------------
DROP TABLE IF EXISTS `chat_session`;
CREATE TABLE `chat_session`  (
                                 `id` bigint NOT NULL COMMENT '主键',
                                 `user_id` bigint NULL DEFAULT NULL COMMENT '用户id',
                                 `session_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会话标题',
                                 `agent_id` bigint NULL DEFAULT NULL COMMENT '智能体ID',
                                 `model_id` bigint NULL DEFAULT NULL COMMENT '最近使用模型ID',
                                 `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ACTIVE' COMMENT '会话状态',
                                 `last_message_at` datetime(0) NULL DEFAULT NULL COMMENT '最后消息时间',
                                 `message_count` int NOT NULL DEFAULT 0 COMMENT '消息数量',
                                 `input_tokens` bigint NOT NULL DEFAULT 0 COMMENT '累计输入 Token 数',
                                 `output_tokens` bigint NOT NULL DEFAULT 0 COMMENT '累计输出 Token 数',
                                 `deduct_tokens` bigint NOT NULL DEFAULT 0 COMMENT '累计扣减 Token 数',
                                 `create_dept` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '部门',
                                 `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                                 `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                                 `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                                 `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                                 `conversation_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '会话ID',
                                 PRIMARY KEY (`id`) USING BTREE,
                                 INDEX `idx_chat_session_user_status_time`(`user_id`, `status`, `last_message_at`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '会话管理' ROW_FORMAT = DYNAMIC;

