-- ----------------------------
-- Table structure for knowledge_acl
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_acl`;
CREATE TABLE `knowledge_acl`  (
                                  `id` bigint NOT NULL,
                                  `knowledge_id` bigint NOT NULL,
                                  `subject_type` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'USER/ROLE',
                                  `subject_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
                                  `permission` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'READ/WRITE/MANAGE',
                                  `include_children` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '部门授权是否包含下级：0否1是',
                                  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0',
                                  `effective_time` datetime(0) NULL DEFAULT NULL COMMENT '生效时间',
                                  `expire_time` datetime(0) NULL DEFAULT NULL COMMENT '失效时间',
                                  `create_dept` bigint NULL DEFAULT NULL,
                                  `create_by` bigint NULL DEFAULT NULL,
                                  `create_time` datetime(0) NULL DEFAULT NULL,
                                  `update_by` bigint NULL DEFAULT NULL,
                                  `update_time` datetime(0) NULL DEFAULT NULL,
                                  PRIMARY KEY (`id`) USING BTREE,
                                  UNIQUE INDEX `uk_knowledge_acl`(`knowledge_id`, `subject_type`, `subject_id`) USING BTREE,
                                  INDEX `idx_knowledge_acl_subject`(`subject_type`, `subject_id`, `status`) USING BTREE,
                                  INDEX `idx_knowledge_acl_time`(`knowledge_id`, `status`, `effective_time`, `expire_time`) USING BTREE,
                                  INDEX `idx_knowledge_acl_access`(`status`, `subject_type`, `subject_id`, `effective_time`, `expire_time`, `knowledge_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '知识库资源ACL' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of knowledge_acl
-- ----------------------------

-- ----------------------------
-- Table structure for knowledge_artifact_generation
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_artifact_generation`;
CREATE TABLE `knowledge_artifact_generation`  (
                                                  `generation_id` bigint NOT NULL COMMENT 'Python 技术产物批次ID',
                                                  `job_id` bigint NOT NULL COMMENT '解析任务ID',
                                                  `attempt_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Kafka 执行批次',
                                                  `knowledge_id` bigint NOT NULL,
                                                  `index_version_id` bigint NOT NULL COMMENT 'knowledge_index_version.id',
                                                  `document_id` bigint NOT NULL,
                                                  `document_version_id` bigint NOT NULL,
                                                  `manifest_oss_id` bigint NOT NULL COMMENT '不可变清单 OSS ID',
                                                  `manifest_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
                                                  `manifest_size` bigint NOT NULL,
                                                  `config_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
                                                  `source_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
                                                  `vector_dimensions` int NOT NULL,
                                                  `vision_vector_dimensions` int NULL DEFAULT NULL COMMENT '图片视觉稠密向量维度；纯文本或无图片产物为空',
                                                  `chunk_count` int NOT NULL,
                                                  `dense_count` int NULL DEFAULT NULL,
                                                  `sparse_count` int NULL DEFAULT NULL,
                                                  `vision_count` int NULL DEFAULT NULL COMMENT '图片片段视觉向量写入数量',
                                                  `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'UPLOADED/READY/ORPHANED',
                                                  `create_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0),
                                                  `update_time` datetime(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0),
                                                  `cleanup_after` datetime(0) NULL DEFAULT NULL COMMENT '允许清理Qdrant和OSS清单的时间',
                                                  `cleaned_at` datetime(0) NULL DEFAULT NULL COMMENT 'Qdrant与OSS清单均清理完成时间',
                                                  `cleanup_error` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '最近一次清理失败摘要',
                                                  PRIMARY KEY (`generation_id`) USING BTREE,
                                                  UNIQUE INDEX `uk_knowledge_artifact_attempt`(`job_id`, `attempt_id`) USING BTREE,
                                                  INDEX `idx_knowledge_artifact_document`(`document_version_id`, `status`) USING BTREE,
                                                  INDEX `idx_knowledge_artifact_cleanup`(`status`, `update_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '知识库不可变技术产物批次' ROW_FORMAT = Dynamic;

