-- ----------------------------
-- Table structure for knowledge_document_version
-- ----------------------------
DROP TABLE IF EXISTS `knowledge_document_version`;
CREATE TABLE `knowledge_document_version`  (
                                               `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文档版本ID',
                                               `document_id` bigint NOT NULL COMMENT '逻辑文档ID',
                                               `knowledge_id` bigint NOT NULL COMMENT '知识库ID',
                                               `version_no` int NOT NULL COMMENT '文档版本号',
                                               `oss_id` bigint NOT NULL COMMENT 'sys_oss文件ID',
                                               `original_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '原始文件名',
                                               `file_suffix` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '文件后缀',
                                               `mime_type` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'MIME类型',
                                               `file_size` bigint NULL DEFAULT NULL COMMENT '文件大小字节',
                                               `file_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'SHA-256',
                                               `target_index_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '本处理配置绑定的目标索引版本',
                                               `configuration_revision` int NOT NULL DEFAULT 1 COMMENT '文档处理配置修订号',
                                               `processing_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'TEXT' COMMENT 'TEXT/MULTIMODAL',
                                               `text_embedding_profile_id` bigint NULL DEFAULT NULL COMMENT '文本Embedding Profile ID',
                                               `text_embedding_profile_revision` int NULL DEFAULT NULL COMMENT '文本Embedding发布修订',
                                               `multimodal_embedding_profile_id` bigint NULL DEFAULT NULL COMMENT '多模态Embedding Profile ID',
                                               `multimodal_embedding_profile_revision` int NULL DEFAULT NULL COMMENT '多模态Embedding发布修订',
                                               `vision_profile_id` bigint NULL DEFAULT NULL COMMENT 'OCR/视觉处理Profile ID',
                                               `vision_profile_revision` int NULL DEFAULT NULL COMMENT 'OCR/视觉处理发布修订',
                                               `rerank_mode` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' COMMENT 'PROFILE/NONE',
                                               `text_rerank_profile_id` bigint NULL DEFAULT NULL COMMENT '文本Rerank Profile ID',
                                               `text_rerank_profile_revision` int NULL DEFAULT NULL COMMENT '文本Rerank发布修订',
                                               `multimodal_rerank_profile_id` bigint NULL DEFAULT NULL COMMENT '多模态Rerank Profile ID',
                                               `multimodal_rerank_profile_revision` int NULL DEFAULT NULL COMMENT '多模态Rerank发布修订',
                                               `document_processing_snapshot` json NULL COMMENT '文档版本不可变处理与查询路由快照',
                                               `parse_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING/PROCESSING/READY/FAILED/DISABLED/DELETED',
                                               `parse_error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
                                               `parse_error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
                                               `parsed_at` datetime(0) NULL DEFAULT NULL,
                                               `create_dept` bigint NULL DEFAULT NULL,
                                               `create_by` bigint NULL DEFAULT NULL,
                                               `create_time` datetime(0) NULL DEFAULT NULL,
                                               `update_by` bigint NULL DEFAULT NULL,
                                               `update_time` datetime(0) NULL DEFAULT NULL,
                                               PRIMARY KEY (`id`) USING BTREE,
                                               UNIQUE INDEX `uk_document_version_no`(`document_id`, `version_no`) USING BTREE,
                                               INDEX `idx_document_version_knowledge`(`knowledge_id`, `parse_status`) USING BTREE,
                                               INDEX `idx_document_version_oss`(`oss_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104815933117284353 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '知识库文档版本' ROW_FORMAT = Dynamic;

