                                   `access_scope` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ACL_ONLY' COMMENT 'ALL_INTERNAL/ACL_ONLY',
                                   `description` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '知识库描述',
                                   `splitter_config` json NULL COMMENT '切片配置快照',
                                   `retrieval_config` json NULL COMMENT '知识库检索和重排配置',
                                   `current_index_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前生效索引版本',
                                   `permission_revision` int NOT NULL DEFAULT 1 COMMENT '权限修订号',
                                   `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '0正常 1停用',
