                                   INDEX `idx_knowledge_access_status`(`access_scope`, `status`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 2104814417803329538 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '知识库' ROW_FORMAT = DYNAMIC;

