                                        `knowledge_id` bigint NOT NULL,
                                        `document_id` bigint NULL DEFAULT NULL COMMENT '逻辑文档ID',
                                        `document_version_id` bigint NULL DEFAULT NULL COMMENT '文档版本ID',
                                        `attach_id` bigint NULL DEFAULT NULL,
                                        `target_index_version` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
                                        `idempotency_key` varchar(160) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务幂等键',
                                        `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
                                        `list_hidden` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '是否从管理列表隐藏：0否1是',
                                        `progress` int NOT NULL DEFAULT 0,
                                        `attempt_count` int NOT NULL DEFAULT 0,
                                        `max_attempts` int NOT NULL DEFAULT 3,
                                        `last_sequence` bigint NOT NULL DEFAULT 0,
                                        `lease_owner` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Python领取者',
                                        `lease_expire_time` datetime(0) NULL DEFAULT NULL COMMENT '任务租约到期时间',
                                        `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
                                        `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL,
                                        `started_at` datetime(0) NULL DEFAULT NULL,
                                        `finished_at` datetime(0) NULL DEFAULT NULL,
                                        `create_dept` bigint NULL DEFAULT NULL,
                                        `create_by` bigint NULL DEFAULT NULL,
                                        `create_time` datetime(0) NULL DEFAULT NULL,
                                        `update_by` bigint NULL DEFAULT NULL,
                                        `update_time` datetime(0) NULL DEFAULT NULL,
                                        `attempt_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '当前 Kafka 执行批次',
                                        `generation_id` bigint NULL DEFAULT NULL COMMENT '当前产物批次',
                                        `last_result_hash` char(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '已接受序列的结果摘要',
                                        `index_snapshot` json NULL COMMENT '浠诲姟缁戝畾鐨勫畬鏁碔ndexSnapshot',
                                        `document_processing_snapshot` json NULL COMMENT '任务首次固化的文档处理快照',
                                        `rerank_snapshot` json NULL COMMENT '浠诲姟缁戝畾鐨勫彲閫塕erank蹇収',
                                        `parent_job_id` bigint NULL DEFAULT NULL COMMENT 'REBUILD父任务ID，普通任务为空',
                                        `task_payload` json NULL COMMENT 'CLEANUP或RECONCILE冻结任务参数',
                                        `budget_account_id` bigint NULL DEFAULT NULL COMMENT '本次执行使用的Token额度账户ID',
                                        `budget_reserved_tokens` bigint NOT NULL DEFAULT 0 COMMENT '本次执行已预占Token数量',
                                        `execution_budget_tokens` int NULL DEFAULT NULL COMMENT '下发Python的本次模型Token硬上限',
                                        `budget_status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' COMMENT '预算状态：NONE、RESERVED、SETTLING、SETTLED',
                                        PRIMARY KEY (`id`) USING BTREE,
                                        UNIQUE INDEX `uk_knowledge_job_request`(`request_id`) USING BTREE,
                                        UNIQUE INDEX `uk_knowledge_job_idempotency`(`idempotency_key`) USING BTREE,
                                        INDEX `idx_knowledge_job_status`(`knowledge_id`, `status`, `create_time`) USING BTREE,
                                        INDEX `idx_knowledge_job_attach`(`attach_id`, `status`) USING BTREE,
                                        INDEX `idx_knowledge_job_lease`(`status`, `lease_expire_time`) USING BTREE,
                                        INDEX `idx_knowledge_job_document_version_time`(`document_version_id`, `create_time`, `id`) USING BTREE,
                                        INDEX `idx_knowledge_job_document_time`(`document_id`, `create_time`, `id`) USING BTREE,
                                        INDEX `idx_knowledge_job_parent_status`(`parent_job_id`, `status`, `id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '知识库解析任务控制面状态' ROW_FORMAT = Dynamic;

