-- ----------------------------
-- Table structure for mcp_role_tool_permission
-- ----------------------------
DROP TABLE IF EXISTS `mcp_role_tool_permission`;
CREATE TABLE `mcp_role_tool_permission`  (
                                             `id` bigint NOT NULL COMMENT '主键',
                                             `role_id` bigint NOT NULL COMMENT '角色ID',
                                             `tool_id` bigint NOT NULL COMMENT '工具ID',
                                             `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '0正常 1停用',
                                             `effective_time` datetime(0) NULL DEFAULT NULL COMMENT '生效时间',
                                             `expire_time` datetime(0) NULL DEFAULT NULL COMMENT '失效时间',
                                             `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
                                             `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
                                             `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                                             `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                                             `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                                             `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                                             PRIMARY KEY (`id`) USING BTREE,
                                             UNIQUE INDEX `uk_mcp_role_tool`(`role_id`, `tool_id`) USING BTREE,
                                             INDEX `idx_mcp_role_tool_active`(`role_id`, `status`, `effective_time`, `expire_time`) USING BTREE,
                                             INDEX `idx_mcp_role_tool_tool`(`tool_id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '角色MCP工具权限表' ROW_FORMAT = Dynamic;

