-- ----------------------------
-- Table structure for mcp_server_info
-- ----------------------------
DROP TABLE IF EXISTS `mcp_server_info`;
CREATE TABLE `mcp_server_info`  (
                                    `id` bigint NOT NULL COMMENT 'Server ID',
                                    `server_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Server唯一编码',
                                    `server_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'Server名称',
                                    `server_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'THIRD_PARTY' COMMENT 'THIRD_PARTY/BUSINESS/PYTHON_BUILTIN',
                                    `transport_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'STREAMABLE_HTTP' COMMENT 'STREAMABLE_HTTP/STDIO',
                                    `endpoint` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Streamable HTTP MCP地址',
                                    `runtime_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'STDIO部署侧白名单运行时键',
                                    `protocol_version` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '2026-07-28' COMMENT '目标MCP协议版本或AUTO',
                                    `auth_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NONE' COMMENT 'NONE/BEARER/API_KEY/OAUTH2/INTERNAL_HMAC',
                                    `credential_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Python侧凭证别名，不保存明文密钥',
                                    `connect_timeout` int NOT NULL DEFAULT 30 COMMENT '连接超时秒数',
                                    `default_risk_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'LOW' COMMENT 'LOW/MEDIUM/HIGH/CRITICAL',
                                    `status` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
                                    `runtime_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'NOT_DEPLOYED' COMMENT 'NOT_DEPLOYED/SYNCED/ERROR',
                                    `runtime_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Python运行状态说明',
                                    `last_discovered_at` datetime(0) NULL DEFAULT NULL COMMENT '最后工具发现时间',
                                    `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
                                    `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
                                    `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                                    `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                                    `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                                    `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                                    `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
                                    PRIMARY KEY (`id`) USING BTREE,
                                    UNIQUE INDEX `uk_mcp_server_code`(`server_code`) USING BTREE,
                                    INDEX `idx_mcp_server_status`(`status`) USING BTREE,
                                    INDEX `idx_mcp_server_transport`(`transport_type`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MCP Server配置表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mcp_server_info
-- ----------------------------
INSERT INTO `mcp_server_info` VALUES (2104773390069501953, 'open-meteo-mcp', '天气服务', 'THIRD_PARTY', 'STREAMABLE_HTTP', 'https://open-meteo.caseyjhand.com/mcp', NULL, '2026-07-28', 'NONE', NULL, 30, 'LOW', 'ENABLED', 'NOT_DEPLOYED', NULL, '2026-09-29 11:29:07', '天气预报、空气质量、地点查询等；', 100, 1, '2026-09-29 11:20:56', 1, '2026-09-29 11:29:08', '0');
INSERT INTO `mcp_server_info` VALUES (2104774189336072193, 'openstreetmap-mcp', '地图服务', 'THIRD_PARTY', 'STREAMABLE_HTTP', 'https://openstreetmap.caseyjhand.com/mcp', NULL, '2026-07-28', 'NONE', NULL, 30, 'LOW', 'ENABLED', 'NOT_DEPLOYED', NULL, '2026-09-29 11:29:28', '这个服务提供地点搜索、逆地理编码和周边查询等工具，不提供路线规划', 100, 1, '2026-09-29 11:24:06', 1, '2026-09-29 11:29:28', '0');

-- ----------------------------
-- Table structure for mcp_tool_info
-- ----------------------------
DROP TABLE IF EXISTS `mcp_tool_info`;
CREATE TABLE `mcp_tool_info`  (
                                  `id` bigint NOT NULL COMMENT '工具ID',
                                  `server_id` bigint NOT NULL COMMENT '所属MCP Server ID',
                                  `tool_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'MCP原始工具名',
                                  `qualified_name` varchar(320) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT 'serverCode:toolName',
                                  `display_name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '管理端显示名称',
                                  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '工具描述',
                                  `input_schema` json NOT NULL COMMENT '输入JSON Schema',
                                  `output_schema` json NULL COMMENT '输出JSON Schema',
                                  `annotations_json` json NULL COMMENT 'MCP工具注解',
                                  `meta_json` json NULL COMMENT 'MCP _meta',
                                  `schema_digest` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '工具Schema SHA-256摘要',
                                  `source_type` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'IMPORTED' COMMENT 'DISCOVERED/IMPORTED/BUSINESS',
                                  `discovery_status` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE/CHANGED/REMOVED',
                                  `admin_enabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '管理端启用：0否 1是',
                                  `general_chat_enabled` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '允许无 Agent 聊天使用：0否 1是',
                                  `risk_level` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'LOW' COMMENT 'LOW/MEDIUM/HIGH/CRITICAL',
                                  `require_confirmation` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '是否需要用户确认：0否 1是',
                                  `timeout_seconds` int NOT NULL DEFAULT 30 COMMENT '调用超时秒数',
                                  `visible_result_fields` json NULL COMMENT '允许返回给模型的字段',
                                  `last_discovered_at` datetime(0) NULL DEFAULT NULL COMMENT '最后发现时间',
                                  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
                                  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
                                  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                                  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
                                  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
                                  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '删除标志（0存在 2删除）',
                                  PRIMARY KEY (`id`) USING BTREE,
                                  UNIQUE INDEX `uk_mcp_server_tool`(`server_id`, `tool_name`) USING BTREE,
                                  UNIQUE INDEX `uk_mcp_qualified_name`(`qualified_name`) USING BTREE,
                                  INDEX `idx_mcp_tool_enabled`(`server_id`, `admin_enabled`, `discovery_status`) USING BTREE,
                                  INDEX `idx_mcp_tool_risk`(`risk_level`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'MCP工具目录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of mcp_tool_info
-- ----------------------------
INSERT INTO `mcp_tool_info` VALUES (2104775452542996482, 2104773390069501953, 'openmeteo_search_locations', 'open-meteo-mcp:openmeteo_search_locations', 'Openmeteo Search Locations', 'Resolve a place name to ranked coordinate matches with country, region, elevation, timezone, and population. Required prerequisite for name-based queries — all weather tools take latitude/longitude, not place names. Search by a bare place name (city, region, or landmark); never fold a qualifier into it — pass \"Baoding\", not \"Baoding Hebei\", and \"Paris\", not \"Paris, France\". To disambiguate places that share a name, set the country input (ISO 3166-1 alpha-2, e.g. \"US\") and/or read the admin1 and country fields on each ranked result — admin1 is a result field for choosing among matches, not a search input. Returns up to 10 matches ranked by population/relevance.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"name\"], \"properties\": {\"name\": {\"type\": \"string\", \"maxLength\": 100, \"minLength\": 1, \"description\": \"Place name to search — a bare city, region, or landmark (\\\"Seattle\\\", \\\"Mount Rainier\\\"). Do not fold in a region or country qualifier (\\\"Baoding\\\", not \\\"Baoding Hebei\\\"); use the country input to disambiguate. A one- or two-character native-script name (\\\"서울\\\", \\\"大阪\\\") needs the full administrative name (\\\"서울특별시\\\", \\\"大阪市\\\") or the romanized name (\\\"Seoul\\\", \\\"Osaka\\\") — see the language field. Weather tools require coordinates — use the lat/lon from this result.\"}, \"count\": {\"type\": \"integer\", \"default\": 5, \"maximum\": 10, \"minimum\": 1, \"description\": \"Max results to return (1–10). Default 5. Return more when disambiguating common names like \\\"Springfield\\\" or \\\"Portland\\\".\"}, \"country\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z]{2}$\", \"description\": \"ISO 3166-1 alpha-2 country code (e.g. \\\"US\\\", \\\"FR\\\") to disambiguate places that share a name. Omit for a global search.\"}, \"language\": {\"type\": \"string\", \"default\": \"en\", \"description\": \"Language for matching and returning place names (ISO 639-1, e.g., \\\"en\\\", \\\"de\\\", \\\"zh\\\"). The API matches name against the localized index for this language, so set it to match the script of name — e.g. language \\\"zh\\\" for \\\"上海\\\", \\\"ru\\\" for \\\"Москва\\\". This resolves a native-script name of three or more characters, which is matched by normalized prefix; a one- or two-character name must equal an index entry exactly, so setting language alone will not find \\\"서울\\\" or \\\"大阪\\\" — retry those with the full administrative name (\\\"서울특별시\\\", \\\"大阪市\\\") or the romanized name (\\\"Seoul\\\", \\\"Osaka\\\"). Default \\\"en\\\"; a query in a recognized non-Latin script (CJK, Hangul, Cyrillic, Arabic, Greek, Hebrew, Thai, Devanagari) that misses under \\\"en\\\" is retried once with the language inferred from its script.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"results\", \"count\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"count\": {\"type\": \"number\", \"description\": \"Number of results returned\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"no_results\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `no_results`: The search returned no matching places. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"notice\": {\"type\": \"string\", \"description\": \"Advisory on the confidence of the top match, present only when its population is null or under 100,000 — the shape a historic or colonial exonym returns, where the upstream index answers with an unrelated small feature and never surfaces the modern city. Names the returned place, country, and feature_code, and asks the caller to verify the coordinates or retry with the place’s current official name. Never changes results or count.\"}, \"results\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"id\", \"name\", \"latitude\", \"longitude\", \"elevation\", \"timezone\", \"country\", \"country_code\", \"admin1\", \"admin2\", \"population\", \"feature_code\"], \"properties\": {\"id\": {\"type\": \"number\", \"description\": \"Open-Meteo place ID — stable reference for this location\"}, \"name\": {\"type\": \"string\", \"description\": \"Place name\"}, \"admin1\": {\"type\": [\"string\", \"null\"], \"description\": \"State, province, or region\"}, \"admin2\": {\"type\": [\"string\", \"null\"], \"description\": \"County or district\"}, \"country\": {\"type\": [\"string\", \"null\"], \"description\": \"Country name — null for non-country features like continents and oceans\"}, \"latitude\": {\"type\": \"number\", \"description\": \"Latitude in decimal degrees\"}, \"timezone\": {\"type\": [\"string\", \"null\"], \"description\": \"IANA timezone (e.g., \\\"America/Los_Angeles\\\") — pass to weather tools as the timezone parameter. Null when the API omits it.\"}, \"elevation\": {\"type\": [\"number\", \"null\"], \"description\": \"Elevation in meters above sea level\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Longitude in decimal degrees\"}, \"population\": {\"type\": [\"number\", \"null\"], \"description\": \"Population (when available) — useful for disambiguating same-named cities\"}, \"country_code\": {\"type\": [\"string\", \"null\"], \"description\": \"ISO 3166-1 alpha-2 country code — null for non-country features like continents and oceans\"}, \"feature_code\": {\"type\": \"string\", \"description\": \"GeoNames feature code describing the place type (e.g., \\\"PPLA2\\\" = state capital city, \\\"PPL\\\" = populated place)\"}}, \"description\": \"A single geocoding result with coordinates and administrative context\", \"additionalProperties\": false}, \"description\": \"Ranked matches (most relevant first). Never empty — when nothing matches, the tool fails with no_results instead of returning an empty array.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, '6d72b7aead597d80b5bd2820f4998c8c8233c67ed4eeaefc6ec0f59c2849e5e9', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:33:20', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452593328130, 2104773390069501953, 'openmeteo_get_elevation', 'open-meteo-mcp:openmeteo_get_elevation', 'Openmeteo Get Elevation', 'Terrain elevation from the Copernicus Digital Elevation Model (~90m resolution) for one or more coordinate pairs. Accepts up to 100 pairs per call. Useful for geographic context, elevation-adjusted weather interpretation, or route planning.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitudes\", \"longitudes\"], \"properties\": {\"latitudes\": {\"type\": \"array\", \"items\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90}, \"maxItems\": 100, \"minItems\": 1, \"description\": \"Array of latitudes in decimal degrees (up to 100). Must be same length as longitudes.\"}, \"longitudes\": {\"type\": \"array\", \"items\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180}, \"maxItems\": 100, \"minItems\": 1, \"description\": \"Array of longitudes in decimal degrees (up to 100). Must be same length as latitudes.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"elevations\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"coordinate_count_mismatch\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `coordinate_count_mismatch`: latitudes and longitudes arrays have different lengths. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"elevations\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"latitude\", \"longitude\", \"elevation_m\"], \"properties\": {\"latitude\": {\"type\": \"number\", \"description\": \"Input latitude\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Input longitude\"}, \"elevation_m\": {\"type\": \"number\", \"description\": \"Terrain elevation in meters above sea level\"}}, \"description\": \"Elevation for a single coordinate pair\", \"additionalProperties\": false}, \"description\": \"Elevation values in input order\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, 'e6106ae216913c4762adde751650fd2acc9c9cfdb743b8e3098a0a51aafe0439', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:31:20', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452593328131, 2104773390069501953, 'openmeteo_get_forecast', 'open-meteo-mcp:openmeteo_get_forecast', 'Openmeteo Get Forecast', 'Weather forecast for coordinates: hourly and/or daily variables for up to 16 days ahead, with optional past_days (up to 92) for recent history. Use past_days instead of openmeteo_get_historical for dates within the last 1–5 days, since the archive’s ERA5 components lag by up to ~5 days. Returns per-timestamp records — each hourly entry contains a \"time\" field (ISO 8601) plus one key per requested variable; each daily entry contains a \"time\" field (YYYY-MM-DD) plus requested variables. Common hourly variables: temperature_2m, precipitation, wind_speed_10m, relative_humidity_2m, cloud_cover, uv_index, apparent_temperature, precipitation_probability, weather_code, surface_pressure, visibility, wind_direction_10m, wind_gusts_10m, dew_point_2m. Common daily variables: temperature_2m_max, temperature_2m_min, precipitation_sum, wind_speed_10m_max, sunrise, sunset, uv_index_max, precipitation_hours, weather_code. Set current_variables for conditions at this instant — Open-Meteo serves those from 15-minute model data, which is more precise than picking the nearest hourly row, and the response carries a current object plus a current_units map. A wide window — a large past_days plus many hourly variables — produces thousands of records; these spill to a DataCanvas when canvas is enabled, returning canvas_id and table_name with truncated: true — inspect the staged columns with openmeteo_dataframe_describe, then query the full set with openmeteo_dataframe_query. With canvas disabled they return a bounded preview instead. At least one of current_variables, hourly_variables, or daily_variables is required.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitude\", \"longitude\"], \"properties\": {\"latitude\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude in decimal degrees (e.g., 47.6062 for Seattle). Use openmeteo_search_locations to resolve a place name to coordinates.\"}, \"timezone\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"IANA timezone (e.g., \\\"America/Los_Angeles\\\") or \\\"auto\\\" to use the location\'s local timezone. Default \\\"auto\\\". The timezone from openmeteo_search_locations is ideal to pass here.\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"DataCanvas token for wide past_days or multi-variable queries. When a result is too large to return inline — driven by total payload size, so a wide multi-variable pull can spill at any row count — it spills to this canvas: pass the returned token to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it. Omit to create a fresh canvas.\"}, \"longitude\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in decimal degrees (e.g., -122.3321 for Seattle).\"}, \"past_days\": {\"type\": \"integer\", \"default\": 0, \"maximum\": 92, \"minimum\": 0, \"description\": \"Include this many days of past data before today (0–92). Use for recent history — the archive’s ERA5 components lag by up to ~5 days. Default 0.\"}, \"forecast_days\": {\"type\": \"integer\", \"default\": 7, \"maximum\": 16, \"minimum\": 1, \"description\": \"Number of forecast days (1–16). Default 7.\"}, \"daily_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Daily summary variables (e.g., [\\\"temperature_2m_max\\\", \\\"temperature_2m_min\\\", \\\"precipitation_sum\\\", \\\"wind_speed_10m_max\\\", \\\"sunrise\\\", \\\"sunset\\\", \\\"uv_index_max\\\"]). Daily names only — an hourly name such as cloud_cover or temperature_2m belongs in hourly_variables and is rejected here; for a daily summary of an hourly variable use its published aggregate (cloud_cover_max, cloud_cover_mean, cloud_cover_min). At least one of current_variables, hourly_variables, or daily_variables is required.\"}, \"wind_speed_unit\": {\"enum\": [\"kmh\", \"mph\", \"ms\", \"kn\"], \"type\": \"string\", \"default\": \"kmh\", \"description\": \"Wind speed unit: \\\"kmh\\\" (km/h), \\\"mph\\\", \\\"ms\\\" (m/s), or \\\"kn\\\" (knots). Default \\\"kmh\\\".\"}, \"hourly_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Hourly variables to fetch (e.g., [\\\"temperature_2m\\\", \\\"precipitation\\\", \\\"wind_speed_10m\\\", \\\"relative_humidity_2m\\\", \\\"cloud_cover\\\", \\\"uv_index\\\", \\\"apparent_temperature\\\"]). Hourly names only — a daily aggregate such as temperature_2m_max or precipitation_sum belongs in daily_variables and is rejected here. At least one of current_variables, hourly_variables, or daily_variables is required.\"}, \"temperature_unit\": {\"enum\": [\"celsius\", \"fahrenheit\"], \"type\": \"string\", \"default\": \"celsius\", \"description\": \"Temperature unit. Default \\\"celsius\\\".\"}, \"current_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Variables to return for the current instant (e.g., [\\\"temperature_2m\\\", \\\"precipitation\\\", \\\"wind_speed_10m\\\", \\\"weather_code\\\"]). Uses Open-Meteo\'s 15-minute current-conditions data, so it answers \\\"what is it doing right now?\\\" without requesting an hourly series and picking a row. Takes the hourly variable names; a daily-only name such as temperature_2m_max comes back null with the unit \\\"undefined\\\" and is reported in the notice. Satisfies the variable requirement on its own.\"}, \"precipitation_unit\": {\"enum\": [\"mm\", \"inch\"], \"type\": \"string\", \"default\": \"mm\", \"description\": \"Precipitation unit: \\\"mm\\\" or \\\"inch\\\". Default \\\"mm\\\".\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"latitude\", \"longitude\", \"elevation\", \"timezone\", \"utc_offset_seconds\", \"record_count\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"daily\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-day records. Each object has a \\\"time\\\" field (YYYY-MM-DD) plus one key per requested variable with its value. Units are in the daily_units map. Absent when only hourly_variables were requested. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"invalid_variable\", \"variable_wrong_cadence\", \"no_variables_requested\", \"invalid_timezone\", \"request_too_large\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `invalid_variable`: An unknown variable name was requested. `variable_wrong_cadence`: A variable Open-Meteo documents under one cadence was passed in the other cadence field — for example cloud_cover in daily_variables, or temperature_2m_max in hourly_variables. `no_variables_requested`: None of current_variables, hourly_variables, or daily_variables was provided. `invalid_timezone`: timezone was blank, or upstream did not recognize the requested time zone. `request_too_large`: Open-Meteo refused the request as asking for too much data in one call. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"hourly\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-hour records. Each object has a \\\"time\\\" field (ISO 8601) plus one key per requested variable with its value. Units are in the hourly_units map. Absent when only daily_variables were requested. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"notice\": {\"type\": \"string\", \"description\": \"Everything this response needs to say beyond the data, composed into one advisory: columns the endpoint returned with the unit \\\"undefined\\\" (a name it parsed but does not serve in the requested cadence); recognized variables whose requested window falls outside the data\'s coverage, with the timestamps that do carry values; and, when the result spilled, either the canvas and table holding the full row set plus the two dataframe tools that read it, or — with DataCanvas disabled — why there is no canvas_id and how to reach the rows the preview omits.\"}, \"current\": {\"type\": \"object\", \"required\": [\"time\", \"interval\"], \"properties\": {\"time\": {\"type\": \"string\", \"description\": \"Timestamp of these values (ISO 8601, in the resolved timezone)\"}, \"interval\": {\"type\": \"number\", \"description\": \"Update cadence of the current-conditions data, in seconds (900 = 15 minutes) — metadata, not a requested variable\"}}, \"description\": \"Conditions at a single instant: one key per requested current variable alongside time and interval. Units are in the current_units map. Absent when current_variables was not requested.\", \"additionalProperties\": {\"type\": [\"string\", \"number\", \"null\"]}}, \"latitude\": {\"type\": \"number\", \"description\": \"Snapped latitude (Open-Meteo snaps to nearest grid point)\"}, \"timezone\": {\"type\": \"string\", \"description\": \"Resolved IANA timezone\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"DataCanvas token for the staged full dataset. Present only when truncated is true AND DataCanvas is enabled (CANVAS_PROVIDER_TYPE=duckdb) — absent otherwise, in which case the preview is all this response carries. Pass to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it.\"}, \"elevation\": {\"type\": \"number\", \"description\": \"Terrain elevation at grid point (meters)\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Snapped longitude\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the response was too large to return inline, so hourly and daily carry a bounded preview rather than the full set. With DataCanvas enabled the complete data is staged at canvas_id — every hourly and daily row, including any column the preview omits. With it disabled there is no canvas_id, and the omitted rows are reached only by narrowing the request.\"}, \"table_name\": {\"type\": \"string\", \"description\": \"DuckDB table name for the staged data — use as the FROM target in openmeteo_dataframe_query SQL; openmeteo_dataframe_describe lists its columns. Present only alongside canvas_id.\"}, \"daily_units\": {\"type\": \"object\", \"description\": \"Map of variable name → unit string for daily data. Absent when no daily_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"hourly_units\": {\"type\": \"object\", \"description\": \"Map of variable name → unit string for hourly data (e.g., {\\\"temperature_2m\\\": \\\"°C\\\", \\\"precipitation\\\": \\\"mm\\\"}). Absent when no hourly_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"record_count\": {\"type\": \"number\", \"description\": \"Total number of records (hourly + daily rows) — the full upstream total when truncated is true, not the combined length of the hourly and daily previews.\"}, \"current_units\": {\"type\": \"object\", \"description\": \"Map of key → unit string for the current block, covering time and interval as well as each requested variable (e.g., {\\\"interval\\\": \\\"seconds\\\", \\\"temperature_2m\\\": \\\"°C\\\"}). Absent when no current_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"utc_offset_seconds\": {\"type\": \"number\", \"description\": \"UTC offset in seconds for this timezone at query time\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, '699ffa4f0c5a911cb58f1f056b0c8091e4c946a7d30298f5b927442aa3d3e5c8', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:31:52', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452673019906, 2104773390069501953, 'openmeteo_get_historical', 'open-meteo-mcp:openmeteo_get_historical', 'Openmeteo Get Historical', 'Historical weather from the Open-Meteo reanalysis archive (1940–present). Requires start_date and end_date (ISO 8601 date, e.g., \"2024-07-01\"). With models omitted the archive answers from Best Match, which blends IFS HRES, ERA5, and ERA5-Land seamlessly — so the source varies by date and no single update lag describes the response. Set models to pin a consistent source for a multi-decade series: the ERA5 family updates daily with about a 5-day delay, while IFS HRES has none, so for the last few days either request models: [\"ecmwf_ifs\"] or use openmeteo_get_forecast with past_days. Available models: best_match (default, blends IFS HRES + ERA5 + ERA5-Land), ecmwf_ifs (global 9 km, updated every 6 hours, no delay), ecmwf_ifs_analysis_long_window (global 9 km, daily, 2 days delay), era5_seamless (ERA5 and ERA5-Land combined), era5 (global 0.25° (~25 km), daily, 5 days delay), era5_land (global 0.1° (~11 km), daily, 5 days delay), era5_ensemble (global 0.5° (~55 km), daily, 5 days delay), cerra (Europe only, 5 km, no real-time updates). Uses the same variable names as the forecast API for direct comparison. Large date ranges (multi-year hourly) produce thousands of records — these spill to a DataCanvas when canvas is enabled, returning canvas_id and table_name with truncated: true; inspect the staged columns with openmeteo_dataframe_describe, then query the full set with openmeteo_dataframe_query. With canvas disabled they return a bounded preview instead. At least one of hourly_variables or daily_variables is required.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitude\", \"longitude\", \"start_date\", \"end_date\"], \"properties\": {\"models\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 8, \"description\": \"Archive models to read from: best_match (default, blends IFS HRES + ERA5 + ERA5-Land), ecmwf_ifs (global 9 km, updated every 6 hours, no delay), ecmwf_ifs_analysis_long_window (global 9 km, daily, 2 days delay), era5_seamless (ERA5 and ERA5-Land combined), era5 (global 0.25° (~25 km), daily, 5 days delay), era5_land (global 0.1° (~11 km), daily, 5 days delay), era5_ensemble (global 0.5° (~55 km), daily, 5 days delay), cerra (Europe only, 5 km, no real-time updates). Omit to use Open-Meteo\'s Best Match default, which blends IFS HRES, ERA5, and ERA5-Land — pin a model instead when a consistent source matters across the range. With 2+ models each variable column is suffixed with the model name. cerra covers Europe only and is rejected as a coverage gap elsewhere. A name outside this list is sent upstream rather than rejected here.\"}, \"end_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"End date (YYYY-MM-DD, inclusive). Must be on or after start_date. For the last few days, either request models: [\\\"ecmwf_ifs\\\"] or use openmeteo_get_forecast with past_days.\"}, \"latitude\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude in decimal degrees. Use openmeteo_search_locations to resolve a place name to coordinates.\"}, \"timezone\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"IANA timezone or \\\"auto\\\". Default \\\"auto\\\".\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"DataCanvas token for multi-year or multi-variable queries. When a result is too large to return inline — driven by total payload size, so a wide multi-variable pull can spill at any row count — it spills to this canvas: pass the returned token to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it. Omit to create a fresh canvas.\"}, \"longitude\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in decimal degrees.\"}, \"start_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"Start date (YYYY-MM-DD, e.g., \\\"2024-07-01\\\"). The archive covers from 1940-01-01; how close to today it reaches depends on the model — the ERA5 family runs about 5 days behind, IFS HRES is current.\"}, \"daily_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Daily summary variables (e.g., [\\\"temperature_2m_max\\\", \\\"temperature_2m_min\\\", \\\"precipitation_sum\\\", \\\"wind_speed_10m_max\\\"]). Daily names only — an hourly name such as cloud_cover or temperature_2m belongs in hourly_variables and is rejected here; for a daily summary of an hourly variable use its published aggregate (cloud_cover_max, cloud_cover_mean, cloud_cover_min). At least one of hourly_variables or daily_variables required.\"}, \"wind_speed_unit\": {\"enum\": [\"kmh\", \"mph\", \"ms\", \"kn\"], \"type\": \"string\", \"default\": \"kmh\", \"description\": \"Wind speed unit. Default \\\"kmh\\\".\"}, \"hourly_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Hourly archive variables (e.g., [\\\"temperature_2m\\\", \\\"precipitation\\\", \\\"wind_speed_10m\\\", \\\"relative_humidity_2m\\\", \\\"cloud_cover\\\", \\\"soil_moisture_0_to_7cm\\\"]). Hourly names only — a daily aggregate such as temperature_2m_max or precipitation_sum belongs in daily_variables and is rejected here. At least one of hourly_variables or daily_variables required.\"}, \"temperature_unit\": {\"enum\": [\"celsius\", \"fahrenheit\"], \"type\": \"string\", \"default\": \"celsius\", \"description\": \"Temperature unit. Default \\\"celsius\\\".\"}, \"precipitation_unit\": {\"enum\": [\"mm\", \"inch\"], \"type\": \"string\", \"default\": \"mm\", \"description\": \"Precipitation unit. Default \\\"mm\\\".\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"latitude\", \"longitude\", \"elevation\", \"timezone\", \"date_range\", \"record_count\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"daily\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-day records with \\\"time\\\" (YYYY-MM-DD) + variable keys. Absent when only hourly_variables were requested. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"date_out_of_range\", \"date_order_invalid\", \"no_variables_requested\", \"invalid_variable\", \"variable_wrong_cadence\", \"invalid_timezone\", \"request_too_large\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `date_out_of_range`: start_date predates 1940-01-01, or the requested dates fall outside the coverage of the selected model. `date_order_invalid`: end_date is before start_date. `no_variables_requested`: Neither hourly_variables nor daily_variables was provided. `invalid_variable`: An unknown variable name or unsupported archive model was requested. `variable_wrong_cadence`: A variable Open-Meteo documents under one cadence was passed in the other cadence field — for example cloud_cover in daily_variables, or temperature_2m_max in hourly_variables. `invalid_timezone`: timezone was blank, or upstream did not recognize the requested time zone. `request_too_large`: Open-Meteo refused the request as asking for too much data in one call. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"hourly\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-hour records with \\\"time\\\" (ISO 8601) + variable keys. Absent when only daily_variables were requested. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"models\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"Archive models requested — echoes the models parameter. Absent when models was omitted, which means the data came from Open-Meteo Best Match (IFS HRES + ERA5 + ERA5-Land) and the source varies by date.\"}, \"notice\": {\"type\": \"string\", \"description\": \"Everything this response needs to say beyond the data, composed into one advisory: columns the archive returned with the unit \\\"undefined\\\" (a name it parsed but does not serve in the requested cadence); recognized variables whose requested window falls outside the data\'s coverage, with the timestamps that do carry values; and, when the result spilled, either the canvas and table holding the full row set plus the two dataframe tools that read it, or — with DataCanvas disabled — why there is no canvas_id and how to reach the rows the preview omits.\"}, \"latitude\": {\"type\": \"number\", \"description\": \"Snapped latitude\"}, \"timezone\": {\"type\": \"string\", \"description\": \"Resolved IANA timezone\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"DataCanvas token for the staged full dataset. Present only when truncated is true AND DataCanvas is enabled (CANVAS_PROVIDER_TYPE=duckdb) — absent otherwise, in which case the preview is all this response carries. Pass to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it.\"}, \"elevation\": {\"type\": \"number\", \"description\": \"Elevation at grid point (meters)\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Snapped longitude\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the response was too large to return inline, so hourly and daily carry a bounded preview rather than the full set. With DataCanvas enabled the complete data is staged at canvas_id — every hourly and daily row, including any column the preview omits. With it disabled there is no canvas_id, and the omitted rows are reached only by narrowing the request.\"}, \"date_range\": {\"type\": \"object\", \"required\": [\"start\", \"end\"], \"properties\": {\"end\": {\"type\": \"string\", \"description\": \"Actual end date of returned data\"}, \"start\": {\"type\": \"string\", \"description\": \"Actual start date of returned data\"}}, \"description\": \"Date range of returned data\", \"additionalProperties\": false}, \"table_name\": {\"type\": \"string\", \"description\": \"DuckDB table name for the staged data — use as the FROM target in openmeteo_dataframe_query SQL; openmeteo_dataframe_describe lists its columns. Present only alongside canvas_id.\"}, \"daily_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for daily data. Absent when no daily_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"hourly_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for hourly data (e.g., {\\\"temperature_2m\\\": \\\"°C\\\", \\\"precipitation\\\": \\\"mm\\\"}). Absent when no hourly_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"record_count\": {\"type\": \"number\", \"description\": \"Total number of records (hourly + daily rows) — the full upstream total when truncated is true, not the combined length of the hourly and daily previews.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, '620099479b11497053f8e93f494a8aba81a200a62f897c716498fd306a567036', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:32:16', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452740128770, 2104773390069501953, 'openmeteo_get_marine', 'open-meteo-mcp:openmeteo_get_marine', 'Openmeteo Get Marine', 'Marine wave and ocean conditions for a coastal or ocean coordinate: wave height, wave period, wave direction, wind-wave height, swell height, sea-surface temperature. Forecast horizon up to 8 days, with optional past_days (up to 92) for recent history — or start_date and end_date together for an archive range, which returns real wave values back to at least 2022. One window per call: a date range is mutually exclusive with forecast_days and past_days, and needs both ends — a lone start_date or end_date is rejected. Returns per-timestamp records — each entry contains a \"time\" field plus one key per requested variable. Best for open-ocean and coastal exposed points — sheltered inland waters return near-zero wave values. Common hourly variables: wave_height, wave_direction, wave_period, wind_wave_height, wind_wave_direction, wind_wave_period, swell_wave_height, swell_wave_direction, swell_wave_period. Common daily: wave_height_max, wave_direction_dominant, wave_period_max. Note: ocean_current_velocity is null for non-open-ocean coordinates. A wide window — a large past_days or date range plus many variables — produces thousands of records; these spill to a DataCanvas when canvas is enabled, returning canvas_id and table_name with truncated: true — inspect the staged columns with openmeteo_dataframe_describe, then query the full set with openmeteo_dataframe_query. With canvas disabled they return a bounded preview instead.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitude\", \"longitude\"], \"properties\": {\"end_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"End date for the archive range (YYYY-MM-DD, inclusive). Must be on or after start_date. Requires start_date — the pair must be sent together, and neither combines with forecast_days or past_days.\"}, \"latitude\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude of a coastal or ocean point. Use openmeteo_search_locations to resolve a place name. Inland points return near-zero wave values.\"}, \"timezone\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"IANA timezone or \\\"auto\\\". Default \\\"auto\\\".\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"DataCanvas token for wide past_days, archive-range, or multi-variable queries. When a result is too large to return inline — driven by total payload size, so a wide multi-variable pull can spill at any row count — it spills to this canvas: pass the returned token to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it. Omit to create a fresh canvas.\"}, \"longitude\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in decimal degrees.\"}, \"past_days\": {\"type\": \"integer\", \"default\": 0, \"maximum\": 92, \"minimum\": 0, \"description\": \"Include this many days of past data before today (0–92). Use for recent history instead of a start_date/end_date range. Default 0. Must stay 0 when start_date/end_date are used.\"}, \"start_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"Start date for the archive range (YYYY-MM-DD, e.g., \\\"2024-07-01\\\"). Real wave values go back to at least 2022. Requires end_date — the pair must be sent together, and neither combines with forecast_days or past_days.\"}, \"forecast_days\": {\"type\": \"integer\", \"maximum\": 8, \"minimum\": 1, \"description\": \"Forecast horizon in days (1–8). Omit for the upstream default of 7. Mutually exclusive with start_date/end_date — omit it entirely when pulling an archive range.\"}, \"daily_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Daily marine summary variables (e.g., [\\\"wave_height_max\\\", \\\"wave_direction_dominant\\\", \\\"wave_period_max\\\"]). Daily names only — an hourly name such as wave_height belongs in hourly_variables and is rejected here; for a daily summary use its published aggregate (wave_height_max). At least one of hourly_variables or daily_variables required.\"}, \"hourly_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Hourly marine variables (e.g., [\\\"wave_height\\\", \\\"wave_direction\\\", \\\"wave_period\\\", \\\"wind_wave_height\\\", \\\"swell_wave_height\\\"]). Hourly names only — a daily aggregate such as wave_height_max or wave_direction_dominant belongs in daily_variables and is rejected here. At least one of hourly_variables or daily_variables required.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"latitude\", \"longitude\", \"timezone\", \"record_count\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"daily\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-day summary records with \\\"time\\\" (YYYY-MM-DD) + variable keys (e.g., wave_height_max in meters, wave_direction_dominant in degrees, wave_period_max in seconds). Absent when only hourly_variables were requested. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"invalid_variable\", \"variable_wrong_cadence\", \"no_variables_requested\", \"date_range_incomplete\", \"forecast_window_conflict\", \"date_order_invalid\", \"invalid_timezone\", \"request_too_large\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `invalid_variable`: An unknown marine variable name was requested. `variable_wrong_cadence`: A variable Open-Meteo documents under one cadence was passed in the other cadence field — for example wave_height in daily_variables, or wave_height_max in hourly_variables. `no_variables_requested`: Neither hourly_variables nor daily_variables was provided. `date_range_incomplete`: Only one of start_date / end_date was provided — the marine archive requires the pair together. `forecast_window_conflict`: forecast_days or a non-zero past_days was combined with start_date or end_date. `date_order_invalid`: end_date is before start_date. `invalid_timezone`: timezone was blank, or upstream did not recognize the requested time zone. `request_too_large`: Open-Meteo refused the request as asking for too much data in one call. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"hourly\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-hour records with \\\"time\\\" (ISO 8601) + one key per requested variable (e.g., wave_height in meters, wave_direction in degrees, wave_period in seconds). Absent when only daily_variables were requested. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"notice\": {\"type\": \"string\", \"description\": \"Everything this response needs to say beyond the data, composed into one advisory: columns the endpoint returned with the unit \\\"undefined\\\" (a name it parsed but does not serve); recognized variables whose requested window falls outside the data\'s coverage, with the timestamps that do carry values; and, when the result spilled, either the canvas and table holding the full row set plus the two dataframe tools that read it, or — with DataCanvas disabled — why there is no canvas_id and how to reach the rows the preview omits.\"}, \"latitude\": {\"type\": \"number\", \"description\": \"Snapped latitude\"}, \"timezone\": {\"type\": \"string\", \"description\": \"Resolved IANA timezone\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"DataCanvas token for the staged full dataset. Present only when truncated is true AND DataCanvas is enabled (CANVAS_PROVIDER_TYPE=duckdb) — absent otherwise, in which case the preview is all this response carries. Pass to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it.\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Snapped longitude\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the response was too large to return inline, so hourly and daily carry a bounded preview rather than the full set. With DataCanvas enabled the complete data is staged at canvas_id — every hourly and daily row, including any column the preview omits. With it disabled there is no canvas_id, and the omitted rows are reached only by narrowing the request.\"}, \"table_name\": {\"type\": \"string\", \"description\": \"DuckDB table name for the staged data — use as the FROM target in openmeteo_dataframe_query SQL; openmeteo_dataframe_describe lists its columns. Present only alongside canvas_id.\"}, \"daily_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for daily data. Absent when no daily_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"hourly_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for hourly data (e.g., {\\\"wave_height\\\": \\\"m\\\", \\\"wave_period\\\": \\\"s\\\"}). Absent when no hourly_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"record_count\": {\"type\": \"number\", \"description\": \"Total number of records (hourly + daily rows) — the full upstream total when truncated is true, not the combined length of the hourly and daily previews.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, '7dc96379986a7a6475d2adcc6061c75ddeb4f90383e8b710faa8a9d88e1caaf0', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:33:24', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452790460418, 2104773390069501953, 'openmeteo_get_air_quality', 'open-meteo-mcp:openmeteo_get_air_quality', 'Openmeteo Get Air Quality', 'Modeled CAMS (Copernicus Atmosphere Monitoring Service) air quality: PM2.5, PM10, nitrogen dioxide, sulphur dioxide, ozone, carbon monoxide, dust, pollen, and European/US AQI indices. This is modeled grid data, not measured station readings — for measured data, use openaq-mcp-server. Forecast horizon up to 7 days, with optional past_days (up to 92) for recent history — or start_date and end_date together for an archive range; the CAMS global archive begins in August 2022, and earlier dates return rows of nulls. One window per call: a date range is mutually exclusive with forecast_days and past_days, and needs both ends — a lone start_date or end_date is rejected. Common variables: pm2_5, pm10, carbon_monoxide, nitrogen_dioxide, sulphur_dioxide, ozone, dust, european_aqi, us_aqi, alder_pollen, birch_pollen, grass_pollen, mugwort_pollen, olive_pollen, ragweed_pollen. Set current_variables for pollutant and AQI values at this instant — returned as a current object plus a current_units map, and enough on its own without hourly_variables; the block’s interval field reports how often that value updates (3600 seconds on this endpoint). A wide window — a large past_days or date range plus many variables — produces thousands of records; these spill to a DataCanvas when canvas is enabled, returning canvas_id and table_name with truncated: true — inspect the staged columns with openmeteo_dataframe_describe, then query the full set with openmeteo_dataframe_query. With canvas disabled they return a bounded preview instead.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitude\", \"longitude\"], \"properties\": {\"end_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"End date for the archive range (YYYY-MM-DD, inclusive). Must be on or after start_date. Requires start_date — the pair must be sent together, and neither combines with forecast_days or past_days.\"}, \"latitude\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude in decimal degrees. Use openmeteo_search_locations to resolve a place name.\"}, \"timezone\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"IANA timezone or \\\"auto\\\". Default \\\"auto\\\".\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"DataCanvas token for wide past_days, archive-range, or multi-variable queries. When a result is too large to return inline — driven by total payload size, so a wide multi-variable pull can spill at any row count — it spills to this canvas: pass the returned token to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it. Omit to create a fresh canvas.\"}, \"longitude\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in decimal degrees.\"}, \"past_days\": {\"type\": \"integer\", \"default\": 0, \"maximum\": 92, \"minimum\": 0, \"description\": \"Include this many days of past data before today (0–92). Use for recent history instead of a start_date/end_date range. Default 0. Must stay 0 when start_date/end_date are used.\"}, \"start_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"Start date for the archive range (YYYY-MM-DD, e.g., \\\"2024-07-01\\\"). The CAMS global archive begins in August 2022; earlier dates return rows of nulls, and us_aqi starts a day later than the pollutant series (european_aqi starts with it). Requires end_date — the pair must be sent together, and neither combines with forecast_days or past_days.\"}, \"forecast_days\": {\"type\": \"integer\", \"maximum\": 7, \"minimum\": 1, \"description\": \"Forecast horizon in days (1–7). Omit for the upstream default of 5. Mutually exclusive with start_date/end_date — omit it entirely when pulling an archive range.\"}, \"hourly_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Hourly air quality variables (e.g., [\\\"pm2_5\\\", \\\"pm10\\\", \\\"ozone\\\", \\\"nitrogen_dioxide\\\", \\\"european_aqi\\\", \\\"us_aqi\\\"]). At least one of current_variables or hourly_variables is required.\"}, \"current_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Air quality variables to return for the current instant (e.g., [\\\"pm2_5\\\", \\\"pm10\\\", \\\"european_aqi\\\", \\\"us_aqi\\\"]). Uses Open-Meteo\'s current-conditions data, so it answers \\\"what is the AQI now?\\\" without requesting an hourly series and picking a row; the returned interval reports the update cadence, 3600 seconds on this endpoint. Satisfies the variable requirement on its own.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"latitude\", \"longitude\", \"timezone\", \"record_count\", \"data_source\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"invalid_variable\", \"no_variables_requested\", \"date_range_incomplete\", \"forecast_window_conflict\", \"date_order_invalid\", \"invalid_timezone\", \"request_too_large\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `invalid_variable`: An unknown air quality variable name was requested. `no_variables_requested`: Neither current_variables nor hourly_variables was provided. `date_range_incomplete`: Only one of start_date / end_date was provided — the CAMS archive requires the pair together. `forecast_window_conflict`: forecast_days or a non-zero past_days was combined with start_date or end_date. `date_order_invalid`: end_date is before start_date. `invalid_timezone`: timezone was blank, or upstream did not recognize the requested time zone. `request_too_large`: Open-Meteo refused the request as asking for too much data in one call. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"hourly\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-hour records with \\\"time\\\" (ISO 8601) + one key per requested variable. Units: pm2_5/pm10/dust in μg/m³, carbon_monoxide in μg/m³, nitrogen_dioxide/sulphur_dioxide/ozone in μg/m³, european_aqi/us_aqi as index values. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"notice\": {\"type\": \"string\", \"description\": \"Everything this response needs to say beyond the data, composed into one advisory: columns the endpoint returned with the unit \\\"undefined\\\" (a name it parsed but does not serve); recognized variables whose requested window falls outside the CAMS archive, with the timestamps that do carry values; and, when the result spilled, either the canvas and table holding the full row set plus the two dataframe tools that read it, or — with DataCanvas disabled — why there is no canvas_id and how to reach the rows the preview omits.\"}, \"current\": {\"type\": \"object\", \"required\": [\"time\", \"interval\"], \"properties\": {\"time\": {\"type\": \"string\", \"description\": \"Timestamp of these values (ISO 8601, in the resolved timezone)\"}, \"interval\": {\"type\": \"number\", \"description\": \"Update cadence of the current-conditions data, in seconds (3600 = hourly on this endpoint) — metadata, not a requested variable\"}}, \"description\": \"Pollutant and index values at a single instant: one key per requested current variable alongside time and interval. Units are in the current_units map. Absent when current_variables was not requested.\", \"additionalProperties\": {\"type\": [\"string\", \"number\", \"null\"]}}, \"latitude\": {\"type\": \"number\", \"description\": \"Snapped latitude\"}, \"timezone\": {\"type\": \"string\", \"description\": \"Resolved IANA timezone\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"DataCanvas token for the staged full dataset. Present only when truncated is true AND DataCanvas is enabled (CANVAS_PROVIDER_TYPE=duckdb) — absent otherwise, in which case the preview is all this response carries. Pass to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it.\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Snapped longitude\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the response was too large to return inline, so hourly carries a bounded preview rather than the full set. With DataCanvas enabled the complete data is staged at canvas_id. With it disabled there is no canvas_id, and the omitted rows are reached only by narrowing the request.\"}, \"table_name\": {\"type\": \"string\", \"description\": \"DuckDB table name for the staged data — use as the FROM target in openmeteo_dataframe_query SQL; openmeteo_dataframe_describe lists its columns. Present only alongside canvas_id.\"}, \"data_source\": {\"type\": \"string\", \"const\": \"CAMS\", \"description\": \"Data source identifier — this is modeled CAMS data, forecast or archive, not measured station data.\"}, \"hourly_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for hourly data (e.g., {\\\"pm2_5\\\": \\\"μg/m³\\\", \\\"european_aqi\\\": \\\"EAQI\\\"}).\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"record_count\": {\"type\": \"number\", \"description\": \"Total number of hourly records — the full upstream total when truncated is true, not the length of the hourly preview.\"}, \"current_units\": {\"type\": \"object\", \"description\": \"Key → unit string for the current block, covering time and interval as well as each requested variable (e.g., {\\\"interval\\\": \\\"seconds\\\", \\\"pm2_5\\\": \\\"μg/m³\\\"}). Absent when no current_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, '6accc5b37eadf2daa85b7bc6e60f90e6d4ee76fbdcd7b8f6545989094ef10b3b', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:31:11', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452865957890, 2104773390069501953, 'openmeteo_get_ensemble', 'open-meteo-mcp:openmeteo_get_ensemble', 'Openmeteo Get Ensemble', 'Probabilistic ensemble weather forecast — up to 64 ensemble members, up to 16 days ahead with optional past_days (0–92). Each member\'s values appear as separate columns named with a member suffix (e.g. temperature_2m_member01, temperature_2m_member02). Use the spread across members to compute exceedance probabilities, quantify forecast uncertainty, and build decision thresholds. Available models: ecmwf_ifs025_ensemble (51 members, global 0.25°), ecmwf_aifs025_ensemble (51, global 0.25°), ecmwf_ifs_europe_ensemble (51, Europe 9 km), ecmwf_aifs_europe_ensemble (51, Europe 31 km), google_weathernext2_ensemble (64, global 0.25°), ncep_gefs_seamless (31, global blend), ncep_gefs025 (31, global 0.25°), ncep_gefs05 (31, global 50 km, 35 days), ncep_aigefs025 (31, global 0.25°), icon_seamless_eps (20–40, global/Europe blend), icon_global_eps (40, global 26 km), icon_eu_eps (40, Europe 13 km), icon_d2_eps (20, Central Europe 2 km), gem_global_ensemble (21, global 0.25°), bom_access_global_ensemble (18, global 40 km), ukmo_global_ensemble_20km (18, global 20 km), ukmo_uk_ensemble_2km (3, UK 2 km), meteoswiss_icon_ch1_ensemble (11, Central Europe 1 km), meteoswiss_icon_ch2_ensemble (21, Central Europe 2 km). Omit models to use the API default blend. A regional model returns no data outside the area it covers; that comes back as an input error naming the coverage gap, not a transient failure, so pick a global model or move the coordinate inside the region rather than retrying. A model name this list does not carry is still sent upstream, so a newly added one keeps working. Large multi-member, multi-day pulls produce thousands of records and spill to a DataCanvas when canvas is enabled, returning canvas_id and table_name with truncated: true — inspect the staged columns with openmeteo_dataframe_describe, then query the full set with openmeteo_dataframe_query. With canvas disabled they return a bounded preview instead. At least one of hourly_variables or daily_variables is required.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitude\", \"longitude\"], \"properties\": {\"models\": {\"type\": \"string\", \"description\": \"Ensemble model to use, one name: ecmwf_ifs025_ensemble (51 members, global 0.25°), ecmwf_aifs025_ensemble (51, global 0.25°), ecmwf_ifs_europe_ensemble (51, Europe 9 km), ecmwf_aifs_europe_ensemble (51, Europe 31 km), google_weathernext2_ensemble (64, global 0.25°), ncep_gefs_seamless (31, global blend), ncep_gefs025 (31, global 0.25°), ncep_gefs05 (31, global 50 km, 35 days), ncep_aigefs025 (31, global 0.25°), icon_seamless_eps (20–40, global/Europe blend), icon_global_eps (40, global 26 km), icon_eu_eps (40, Europe 13 km), icon_d2_eps (20, Central Europe 2 km), gem_global_ensemble (21, global 0.25°), bom_access_global_ensemble (18, global 40 km), ukmo_global_ensemble_20km (18, global 20 km), ukmo_uk_ensemble_2km (3, UK 2 km), meteoswiss_icon_ch1_ensemble (11, Central Europe 1 km), meteoswiss_icon_ch2_ensemble (21, Central Europe 2 km). Member counts include the control run. Omit to use the API default blend. A name outside this list is sent upstream rather than rejected here, so a model Open-Meteo adds later still works.\"}, \"latitude\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude in decimal degrees. Use openmeteo_search_locations to resolve a place name to coordinates.\"}, \"timezone\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"IANA timezone (e.g., \\\"America/Los_Angeles\\\") or \\\"auto\\\" to use the location\'s local timezone. Default \\\"auto\\\".\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"DataCanvas token for large multi-member queries. When a result is too large to return inline — driven by total payload size, so a wide member fan-out can spill at any row count — it spills to this canvas: pass the returned token to openmeteo_dataframe_describe to list the staged table and its per-member columns, then to openmeteo_dataframe_query to run SQL against it. Omit to create a fresh canvas.\"}, \"longitude\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in decimal degrees.\"}, \"past_days\": {\"type\": \"integer\", \"default\": 0, \"maximum\": 92, \"minimum\": 0, \"description\": \"Include this many days of past ensemble data before today (0–92). Default 0.\"}, \"forecast_days\": {\"type\": \"integer\", \"default\": 7, \"maximum\": 16, \"minimum\": 1, \"description\": \"Forecast horizon in days (1–16). Default 7.\"}, \"daily_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Daily variables to fetch across all ensemble members (e.g., [\\\"temperature_2m_max\\\", \\\"temperature_2m_min\\\", \\\"precipitation_sum\\\"]). Each variable appears as temperature_2m_max_member01, … Daily names only — an hourly name such as precipitation or temperature_2m belongs in hourly_variables and is rejected here; for a daily summary use its published aggregate (precipitation_sum, temperature_2m_max). At least one of hourly_variables or daily_variables required.\"}, \"wind_speed_unit\": {\"enum\": [\"kmh\", \"mph\", \"ms\", \"kn\"], \"type\": \"string\", \"default\": \"kmh\", \"description\": \"Wind speed unit. Default \\\"kmh\\\".\"}, \"hourly_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Hourly variables to fetch across all ensemble members (e.g., [\\\"temperature_2m\\\", \\\"precipitation\\\", \\\"wind_speed_10m\\\"]). Each variable appears as temperature_2m_member01, temperature_2m_member02, … in the output. Hourly names only — a daily-only aggregate such as precipitation_sum or wind_speed_10m_max belongs in daily_variables and is rejected here; temperature_2m_max and temperature_2m_min are an exception, published here as 3-hourly aggregations as well as daily. At least one of hourly_variables or daily_variables required.\"}, \"temperature_unit\": {\"enum\": [\"celsius\", \"fahrenheit\"], \"type\": \"string\", \"default\": \"celsius\", \"description\": \"Temperature unit. Default \\\"celsius\\\".\"}, \"precipitation_unit\": {\"enum\": [\"mm\", \"inch\"], \"type\": \"string\", \"default\": \"mm\", \"description\": \"Precipitation unit. Default \\\"mm\\\".\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"latitude\", \"longitude\", \"elevation\", \"timezone\", \"record_count\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"daily\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-day records with \\\"time\\\" (YYYY-MM-DD) + per-member columns (e.g., temperature_2m_max_member01). Absent when only hourly_variables were requested. When truncated, contains a preview only — query canvas_id for the full dataset when one is present.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"no_variables_requested\", \"invalid_variable\", \"variable_wrong_cadence\", \"invalid_timezone\", \"request_too_large\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `no_variables_requested`: Neither hourly_variables nor daily_variables was provided. `invalid_variable`: An unknown variable name or unsupported model was requested. `variable_wrong_cadence`: A variable the ensemble API documents under one cadence was passed in the other cadence field — for example precipitation_sum in hourly_variables, or precipitation in daily_variables. `invalid_timezone`: timezone was blank, or upstream did not recognize the requested time zone. `request_too_large`: Open-Meteo refused the request as asking for too much data in one call. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"model\": {\"type\": \"string\", \"description\": \"Ensemble model used (e.g. \\\"ecmwf_ifs025_ensemble\\\") — echoes the requested models parameter. Absent when models was omitted (API default blend; the API reports no provenance).\"}, \"hourly\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-hour records with \\\"time\\\" (ISO 8601) + per-member columns for each requested variable (e.g., temperature_2m_member01, temperature_2m_member02). Absent when only daily_variables were requested. When truncated, contains a preview only — query canvas_id for the full dataset when one is present.\"}, \"notice\": {\"type\": \"string\", \"description\": \"Everything this response needs to say beyond the data, composed into one advisory: variables the endpoint returned with the unit \\\"undefined\\\" across every member (a name the selected model does not carry); recognized variables whose requested window runs past the model\'s horizon, with the timestamps that do carry values; and, when the result spilled, either the canvas and table holding the full row set plus the two dataframe tools that read it, or — with DataCanvas disabled — why there is no canvas_id and how to reach the rows the preview omits.\"}, \"latitude\": {\"type\": \"number\", \"description\": \"Snapped latitude (Open-Meteo snaps to nearest grid point)\"}, \"timezone\": {\"type\": \"string\", \"description\": \"Resolved IANA timezone\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"DataCanvas token for the staged full dataset. Present only when truncated is true AND DataCanvas is enabled (CANVAS_PROVIDER_TYPE=duckdb) — absent otherwise, in which case the preview is all this response carries. Pass to openmeteo_dataframe_describe to list the staged table and its per-member columns, then to openmeteo_dataframe_query to run SQL against it.\"}, \"elevation\": {\"type\": \"number\", \"description\": \"Terrain elevation at grid point (meters)\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Snapped longitude\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the response was too large to return inline, so hourly and daily carry a bounded preview rather than the full set. With DataCanvas enabled the complete data is staged at canvas_id — every hourly and daily row, including any column the preview omits. With it disabled there is no canvas_id, and the omitted rows are reached only by narrowing the request.\"}, \"table_name\": {\"type\": \"string\", \"description\": \"DuckDB table name for the staged data — use as the FROM target in openmeteo_dataframe_query SQL; openmeteo_dataframe_describe lists its columns, which is the only way to learn the per-member suffixes this request produced. Present only alongside canvas_id.\"}, \"daily_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for daily data. Absent when no daily_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"hourly_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for hourly data (e.g., {\\\"temperature_2m_member01\\\": \\\"°C\\\"}). Absent when no hourly_variables were requested.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"member_count\": {\"type\": \"number\", \"description\": \"Number of distinct perturbed ensemble members in the response, counted from the _memberNN column suffixes. The unsuffixed base column (the control run) is not included in this count.\"}, \"record_count\": {\"type\": \"number\", \"description\": \"Total number of records (hourly + daily rows) — the full upstream total when truncated is true, not the combined length of the hourly and daily previews.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, '631ec282e4ecd4ea6bf7683098688d1eee816256591901eec333563b1ea66c98', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:31:36', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452945649666, 2104773390069501953, 'openmeteo_get_flood', 'open-meteo-mcp:openmeteo_get_flood', 'Openmeteo Get Flood', 'GloFAS (Global Flood Awareness System) river discharge forecast and historical reanalysis. Returns daily ensemble river discharge (m³/s) for the largest modeled river within 5 km of the given coordinates — no river ID needed. That river is not always the closest one: at 5 km resolution a point near a confluence or a pair of parallel channels can resolve to an unintended reach. When the returned discharge looks unrepresentative for the intended river, Open-Meteo suggests varying the coordinate by about 0.1° and comparing the values. Forecast horizon up to 210 days ahead; reanalysis history back to 1984-01-01. One mode per call: forecast_days for the future outlook, or start_date and end_date together for reanalysis history. The two modes are mutually exclusive, and a date range needs both ends — a lone start_date or end_date is rejected. Available daily variables: \"river_discharge\" (ensemble mean), \"river_discharge_mean\", \"river_discharge_min\", \"river_discharge_max\", \"river_discharge_median\", \"river_discharge_p25\" (25th percentile), \"river_discharge_p75\" (75th percentile). Returns null for coordinates far from any river or in areas without GloFAS coverage. A wide reanalysis range produces thousands of daily records and spills to a DataCanvas when canvas is enabled, returning canvas_id and table_name with truncated: true — inspect the staged columns with openmeteo_dataframe_describe, then query the full set with openmeteo_dataframe_query. With canvas disabled it returns a bounded preview instead.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitude\", \"longitude\"], \"properties\": {\"end_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"End date for historical reanalysis (YYYY-MM-DD, inclusive). Must be on or after start_date. Requires start_date — the pair must be sent together, and neither combines with forecast_days.\"}, \"latitude\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude in decimal degrees. Discharge is returned for the largest modeled river within 5 km of this point — no river ID required, and not necessarily the closest river. Vary the coordinate by about 0.1° and compare when the result looks unrepresentative. Use openmeteo_search_locations to resolve a place name.\"}, \"timezone\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"IANA timezone or \\\"auto\\\". Default \\\"auto\\\".\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"DataCanvas token for wide reanalysis queries. When a result is too large to return inline — driven by total payload size, so a multi-variable pull can spill at any row count — it spills to this canvas: pass the returned token to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it. Omit to create a fresh canvas.\"}, \"longitude\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in decimal degrees. With latitude it selects the largest modeled river within 5 km, which is not necessarily the closest one.\"}, \"start_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"Start date for historical reanalysis (YYYY-MM-DD, e.g., \\\"2023-01-01\\\"). GloFAS reanalysis covers from 1984-01-01. Requires end_date — the pair must be sent together, and neither combines with forecast_days.\"}, \"forecast_days\": {\"type\": \"integer\", \"maximum\": 210, \"minimum\": 1, \"description\": \"Number of forecast days ahead (1–210). Mutually exclusive with start_date/end_date — omit it entirely when pulling a historical range.\"}, \"daily_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 20, \"description\": \"Daily discharge variables to fetch (e.g., [\\\"river_discharge\\\", \\\"river_discharge_p25\\\", \\\"river_discharge_p75\\\", \\\"river_discharge_min\\\", \\\"river_discharge_max\\\"]). Required.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"latitude\", \"longitude\", \"timezone\", \"record_count\", \"daily\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"daily\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-day records with \\\"time\\\" (YYYY-MM-DD) + one key per requested variable containing discharge in m³/s, or null for coordinates outside GloFAS coverage. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"no_variables_requested\", \"date_range_incomplete\", \"forecast_days_conflict\", \"date_order_invalid\", \"date_out_of_range\", \"invalid_variable\", \"invalid_timezone\", \"request_too_large\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `no_variables_requested`: daily_variables was not provided or is empty. `date_range_incomplete`: Only one of start_date / end_date was provided — GloFAS requires the pair together. `forecast_days_conflict`: forecast_days was combined with start_date or end_date. `date_order_invalid`: end_date is before start_date. `date_out_of_range`: start_date predates 1984-01-01 or date range is otherwise invalid. `invalid_variable`: An unknown discharge variable name was requested. `invalid_timezone`: timezone was blank, or upstream did not recognize the requested time zone. `request_too_large`: Open-Meteo refused the request as asking for too much data in one call. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"notice\": {\"type\": \"string\", \"description\": \"Everything this response needs to say beyond the data, composed into one advisory: columns GloFAS returned with the unit \\\"undefined\\\" (a name it parsed but does not serve); recognized variables whose requested range falls outside the coordinate\'s discharge record, with the dates that do carry values; and, when the result spilled, either the canvas and table holding the full row set plus the two dataframe tools that read it, or — with DataCanvas disabled — why there is no canvas_id and how to reach the rows the preview omits.\"}, \"latitude\": {\"type\": \"number\", \"description\": \"Snapped latitude — grid point of the selected river\"}, \"timezone\": {\"type\": \"string\", \"description\": \"Resolved IANA timezone\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"DataCanvas token for the staged full dataset. Present only when truncated is true AND DataCanvas is enabled (CANVAS_PROVIDER_TYPE=duckdb) — absent otherwise, in which case the preview is all this response carries. Pass to openmeteo_dataframe_describe to list the staged table and its columns, then to openmeteo_dataframe_query to run SQL against it.\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Snapped longitude — grid point of the selected river\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the response was too large to return inline, so daily carries a bounded preview rather than the full set. With DataCanvas enabled the complete data is staged at canvas_id. With it disabled there is no canvas_id, and the omitted rows are reached only by narrowing the request.\"}, \"table_name\": {\"type\": \"string\", \"description\": \"DuckDB table name for the staged data — use as the FROM target in openmeteo_dataframe_query SQL; openmeteo_dataframe_describe lists its columns. Present only alongside canvas_id.\"}, \"daily_units\": {\"type\": \"object\", \"description\": \"Variable → unit string for daily data (e.g., {\\\"river_discharge\\\": \\\"m³/s\\\"}).\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"record_count\": {\"type\": \"number\", \"description\": \"Total number of daily discharge records — the full staged count when truncated is true, not the length of the daily preview.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, 'd5071ee624b3cfc56f8698adca846a78b84ede18486565f906676f53c8255bfb', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:31:41', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775452991787009, 2104773390069501953, 'openmeteo_get_climate', 'open-meteo-mcp:openmeteo_get_climate', 'Openmeteo Get Climate', 'Long-range climate projections from bias-corrected daily CMIP6 models, covering 1950-01-01 to 2050-12-31 at any coordinate. Answers \"what will conditions look like through 2050?\" — the future-projection counterpart to openmeteo_get_historical (the observed archive, what happened). Daily resolution only. Available models: CMCC_CM2_VHR4, FGOALS_f3_H, HiRAM_SIT_HR, MRI_AGCM3_2_S, EC_Earth3P_HR, MPI_ESM1_2_XR, NICAM16_8S. A model name outside that list is sent upstream rather than rejected here, so a model Open-Meteo adds later still works; if upstream rejects the request, the error names the offending model on its own rather than the whole requested list. With 2+ models each variable appears once per model with the model name as suffix (e.g. temperature_2m_max_CMCC_CM2_VHR4); a single or omitted model returns plain variable names. Not all models carry all variables — missing combinations return null. Multi-decade daily pulls across several models produce thousands of records and spill to a DataCanvas when canvas is enabled, returning canvas_id and table_name with truncated: true — inspect the staged columns with openmeteo_dataframe_describe, then query the full set with openmeteo_dataframe_query. With canvas disabled they return a bounded preview instead.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"latitude\", \"longitude\", \"start_date\", \"end_date\"], \"properties\": {\"models\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 7, \"description\": \"CMIP6 models to include: CMCC_CM2_VHR4, FGOALS_f3_H, HiRAM_SIT_HR, MRI_AGCM3_2_S, EC_Earth3P_HR, MPI_ESM1_2_XR, NICAM16_8S. With 2+ models each variable column is suffixed with the model name (e.g. temperature_2m_max_MRI_AGCM3_2_S). Omit to use the API default (a single model, unsuffixed columns). A name outside this list is sent upstream rather than rejected here.\"}, \"end_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"End date (YYYY-MM-DD, inclusive, max 2050-12-31). Must be on or after start_date.\"}, \"latitude\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude in decimal degrees. Use openmeteo_search_locations to resolve a place name to coordinates.\"}, \"timezone\": {\"type\": \"string\", \"default\": \"auto\", \"description\": \"IANA timezone or \\\"auto\\\". Default \\\"auto\\\".\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"DataCanvas token for multi-decade or multi-model queries. When a result is too large to return inline — driven by total payload size, so a wide multi-model pull can spill at any row count — it spills to this canvas: pass the returned token to openmeteo_dataframe_describe to list the staged table and its per-model columns, then to openmeteo_dataframe_query to run SQL against it. Omit to create a fresh canvas.\"}, \"longitude\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in decimal degrees.\"}, \"start_date\": {\"type\": \"string\", \"pattern\": \"^\\\\d{4}-\\\\d{2}-\\\\d{2}$\", \"description\": \"Start date (YYYY-MM-DD, e.g., \\\"2049-01-01\\\"). CMIP6 projections cover 1950-01-01 to 2050-12-31.\"}, \"daily_variables\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"description\": \"Daily climate variables to fetch (e.g., [\\\"temperature_2m_max\\\", \\\"temperature_2m_min\\\", \\\"precipitation_sum\\\", \\\"wind_speed_10m_mean\\\", \\\"shortwave_radiation_sum\\\"]). Required — the Climate API is daily-only.\"}, \"wind_speed_unit\": {\"enum\": [\"kmh\", \"mph\", \"ms\", \"kn\"], \"type\": \"string\", \"default\": \"kmh\", \"description\": \"Wind speed unit. Default \\\"kmh\\\".\"}, \"temperature_unit\": {\"enum\": [\"celsius\", \"fahrenheit\"], \"type\": \"string\", \"default\": \"celsius\", \"description\": \"Temperature unit. Default \\\"celsius\\\".\"}, \"precipitation_unit\": {\"enum\": [\"mm\", \"inch\"], \"type\": \"string\", \"default\": \"mm\", \"description\": \"Precipitation unit. Default \\\"mm\\\".\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"latitude\", \"longitude\", \"elevation\", \"timezone\", \"date_range\", \"record_count\", \"daily\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"daily\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Per-day records with \\\"time\\\" (YYYY-MM-DD) + one key per requested variable — per-model suffixed keys when 2+ models were requested (e.g. temperature_2m_max_CMCC_CM2_VHR4). Null values mean the model does not carry that variable. When truncated, contains only a preview — query canvas_id for the full dataset when one is present.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"date_out_of_range\", \"date_order_invalid\", \"no_variables_requested\", \"invalid_variable\", \"invalid_timezone\", \"request_too_large\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `date_out_of_range`: start_date predates 1950-01-01 or end_date is after 2050-12-31. `date_order_invalid`: end_date is before start_date. `no_variables_requested`: daily_variables was not provided or is empty. `invalid_variable`: An unknown variable name or unsupported climate model was requested. `invalid_timezone`: timezone was blank, or upstream did not recognize the requested time zone. `request_too_large`: Open-Meteo refused the request as asking for too much data in one call. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"models\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"Climate models requested — echoes the models parameter. Absent when models was omitted (API default model; the response carries no provenance).\"}, \"notice\": {\"type\": \"string\", \"description\": \"Everything this response needs to say beyond the data, composed into one advisory: columns the endpoint returned with the unit \\\"undefined\\\" (a name it parsed but does not serve); recognized variables a selected model carries no values for, with the dates that do carry values; and, when the result spilled, either the canvas and table holding the full row set plus the two dataframe tools that read it, or — with DataCanvas disabled — why there is no canvas_id and how to reach the rows the preview omits.\"}, \"latitude\": {\"type\": \"number\", \"description\": \"Snapped latitude (Open-Meteo snaps to nearest grid point)\"}, \"timezone\": {\"type\": \"string\", \"description\": \"Resolved IANA timezone\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"DataCanvas token for the staged full dataset. Present only when truncated is true AND DataCanvas is enabled (CANVAS_PROVIDER_TYPE=duckdb) — absent otherwise, in which case the preview is all this response carries. Pass to openmeteo_dataframe_describe to list the staged table and its per-model columns, then to openmeteo_dataframe_query to run SQL against it.\"}, \"elevation\": {\"type\": \"number\", \"description\": \"Elevation at grid point (meters)\"}, \"longitude\": {\"type\": \"number\", \"description\": \"Snapped longitude\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the response was too large to return inline, so daily carries a bounded preview rather than the full set. With DataCanvas enabled the complete data is staged at canvas_id. With it disabled there is no canvas_id, and the omitted rows are reached only by narrowing the request.\"}, \"date_range\": {\"type\": \"object\", \"required\": [\"start\", \"end\"], \"properties\": {\"end\": {\"type\": \"string\", \"description\": \"Actual end date of returned data\"}, \"start\": {\"type\": \"string\", \"description\": \"Actual start date of returned data\"}}, \"description\": \"Date range of returned data\", \"additionalProperties\": false}, \"table_name\": {\"type\": \"string\", \"description\": \"DuckDB table name for the staged data — use as the FROM target in openmeteo_dataframe_query SQL; openmeteo_dataframe_describe lists its columns, which is the only way to learn the per-model suffixes this request produced. Present only alongside canvas_id.\"}, \"daily_units\": {\"type\": \"object\", \"description\": \"Column → unit string for daily data (e.g., {\\\"temperature_2m_max_CMCC_CM2_VHR4\\\": \\\"°C\\\"}).\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"record_count\": {\"type\": \"number\", \"description\": \"Total number of daily records — the full upstream total when truncated is true, not the length of the daily preview.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, 'a530e585ea302613bb6de666bf67e7d4ebec2c242bf3762f2c28f847d5ac2dd7', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:07', 1, '2026-09-29 11:31:16', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775453071478785, 2104773390069501953, 'openmeteo_dataframe_query', 'open-meteo-mcp:openmeteo_dataframe_query', 'Openmeteo Dataframe Query', 'Run a read-only SQL SELECT against tables staged on a DataCanvas by openmeteo_get_forecast, openmeteo_get_historical, openmeteo_get_marine, openmeteo_get_air_quality, openmeteo_get_ensemble, openmeteo_get_flood, or openmeteo_get_climate. Pass the canvas_id returned when any of those tools spills (truncated: true), and reference the exact table_name those tools return alongside it. Call openmeteo_dataframe_describe to list staged tables and their columns when you need to discover names.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"canvas_id\", \"sql\"], \"properties\": {\"sql\": {\"type\": \"string\", \"description\": \"Read-only SELECT statement. Reference table names from openmeteo_dataframe_describe. Example: SELECT AVG(temperature_2m) AS avg_temp, strftime(time, \'%Y-%m\') AS month FROM spilled_abc123 GROUP BY month ORDER BY month\"}, \"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"Canvas ID returned by openmeteo_get_forecast, openmeteo_get_historical, openmeteo_get_marine, openmeteo_get_air_quality, openmeteo_get_ensemble, openmeteo_get_flood, or openmeteo_get_climate when truncated: true.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"rows\", \"row_count\", \"canvas_id\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"rows\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Result rows — a preview capped at 100. When row_count exceeds this, page the rest by re-issuing the SQL with LIMIT / OFFSET.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"canvas_not_enabled\", \"canvas_not_found\", \"system_catalog_access\", \"missing_table\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `canvas_not_enabled`: CANVAS_PROVIDER_TYPE is not set to duckdb. `canvas_not_found`: The canvas_id is unknown or has expired (TTL is 24 h sliding). `system_catalog_access`: The SQL references a system catalog (information_schema, sqlite_master, pg_catalog, or a duckdb_*() function). `missing_table`: The SQL references a table that is not staged on this canvas — a mistyped name, or one that expired (24 h sliding TTL) or was dropped. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"canvas_id\": {\"type\": \"string\", \"description\": \"Canvas ID that was queried.\"}, \"row_count\": {\"type\": \"number\", \"description\": \"Total rows in the full result before any cap.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true}', NULL, 'b02dca4ee295f0cfa2492ef8290f15ea84cfbf97647635ebec8ad7655634890b', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:08', 1, '2026-09-29 11:31:03', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775453071478786, 2104773390069501953, 'openmeteo_dataframe_describe', 'open-meteo-mcp:openmeteo_dataframe_describe', 'Openmeteo Dataframe Describe', 'List the tables and their columns on a DataCanvas staged by openmeteo_get_forecast, openmeteo_get_historical, openmeteo_get_marine, openmeteo_get_air_quality, openmeteo_get_ensemble, openmeteo_get_flood, or openmeteo_get_climate. Call this first to discover table names before querying with openmeteo_dataframe_query.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"canvas_id\"], \"properties\": {\"canvas_id\": {\"type\": \"string\", \"pattern\": \"^[A-Za-z0-9_-]{10}$\", \"description\": \"Canvas ID returned by openmeteo_get_forecast, openmeteo_get_historical, openmeteo_get_marine, openmeteo_get_air_quality, openmeteo_get_ensemble, openmeteo_get_flood, or openmeteo_get_climate when truncated: true.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"canvas_id\", \"tables\", \"expires_at\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"canvas_not_enabled\", \"canvas_not_found\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `canvas_not_enabled`: CANVAS_PROVIDER_TYPE is not set to duckdb. `canvas_not_found`: The canvas_id is unknown or has expired (TTL is 24 h sliding). Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"tables\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"name\", \"kind\", \"row_count\", \"columns\"], \"properties\": {\"kind\": {\"enum\": [\"table\", \"view\"], \"type\": \"string\", \"description\": \"Whether this is a base table or a view.\"}, \"name\": {\"type\": \"string\", \"description\": \"Table name — pass to openmeteo_dataframe_query.\"}, \"columns\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"name\", \"type\", \"nullable\"], \"properties\": {\"name\": {\"type\": \"string\", \"description\": \"Column name.\"}, \"type\": {\"type\": \"string\", \"description\": \"DuckDB type (e.g. VARCHAR, DOUBLE, TIMESTAMP).\"}, \"nullable\": {\"type\": \"boolean\", \"description\": \"Whether the column allows NULL.\"}}, \"description\": \"A column: name, DuckDB type, and nullability.\", \"additionalProperties\": false}, \"description\": \"Column schema.\"}, \"row_count\": {\"type\": \"number\", \"description\": \"Number of rows.\"}}, \"description\": \"A table or view on the canvas: name, kind, row count, and column schema.\", \"additionalProperties\": false}, \"description\": \"Tables and views registered on this canvas.\"}, \"canvas_id\": {\"type\": \"string\", \"description\": \"Canvas ID that was inspected.\"}, \"expires_at\": {\"type\": \"string\", \"description\": \"ISO 8601 expiry after the sliding 24 h TTL.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"idempotentHint\": true}', NULL, '3e138f0a5befc79d68d73b98683a5d5c6f33d4a82603299bb9c22dc7c568b550', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:07', 100, 1, '2026-09-29 11:29:08', 1, '2026-09-29 11:30:30', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775540434636801, 2104774189336072193, 'openstreetmap_search_places', 'openstreetmap-mcp:openstreetmap_search_places', 'Geocode a place name or address', 'Geocode a place name or address to coordinates and structured place data via Nominatim. Send either a free-form query or the structured address fields (street, city, county, state, country, postalcode), never both; results are the best-ranked matches, not every matching object, and matching never uses an OSM attribute tag, so filter or enumerate by tag with openstreetmap_query_nearby, openstreetmap_query_bbox, or openstreetmap_query_raw.', '{\"type\": \"object\", \"anyOf\": [{\"type\": \"object\", \"required\": [\"query\"]}, {\"type\": \"object\", \"required\": [\"street\"]}, {\"type\": \"object\", \"required\": [\"city\"]}, {\"type\": \"object\", \"required\": [\"county\"]}, {\"type\": \"object\", \"required\": [\"state\"]}, {\"type\": \"object\", \"required\": [\"country\"]}, {\"type\": \"object\", \"required\": [\"postalcode\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"city\": {\"type\": \"string\", \"description\": \"City name (structured query).\"}, \"layer\": {\"anyOf\": [{\"type\": \"string\", \"const\": \"\"}, {\"type\": \"string\", \"pattern\": \"^\\\\s*(?:(?:[aA][dD][dD][rR][eE][sS][sS]|[pP][oO][iI]|[rR][aA][iI][lL][wW][aA][yY]|[nN][aA][tT][uU][rR][aA][lL]|[mM][aA][nN][mM][aA][dD][eE])(?:\\\\s*,\\\\s*(?:[aA][dD][dD][rR][eE][sS][sS]|[pP][oO][iI]|[rR][aA][iI][lL][wW][aA][yY]|[nN][aA][tT][uU][rR][aA][lL]|[mM][aA][nN][mM][aA][dD][eE]))*)?\\\\s*$\", \"description\": \"One documented layer name, or a comma-separated list of them, in any casing.\"}], \"description\": \"Filter by data layer: one of address, poi, railway, natural, manmade, or a comma-separated list of them, in any casing. Any other name is rejected here, not upstream; an empty value counts as omitted. Default: no restriction.\"}, \"limit\": {\"type\": \"integer\", \"default\": 5, \"maximum\": 40, \"minimum\": 1, \"description\": \"Maximum results to return. Nominatim may return fewer when additional results do not sufficiently match. Max 40.\"}, \"query\": {\"type\": \"string\", \"description\": \"Free-form search string, e.g. \\\"Space Needle Seattle\\\" or \\\"1600 Pennsylvania Ave NW, Washington DC\\\". Not combinable with the structured address fields. Nominatim reads commas as an address hierarchy, so give the name plus its city or region and nothing in between: \\\"Beinecke Library, New Haven\\\" matches where \\\"Beinecke Library, Yale University, New Haven\\\" returns nothing.\"}, \"state\": {\"type\": \"string\", \"description\": \"State or province (structured query).\"}, \"county\": {\"type\": \"string\", \"description\": \"County or district (structured query).\"}, \"street\": {\"type\": \"string\", \"description\": \"House number and street name (structured query). Use with city/state/country fields. Cannot be combined with query.\"}, \"bounded\": {\"type\": \"boolean\", \"description\": \"Restrict results to the viewbox instead of merely biasing toward it. Requires viewbox — setting it alone is rejected rather than ignored. With it, a match outside the box is dropped even when it scores higher.\"}, \"country\": {\"type\": \"string\", \"description\": \"Country name or ISO 3166-1 alpha-2 code (structured query).\"}, \"viewbox\": {\"type\": \"object\", \"required\": [\"west\", \"south\", \"east\", \"north\"], \"properties\": {\"east\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Eastern boundary longitude. Must be strictly greater than west.\"}, \"west\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Western boundary longitude. Must be strictly less than east.\"}, \"north\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Northern boundary latitude. Must be strictly greater than south.\"}, \"south\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Southern boundary latitude. Must be strictly less than north.\"}}, \"description\": \"Rectangular area to bias results toward, disambiguating a name that repeats worldwide (a creek in one watershed, a street in one municipality). Narrower than countrycodes. Bias only by default: a better match outside the box is still returned. Set bounded for a hard restriction. Unlike openstreetmap_query_bbox this box may not cross the antimeridian — west must be less than east and south less than north, or the call is rejected.\"}, \"language\": {\"type\": \"string\", \"description\": \"Preferred language for result names (BCP 47 code or Accept-Language string, e.g., \\\"en\\\", \\\"de\\\", \\\"fr,en\\\"). Defaults to local OSM language.\"}, \"extratags\": {\"type\": \"boolean\", \"default\": false, \"description\": \"Include the matched object\'s extra OSM tags — contact and metadata (phone, website, opening_hours, wikidata) and physical attributes (surface, tracktype, sac_scale, ele, access). An absent tag describes that object, not OpenStreetMap. Increases response size.\"}, \"postalcode\": {\"type\": \"string\", \"description\": \"Postal or ZIP code (structured query).\"}, \"featureType\": {\"enum\": [\"country\", \"state\", \"city\", \"settlement\"], \"type\": \"string\", \"description\": \"Restrict results to a geographic feature type. Automatically implies the address layer.\"}, \"countrycodes\": {\"anyOf\": [{\"type\": \"string\", \"const\": \"\"}, {\"type\": \"string\", \"pattern\": \"^\\\\s*(?:[A-Za-z]{2}\\\\s*)?(?:,\\\\s*(?:[A-Za-z]{2}\\\\s*)?)*$\", \"description\": \"One ISO 3166-1 alpha-2 country code, or a comma-separated list of them, in any casing.\"}], \"description\": \"Restrict results to one or more countries: comma-separated ISO 3166-1 alpha-2 codes (e.g. \\\"us,ca\\\"), any casing, optional spaces around the commas. Any other form — alpha-3, a semicolon list, a country name — is rejected rather than silently dropped upstream. A well-formed code for a country that does not exist matches nothing. An empty value counts as omitted. Prefer this over the structured country field for filtering.\"}, \"exclude_place_ids\": {\"type\": \"array\", \"items\": {\"anyOf\": [{\"type\": \"string\", \"const\": \"\"}, {\"type\": \"string\", \"pattern\": \"^\\\\s*(?:[NWRnwr]\\\\d+|\\\\d+)?\\\\s*$\", \"description\": \"An OSM ref (N/W/R plus the object id) or a bare Nominatim place_id.\"}], \"description\": \"One exclusion token, or an empty value that excludes nothing.\"}, \"description\": \"OSM refs (N/W/R + id) or Nominatim place_ids to drop from results; any other token form is rejected here rather than by Nominatim. Entries are trimmed, lowercase ref prefixes uppercased, a blank entry treated as absent. Page toward further matches by passing back a prior full page\'s nextExcludeIds, which prefers stable OSM refs over volatile place_ids; the walk ends when a page returns zero results with an exhaustion notice — a success, not an error. Best-effort, not a cursor: Nominatim ranking can reorder between calls, so already-seen results may shift.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"results\", \"total\", \"attribution\", \"effectiveQuery\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"cap\": {\"type\": \"number\", \"description\": \"The limit applied to this request.\"}, \"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"no_results\", \"conflicting_query_mode\", \"missing_query_mode\", \"bounded_without_viewbox\", \"invalid_viewbox\", \"invalid_parameters\", \"rate_limited\", \"upstream_error\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `no_results`: No places matched, and no exclude_place_ids were supplied — an exhausted paging walk returns success with zero results instead. `conflicting_query_mode`: query and at least one structured address field were both supplied; the two modes are mutually exclusive. `missing_query_mode`: Neither query nor any structured address field was supplied. `bounded_without_viewbox`: bounded was set without a viewbox for it to restrict results to. `invalid_viewbox`: The viewbox is inverted or degenerate: west at or beyond east, or south at or beyond north. `invalid_parameters`: Nominatim returned HTTP 400, refusing one of the forwarded parameters; its own message names which one. `rate_limited`: Nominatim returned HTTP 429, or HTTP 200 with a throttle document in place of JSON — the one request per second policy was exceeded. `upstream_error`: Nominatim returned a non-2xx status other than 429, or HTTP 200 with a non-JSON body carrying no throttle signature. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"shown\": {\"type\": \"number\", \"description\": \"Number of results returned.\"}, \"total\": {\"type\": \"number\", \"description\": \"Number of results returned.\"}, \"notice\": {\"type\": \"string\", \"description\": \"Paging guidance, in two cases: results were capped at limit with a probe confirming a further match at the query\'s relevance cutoff (truncated true — keep paging with nextExcludeIds), or an exclude_place_ids walk was exhausted and the page came back empty (the query matched; the walk simply ended, so no rewrite is needed). Tell them apart by truncated and the result count, not by this field\'s presence. Absent when a page returns below the limit, and when it fills the limit with nothing past the cutoff — read nextExcludeIds for whether paging can continue.\"}, \"results\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"place_id\", \"lat\", \"lon\", \"display_name\"], \"properties\": {\"lat\": {\"type\": \"number\", \"description\": \"Latitude in WGS84 decimal degrees.\"}, \"lon\": {\"type\": \"number\", \"description\": \"Longitude in WGS84 decimal degrees.\"}, \"name\": {\"type\": \"string\", \"description\": \"Feature name; absent for address-only results.\"}, \"type\": {\"type\": \"string\", \"description\": \"OSM feature type within category (e.g. \\\"hospital\\\", \\\"tower\\\").\"}, \"osm_id\": {\"type\": \"number\", \"description\": \"OSM object ID. Combine with osm_type for openstreetmap_lookup_objects, or pass \\\"R\\\"/\\\"W\\\" + this id as within on openstreetmap_query_bbox to search inside this boundary. The same scope in openstreetmap_query_raw is rel();map_to_area->.a; or way();map_to_area->.a; then (area.a) on each statement.\"}, \"address\": {\"type\": \"object\", \"description\": \"Structured address breakdown, keys varying by feature type and country: house_number, road, suburb, city, state, postcode, country, country_code.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"category\": {\"type\": \"string\", \"description\": \"OSM feature category (e.g. \\\"amenity\\\", \\\"man_made\\\").\"}, \"osm_type\": {\"enum\": [\"node\", \"way\", \"relation\"], \"type\": \"string\", \"description\": \"OSM object type.\"}, \"place_id\": {\"type\": \"number\", \"description\": \"Nominatim internal place ID. Stable cross-server reference: osm_type+osm_id.\"}, \"extratags\": {\"type\": \"object\", \"description\": \"Extra OSM tags this object carries — contact and metadata (phone, website, opening_hours, wikidata) and physical attributes (surface, tracktype, sac_scale, ele, access). Present only when extratags was requested; an absent tag describes this object, not OpenStreetMap.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"importance\": {\"type\": \"number\", \"description\": \"Nominatim relevance score (0–1). Higher is more globally prominent.\"}, \"boundingbox\": {\"type\": \"array\", \"items\": false, \"maxItems\": 4, \"minItems\": 4, \"description\": \"Bounding box as [south, north, west, east] in WGS84 decimal degrees.\", \"prefixItems\": [{\"type\": \"number\"}, {\"type\": \"number\"}, {\"type\": \"number\"}, {\"type\": \"number\"}]}, \"display_name\": {\"type\": \"string\", \"description\": \"Full human-readable address string.\"}}, \"description\": \"A single geocoding result.\", \"additionalProperties\": false}, \"description\": \"Geocoding results, ordered by Nominatim relevance (importance score descending).\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True when the page filled the requested limit and a same-call probe confirmed another match at this query\'s relevance cutoff; absent otherwise. Absence is not exhaustion — excluding a full page\'s ids can still surface less accurate matches past that cutoff, which is why nextExcludeIds is offered on any full page. Nominatim reports no total, so this is a confirmed observation, not an inference from page size.\"}, \"attribution\": {\"type\": \"string\", \"description\": \"Required data attribution: Data © OpenStreetMap contributors, ODbL 1.0.\"}, \"boundedApplied\": {\"type\": \"boolean\", \"description\": \"True when the viewbox was a hard restriction (bounded=1 was sent), false when it biased ranking only and a match outside it could still be returned. Absent when no viewbox was supplied.\"}, \"effectiveQuery\": {\"type\": \"string\", \"description\": \"The effective query sent to Nominatim — the free-form query string, or a reconstructed string from the provided structured address fields.\"}, \"nextExcludeIds\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"Accumulated exclude tokens (prior excludes plus this page) to pass as exclude_place_ids on the next call. Each is a stable OSM ref (N/W/R + osm_id) when the result carries one, the Nominatim place_id otherwise. Present whenever the page filled the requested limit, whether or not truncated is set: excluding a full page can surface less accurate matches past the probe\'s cutoff. Best-effort, not a cursor — ranking can reorder between calls, so a walk can end sooner than the page count suggests.\"}, \"effectiveViewbox\": {\"type\": \"object\", \"required\": [\"west\", \"south\", \"east\", \"north\"], \"properties\": {\"east\": {\"type\": \"number\", \"description\": \"Eastern boundary longitude sent to Nominatim.\"}, \"west\": {\"type\": \"number\", \"description\": \"Western boundary longitude sent to Nominatim.\"}, \"north\": {\"type\": \"number\", \"description\": \"Northern boundary latitude sent to Nominatim.\"}, \"south\": {\"type\": \"number\", \"description\": \"Southern boundary latitude sent to Nominatim.\"}}, \"description\": \"The viewbox forwarded to Nominatim on this call, echoed so an ambiguous result can be read against the area that scoped it. Absent when no viewbox was supplied.\", \"additionalProperties\": false}, \"tagSelectionCaveat\": {\"type\": \"string\", \"description\": \"Standing caveat: tag-based selection lives on the Overpass tools (openstreetmap_query_nearby, openstreetmap_query_bbox, openstreetmap_query_raw), never here. extratags decorates the returned objects rather than selecting them, so a missing tag is not evidence the tag is missing from OpenStreetMap. Present on every successful response.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"openWorldHint\": true, \"idempotentHint\": true}', NULL, 'c885597e3e6ab1f4e177e57364711fb314bf56b6a7913ebaeacc1541a0d237c1', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:28', 100, 1, '2026-09-29 11:29:28', 1, '2026-09-29 11:32:51', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775540526911489, 2104774189336072193, 'openstreetmap_reverse_geocode', 'openstreetmap-mcp:openstreetmap_reverse_geocode', 'Reverse geocode coordinates to an address', 'Convert a latitude/longitude pair to the nearest address or named place via Nominatim. The result is the closest indexed OSM object at the requested zoom (18 building, 10 city), which in dense areas can be a neighbouring feature rather than the one containing the coordinate; proximity and layer pick it, never an OSM attribute tag, so find features by tag with openstreetmap_query_nearby, openstreetmap_query_bbox, or openstreetmap_query_raw.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"lat\", \"lon\"], \"properties\": {\"lat\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Latitude in WGS84 decimal degrees.\"}, \"lon\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Longitude in WGS84 decimal degrees.\"}, \"zoom\": {\"type\": \"integer\", \"default\": 18, \"maximum\": 18, \"minimum\": 3, \"description\": \"Address detail level, roughly corresponding to map zoom. 18=building, 16=street, 14=neighbourhood, 12=town, 10=city, 8=county, 5=state, 3=country.\"}, \"layer\": {\"anyOf\": [{\"type\": \"string\", \"const\": \"\"}, {\"type\": \"string\", \"pattern\": \"^\\\\s*(?:(?:[aA][dD][dD][rR][eE][sS][sS]|[pP][oO][iI]|[rR][aA][iI][lL][wW][aA][yY]|[nN][aA][tT][uU][rR][aA][lL]|[mM][aA][nN][mM][aA][dD][eE])(?:\\\\s*,\\\\s*(?:[aA][dD][dD][rR][eE][sS][sS]|[pP][oO][iI]|[rR][aA][iI][lL][wW][aA][yY]|[nN][aA][tT][uU][rR][aA][lL]|[mM][aA][nN][mM][aA][dD][eE]))*)?\\\\s*$\", \"description\": \"One documented layer name, or a comma-separated list of them, in any casing.\"}], \"description\": \"Restrict which OSM layer is matched: one of address, poi, railway, natural, manmade, or a comma-separated list of them, in any casing. Any other name is rejected here, not upstream; an empty value counts as omitted. Default: address,poi.\"}, \"language\": {\"type\": \"string\", \"description\": \"Preferred language for the result (BCP 47 code or Accept-Language string).\"}, \"extratags\": {\"type\": \"boolean\", \"default\": false, \"description\": \"Include the matched object\'s extra OSM tags — contact and metadata (phone, website, opening_hours, wikidata) and physical attributes (surface, tracktype, sac_scale, ele, access). An absent tag describes that object, not OpenStreetMap.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"result\", \"attribution\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"no_coverage\", \"invalid_parameters\", \"rate_limited\", \"upstream_error\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `no_coverage`: Nominatim reported no OSM data at the coordinates — open ocean or unmapped territory. `invalid_parameters`: Nominatim returned HTTP 400, refusing one of the forwarded parameters; its own message names which one. `rate_limited`: Nominatim returned HTTP 429, or HTTP 200 with a throttle document in place of JSON — the one request per second policy was exceeded. `upstream_error`: Nominatim returned a non-2xx status other than 429, or HTTP 200 with a non-JSON body carrying no throttle signature. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"result\": {\"type\": \"object\", \"required\": [\"place_id\", \"lat\", \"lon\", \"display_name\"], \"properties\": {\"lat\": {\"type\": \"number\", \"description\": \"Latitude in WGS84 decimal degrees.\"}, \"lon\": {\"type\": \"number\", \"description\": \"Longitude in WGS84 decimal degrees.\"}, \"name\": {\"type\": \"string\", \"description\": \"Feature name when the object is named.\"}, \"type\": {\"type\": \"string\", \"description\": \"OSM feature type within category.\"}, \"osm_id\": {\"type\": \"number\", \"description\": \"OSM object ID. Combine with osm_type for openstreetmap_lookup_objects, or pass \\\"R\\\"/\\\"W\\\" + this id as within on openstreetmap_query_bbox to search inside this boundary. The same scope in openstreetmap_query_raw is rel();map_to_area->.a; or way();map_to_area->.a; then (area.a) on each statement.\"}, \"address\": {\"type\": \"object\", \"description\": \"Structured address, keys varying by feature type: house_number, road, suburb, city, state, postcode, country, country_code.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"category\": {\"type\": \"string\", \"description\": \"OSM feature category (e.g. \\\"amenity\\\", \\\"building\\\").\"}, \"osm_type\": {\"enum\": [\"node\", \"way\", \"relation\"], \"type\": \"string\", \"description\": \"OSM object type.\"}, \"place_id\": {\"type\": \"number\", \"description\": \"Nominatim internal place ID.\"}, \"extratags\": {\"type\": \"object\", \"description\": \"Extra OSM tags this object carries — contact and metadata (phone, website, opening_hours, wikidata) and physical attributes (surface, tracktype, sac_scale, ele, access). Present only when extratags was requested; an absent tag describes this object, not OpenStreetMap.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"boundingbox\": {\"type\": \"array\", \"items\": false, \"maxItems\": 4, \"minItems\": 4, \"description\": \"Bounding box as [south, north, west, east] in WGS84 decimal degrees.\", \"prefixItems\": [{\"type\": \"number\"}, {\"type\": \"number\"}, {\"type\": \"number\"}, {\"type\": \"number\"}]}, \"display_name\": {\"type\": \"string\", \"description\": \"Full human-readable address.\"}}, \"description\": \"The closest matching OSM object at the given coordinates.\", \"additionalProperties\": false}, \"attribution\": {\"type\": \"string\", \"description\": \"Required data attribution.\"}, \"tagSelectionCaveat\": {\"type\": \"string\", \"description\": \"Standing caveat: tag-based selection lives on the Overpass tools (openstreetmap_query_nearby, openstreetmap_query_bbox, openstreetmap_query_raw), never here. extratags decorates the returned objects rather than selecting them, so a missing tag is not evidence the tag is missing from OpenStreetMap. Present when extratags was requested.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"openWorldHint\": true, \"idempotentHint\": true}', NULL, 'a02c6ee59b697d66542f47beaf9d8dde1ed4b553e856b0e3f69d453a2ba7aef5', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:28', 100, 1, '2026-09-29 11:29:28', 1, '2026-09-29 11:32:56', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775540564660226, 2104774189336072193, 'openstreetmap_lookup_objects', 'openstreetmap-mcp:openstreetmap_lookup_objects', 'Look up address details for OSM objects by ID', 'Fetch the Nominatim address record for up to 50 known OSM objects by ID, each prefixed N (node), W (way), or R (relation), e.g. \"N240109189\". Use it for IDs already in hand from openstreetmap_query_nearby or openstreetmap_query_bbox; it returns only objects named in osm_ids, listing any that resolve to nothing under not_found, and cannot select by tag, so discover objects with those tools or openstreetmap_query_raw first.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"osm_ids\"], \"properties\": {\"osm_ids\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"maxItems\": 50, \"minItems\": 1, \"description\": \"OSM IDs to look up, each prefixed with N (node), W (way), or R (relation). Always an array, including for a single ID: [\\\"N240109189\\\"], [\\\"W50637691\\\", \\\"R146656\\\"]. Up to 50 IDs per call.\"}, \"language\": {\"type\": \"string\", \"description\": \"Preferred language for names (BCP 47 code).\"}, \"extratags\": {\"type\": \"boolean\", \"default\": false, \"description\": \"Include each looked-up object\'s extra OSM tags — contact and metadata (phone, website, opening_hours, wikidata) and physical attributes (surface, tracktype, sac_scale, ele, access). An absent tag describes that object, not OpenStreetMap.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"results\", \"not_found\", \"total\", \"attribution\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"invalid_id_format\", \"invalid_parameters\", \"rate_limited\", \"upstream_error\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `invalid_id_format`: An array element is not a single N/W/R-prefixed OSM ID. `invalid_parameters`: Nominatim returned HTTP 400, refusing one of the forwarded parameters; its own message names which one. `rate_limited`: Nominatim returned HTTP 429, or HTTP 200 with a throttle document in place of JSON — the one request per second policy was exceeded. `upstream_error`: Nominatim returned a non-2xx status other than 429, or HTTP 200 with a non-JSON body carrying no throttle signature. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"total\": {\"type\": \"number\", \"description\": \"Number of results returned.\"}, \"results\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"place_id\", \"lat\", \"lon\", \"display_name\"], \"properties\": {\"lat\": {\"type\": \"number\", \"description\": \"Latitude in WGS84 decimal degrees.\"}, \"lon\": {\"type\": \"number\", \"description\": \"Longitude in WGS84 decimal degrees.\"}, \"name\": {\"type\": \"string\", \"description\": \"Feature name if applicable.\"}, \"type\": {\"type\": \"string\", \"description\": \"OSM feature type within category.\"}, \"osm_id\": {\"type\": \"number\", \"description\": \"OSM object ID. Pass \\\"R\\\"/\\\"W\\\" + this id as within on openstreetmap_query_bbox to search inside this boundary. The same scope in openstreetmap_query_raw is rel();map_to_area->.a; or way();map_to_area->.a; then (area.a) on each statement.\"}, \"address\": {\"type\": \"object\", \"description\": \"Structured address breakdown. Keys vary by feature type.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"category\": {\"type\": \"string\", \"description\": \"OSM feature category.\"}, \"osm_type\": {\"enum\": [\"node\", \"way\", \"relation\"], \"type\": \"string\", \"description\": \"OSM object type.\"}, \"place_id\": {\"type\": \"number\", \"description\": \"Nominatim internal place ID.\"}, \"extratags\": {\"type\": \"object\", \"description\": \"Extra OSM tags this object carries — contact and metadata (phone, website, opening_hours, wikidata) and physical attributes (surface, tracktype, sac_scale, ele, access). Present only when extratags was requested; an absent tag describes this object, not OpenStreetMap.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"boundingbox\": {\"type\": \"array\", \"items\": false, \"maxItems\": 4, \"minItems\": 4, \"description\": \"Bounding box as [south, north, west, east] in WGS84 decimal degrees.\", \"prefixItems\": [{\"type\": \"number\"}, {\"type\": \"number\"}, {\"type\": \"number\"}, {\"type\": \"number\"}]}, \"display_name\": {\"type\": \"string\", \"description\": \"Full human-readable address string.\"}}, \"description\": \"Address details for a single OSM ID lookup result.\", \"additionalProperties\": false}, \"description\": \"Address details for the requested OSM IDs that were found.\"}, \"not_found\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"OSM IDs from the request that returned no result.\"}, \"attribution\": {\"type\": \"string\", \"description\": \"Required data attribution: Data © OpenStreetMap contributors, ODbL 1.0.\"}, \"tagSelectionCaveat\": {\"type\": \"string\", \"description\": \"Standing caveat: tag-based selection lives on the Overpass tools (openstreetmap_query_nearby, openstreetmap_query_bbox, openstreetmap_query_raw), never here. extratags decorates the returned objects rather than selecting them, so a missing tag is not evidence the tag is missing from OpenStreetMap. Present when extratags was requested.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"openWorldHint\": true, \"idempotentHint\": true}', NULL, '52d96e8aa5eecb997d8c39347a59ac4da3a8d60e9d9ef6a45bcc1d36d2e58d2c', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:28', 100, 1, '2026-09-29 11:29:28', 1, '2026-09-29 11:33:16', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775540564660227, 2104774189336072193, 'openstreetmap_query_nearby', 'openstreetmap-mcp:openstreetmap_query_nearby', 'Find OSM features near a point', 'Find OSM features within a radius of a point via the Overpass API, the tool for \"what is near X?\" questions. Filter with amenity, or with tag_key plus an optional tag_value, ANDing up to five more filters; every feature returns with its full OSM tag set (no extratags flag here), sorted nearest-first by distance_meters, with nodes covering standalone POIs and ways covering buildings and areas.', '{\"type\": \"object\", \"anyOf\": [{\"type\": \"object\", \"required\": [\"amenity\"]}, {\"type\": \"object\", \"required\": [\"tag_key\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"lat\", \"lon\"], \"properties\": {\"lat\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Center latitude in WGS84 decimal degrees.\"}, \"lon\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Center longitude in WGS84 decimal degrees.\"}, \"limit\": {\"type\": \"integer\", \"default\": 20, \"maximum\": 500, \"minimum\": 1, \"description\": \"Maximum results to return. Applied after the Overpass query — if the area has more features, they are truncated.\"}, \"offset\": {\"type\": \"integer\", \"default\": 0, \"maximum\": 9007199254740991, \"minimum\": 0, \"description\": \"Number of matching features to skip before applying limit, for paging through a large result set. Features are distance-sorted before paging, so higher offsets return progressively farther matches; the full set is cached ~10 minutes so re-paging costs no extra upstream request. Pass the nextOffset value from a prior truncated response.\"}, \"amenity\": {\"type\": \"string\", \"description\": \"OSM amenity tag value (e.g. \\\"hospital\\\", \\\"pharmacy\\\", \\\"restaurant\\\", \\\"atm\\\"), shortcut for tag_key=\\\"amenity\\\". Exactly one primary mode is required: this or tag_key, never both.\"}, \"filters\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"key\"], \"properties\": {\"key\": {\"type\": \"string\", \"description\": \"Literal OSM tag key. Trimmed and nonblank; must be unique across the primary tag and all filters.\"}, \"value\": {\"type\": \"string\", \"description\": \"Literal exact-match value. Omit for key existence; an explicitly blank value is invalid. Trimmed before matching.\"}}, \"description\": \"One additional literal equality or key-existence filter.\", \"additionalProperties\": false}, \"maxItems\": 5, \"description\": \"Up to five additional filters, ANDed with the required primary amenity or tag_key filter in input order. Omitted or [] adds no conditions. Keys must be unique after trimming; keys and values must not contain Overpass QL metacharacters (\\\" \\\\ [ ] ; ( )).\"}, \"tag_key\": {\"type\": \"string\", \"description\": \"Primary OSM tag key (e.g. \\\"leisure\\\", \\\"shop\\\", \\\"highway\\\"); omit tag_value to match any feature carrying the key, or supply it for exact equality. The alternative to amenity, never both. Additional filters are ANDed with this tag.\"}, \"tag_value\": {\"type\": \"string\", \"description\": \"Literal value paired with tag_key for exact equality (e.g., \\\"park\\\", \\\"supermarket\\\"); omit for key existence. Explicit empty or whitespace-only values are invalid. Keys and values are trimmed; blank unused fields are ignored in amenity mode.\"}, \"element_types\": {\"type\": \"array\", \"items\": {\"enum\": [\"node\", \"way\", \"relation\"], \"type\": \"string\"}, \"default\": [\"node\", \"way\"], \"minItems\": 1, \"description\": \"OSM element types to search, at least one. Ways cover most buildings and areas; nodes cover most standalone POIs. Add \\\"relation\\\" for complex structures like large campuses. Omit the field to search nodes and ways; an empty array is rejected because it can only match nothing.\"}, \"radius_meters\": {\"type\": \"number\", \"default\": 1000, \"maximum\": 50000, \"description\": \"Search radius in meters. Max 50,000m (50km). Keep under 5,000m for dense urban POI queries to avoid slow responses.\", \"exclusiveMinimum\": 0}, \"timeout_seconds\": {\"type\": \"integer\", \"default\": 25, \"maximum\": 60, \"minimum\": 5, \"description\": \"Overpass query timeout in seconds. Increase for large radius or dense areas.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"elements\", \"attribution\", \"effectiveTag\", \"totalFound\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"invalid_tag\", \"query_timeout\", \"result_too_large\", \"rate_limited\", \"upstream_error\", \"overpass_gateway_timeout\", \"overpass_unavailable\", \"endpoints_exhausted\", \"endpoints_unavailable\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `invalid_tag`: Tag modes conflict or are missing, a key or supplied value is blank, keys repeat after trimming, or a filter carries Overpass QL metacharacters. `query_timeout`: The query exceeded timeout_seconds. `result_too_large`: Overpass ran out of memory on this query. `rate_limited`: Every configured endpoint refused the query as throttled — HTTP 429, or a throttle document in place of JSON. `upstream_error`: Overpass reported a runtime error that is neither a timeout nor memory exhaustion. `overpass_gateway_timeout`: Overpass answered HTTP 504 — the query exceeded the endpoint\'s own time budget, not timeout_seconds. `overpass_unavailable`: Overpass answered an HTTP 5xx other than 504 — the endpoint is down, restarting, or shedding load. `endpoints_exhausted`: No endpoint answered within its attempt window, or the total time budget ran out first. `endpoints_unavailable`: No configured endpoint would serve the call — connections refused, DNS failures, HTTP refusals such as 401/403/404, throttling, or instance faults, in some mix. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"notice\": {\"type\": \"string\", \"description\": \"Why this page is empty and what to try: nothing matched (widen the radius or change the tag), or offset ran past the end (retry lower). Absent when results were returned.\"}, \"elements\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"osm_type\", \"osm_id\", \"tags\"], \"properties\": {\"lat\": {\"type\": \"number\", \"description\": \"Latitude (present for nodes and ways/relations with computed center).\"}, \"lon\": {\"type\": \"number\", \"description\": \"Longitude (present for nodes and ways/relations with computed center).\"}, \"name\": {\"type\": \"string\", \"description\": \"Feature name from OSM tags.\"}, \"tags\": {\"type\": \"object\", \"description\": \"All OSM tags for this feature. Values are always strings.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"osm_id\": {\"type\": \"number\", \"description\": \"OSM element ID. Use with osm_type for openstreetmap_lookup_objects.\"}, \"osm_type\": {\"enum\": [\"node\", \"way\", \"relation\"], \"type\": \"string\", \"description\": \"OSM element type.\"}, \"distance_meters\": {\"type\": \"number\", \"description\": \"Great-circle distance in meters from the query center, rounded to one decimal. Results are sorted ascending by this value; omitted for elements without a computed coordinate.\"}}, \"description\": \"A single matching OSM feature.\", \"additionalProperties\": false}, \"description\": \"Matching OSM features, up to the limit.\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True if results were cut at the limit. Reduce radius, add more specific tags, or page with offset to retrieve the rest.\"}, \"nextOffset\": {\"type\": \"number\", \"description\": \"Offset to pass on the next call to retrieve the following page of features. Present only when more features remain beyond this page.\"}, \"totalFound\": {\"type\": \"number\", \"description\": \"Total features returned by Overpass before limit truncation.\"}, \"attribution\": {\"type\": \"string\", \"description\": \"Required data attribution: Data © OpenStreetMap contributors, ODbL 1.0.\"}, \"effectiveTag\": {\"type\": \"string\", \"description\": \"The full ordered AND filter chain: key=value for equality, key alone for existence (e.g. \\\"amenity=restaurant, cuisine=italian, name\\\").\"}, \"data_timestamp\": {\"type\": \"string\", \"description\": \"OSM data freshness timestamp from the Overpass response. Absent when the endpoint reported no freshness metadata.\"}, \"servingEndpoint\": {\"type\": \"string\", \"description\": \"Overpass endpoint that answered, as origin and path. May name a failover mirror, or the endpoint that originally served a cached response. Read with data_timestamp when a result looks slow, sparse, or stale.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"openWorldHint\": true, \"idempotentHint\": true}', NULL, '9ad59091f3d39f3c3e9ceac55c65d0cd33b0b2e6357b82aca163eb7049da950c', 'IMPORTED', 'ACTIVE', '1', '0', 'LOW', '0', 30, '[]', '2026-09-29 11:29:28', 100, 1, '2026-09-29 11:29:28', 1, '2026-09-29 11:32:32', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775540564660228, 2104774189336072193, 'openstreetmap_query_bbox', 'openstreetmap-mcp:openstreetmap_query_bbox', 'Find OSM features inside a bounding box or an OSM boundary', 'Find OSM features inside an area via the Overpass API, for surveys of everything in a region (openstreetmap_query_nearby covers proximity to a point). Scope with the four corner fields south, west, north, east, or with within and a single OSM boundary ref such as a city relation or a park way, which searches the boundary polygon itself instead of an overcovering box; never both. Filter with amenity, or with tag_key plus an optional tag_value, ANDing up to five more filters; every feature returns with its full OSM tag set (no extratags flag here).', '{\"type\": \"object\", \"anyOf\": [{\"type\": \"object\", \"required\": [\"south\", \"west\", \"north\", \"east\", \"amenity\"]}, {\"type\": \"object\", \"required\": [\"south\", \"west\", \"north\", \"east\", \"tag_key\"]}, {\"type\": \"object\", \"required\": [\"within\", \"amenity\"]}, {\"type\": \"object\", \"required\": [\"within\", \"tag_key\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"east\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Eastern boundary longitude (maximum longitude). A value below west describes an antimeridian crossing rather than an inverted box.\"}, \"west\": {\"type\": \"number\", \"maximum\": 180, \"minimum\": -180, \"description\": \"Western boundary longitude (minimum longitude). A west greater than east is valid, not an error: Overpass reads it as an antimeridian-crossing box and returns the union of west..180 and -180..east.\"}, \"limit\": {\"type\": \"integer\", \"default\": 20, \"maximum\": 500, \"minimum\": 1, \"description\": \"Maximum results to return. Applied after the Overpass query — if the area has more features, they are truncated.\"}, \"north\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Northern boundary latitude (maximum latitude).\"}, \"south\": {\"type\": \"number\", \"maximum\": 90, \"minimum\": -90, \"description\": \"Southern boundary latitude (minimum latitude). One of four corner fields: supply all four, or use within instead.\"}, \"offset\": {\"type\": \"integer\", \"default\": 0, \"maximum\": 9007199254740991, \"minimum\": 0, \"description\": \"Number of matching features to skip before applying limit, for paging through a large result set. The full match set is fetched and cached ~10 minutes keyed by the query, so re-paging at a new offset is deterministic and costs no extra upstream request. Pass the nextOffset value from a prior truncated response.\"}, \"within\": {\"type\": \"string\", \"pattern\": \"^[RWrw]\\\\d+$\", \"description\": \"OSM boundary to search inside, as one ref: R plus a relation id (\\\"R237385\\\", Seattle) or W plus a closed-way id (\\\"W13800188\\\", a park), case-insensitive. Take it from osm_type plus osm_id on openstreetmap_search_places, openstreetmap_reverse_geocode, or openstreetmap_lookup_objects. The alternative to the four corner fields, never both. A node ref is rejected: a node is never an area. A ref that maps to no Overpass area returns an empty page whose notice names the cause.\"}, \"amenity\": {\"type\": \"string\", \"description\": \"OSM amenity tag value shortcut (e.g. \\\"cafe\\\", \\\"bench\\\", \\\"hospital\\\"). Exactly one primary mode is required: this or tag_key, never both.\"}, \"filters\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"key\"], \"properties\": {\"key\": {\"type\": \"string\", \"description\": \"Literal OSM tag key. Trimmed and nonblank; must be unique across the primary tag and all filters.\"}, \"value\": {\"type\": \"string\", \"description\": \"Literal exact-match value. Omit for key existence; an explicitly blank value is invalid. Trimmed before matching.\"}}, \"description\": \"One additional literal equality or key-existence filter.\", \"additionalProperties\": false}, \"maxItems\": 5, \"description\": \"Up to five additional filters, ANDed with the required primary amenity or tag_key filter in input order. Omitted or [] adds no conditions. Keys must be unique after trimming; keys and values must not contain Overpass QL metacharacters (\\\" \\\\ [ ] ; ( )).\"}, \"tag_key\": {\"type\": \"string\", \"description\": \"Primary OSM tag key (e.g. \\\"leisure\\\", \\\"shop\\\", \\\"natural\\\"); omit tag_value to match any feature carrying the key, or supply it for exact equality. The alternative to amenity, never both. Additional filters are ANDed with this tag.\"}, \"tag_value\": {\"type\": \"string\", \"description\": \"Literal value paired with tag_key for exact equality (e.g., \\\"park\\\", \\\"supermarket\\\"); omit for key existence. Explicit empty or whitespace-only values are invalid. Keys and values are trimmed; blank unused fields are ignored in amenity mode.\"}, \"element_types\": {\"type\": \"array\", \"items\": {\"enum\": [\"node\", \"way\", \"relation\"], \"type\": \"string\"}, \"default\": [\"node\", \"way\"], \"minItems\": 1, \"description\": \"OSM element types to search, at least one. Ways cover most buildings and areas; nodes cover most standalone POIs. Add \\\"relation\\\" for complex structures. Omit the field to search nodes and ways; an empty array is rejected because it can only match nothing.\"}, \"timeout_seconds\": {\"type\": \"integer\", \"default\": 25, \"maximum\": 60, \"minimum\": 5, \"description\": \"Overpass query timeout in seconds. Increase for large bounding boxes or dense areas.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"elements\", \"attribution\", \"effectiveTag\", \"totalFound\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"invalid_scope\", \"invalid_bbox\", \"invalid_tag\", \"query_timeout\", \"result_too_large\", \"rate_limited\", \"upstream_error\", \"overpass_gateway_timeout\", \"overpass_unavailable\", \"endpoints_exhausted\", \"endpoints_unavailable\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `invalid_scope`: The two spatial scopes conflict: within sent alongside a corner field, neither scope sent, or only part of the four-corner set sent. `invalid_bbox`: south exceeds north — the latitude bounds are inverted. `invalid_tag`: Tag modes conflict or are missing, a key or supplied value is blank, keys repeat after trimming, or a filter carries Overpass QL metacharacters. `query_timeout`: The query exceeded timeout_seconds. `result_too_large`: Overpass ran out of memory on this query. `rate_limited`: Every configured endpoint refused the query as throttled — HTTP 429, or a throttle document in place of JSON. `upstream_error`: Overpass reported a runtime error that is neither a timeout nor memory exhaustion. `overpass_gateway_timeout`: Overpass answered HTTP 504 — the query exceeded the endpoint\'s own time budget, not timeout_seconds. `overpass_unavailable`: Overpass answered an HTTP 5xx other than 504 — the endpoint is down, restarting, or shedding load. `endpoints_exhausted`: No endpoint answered within its attempt window, or the total time budget ran out first. `endpoints_unavailable`: No configured endpoint would serve the call — connections refused, DNS failures, HTTP refusals such as 401/403/404, throttling, or instance faults, in some mix. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"notice\": {\"type\": \"string\", \"description\": \"Why this page is empty and what to try: the within ref resolved to no Overpass area, nothing matched (change the scope or tag), or offset ran past the end (retry lower). Absent when results were returned.\"}, \"elements\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"osm_type\", \"osm_id\", \"tags\"], \"properties\": {\"lat\": {\"type\": \"number\", \"description\": \"Latitude (present for nodes and ways/relations with computed center).\"}, \"lon\": {\"type\": \"number\", \"description\": \"Longitude (present for nodes and ways/relations with computed center).\"}, \"name\": {\"type\": \"string\", \"description\": \"Feature name from OSM tags.\"}, \"tags\": {\"type\": \"object\", \"description\": \"All OSM tags for this feature. Values are always strings.\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {\"type\": \"string\"}}, \"osm_id\": {\"type\": \"number\", \"description\": \"OSM element ID. Use with osm_type for openstreetmap_lookup_objects.\"}, \"osm_type\": {\"enum\": [\"node\", \"way\", \"relation\"], \"type\": \"string\", \"description\": \"OSM element type.\"}}, \"description\": \"A single matching OSM feature.\", \"additionalProperties\": false}, \"description\": \"Matching OSM features inside the requested scope — the bounding box, or the within boundary — up to the limit.\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True if results were cut at the limit. Reduce bbox area, add more specific tags, or page with offset to retrieve the rest.\"}, \"nextOffset\": {\"type\": \"number\", \"description\": \"Offset to pass on the next call to retrieve the following page of features. Present only when more features remain beyond this page.\"}, \"totalFound\": {\"type\": \"number\", \"description\": \"Total features returned by Overpass before limit truncation.\"}, \"attribution\": {\"type\": \"string\", \"description\": \"Required data attribution: Data © OpenStreetMap contributors, ODbL 1.0.\"}, \"effectiveTag\": {\"type\": \"string\", \"description\": \"The full ordered AND filter chain: key=value for equality, key alone for existence (e.g. \\\"amenity=restaurant, cuisine=italian, name\\\").\"}, \"effectiveArea\": {\"type\": \"string\", \"description\": \"The boundary scope as resolved: the within ref and the Overpass area it mapped to. Absent when the call used the four corner fields.\"}, \"areasTimestamp\": {\"type\": \"string\", \"description\": \"Freshness of the Overpass area database, rebuilt on its own schedule and so lagging data_timestamp — a boundary edited since is scoped against its older polygon. Present only on a within call whose endpoint reported it.\"}, \"data_timestamp\": {\"type\": \"string\", \"description\": \"OSM data freshness timestamp from the Overpass response. Absent when the endpoint reported no freshness metadata.\"}, \"servingEndpoint\": {\"type\": \"string\", \"description\": \"Overpass endpoint that answered, as origin and path. May name a failover mirror, or the endpoint that originally served a cached response. Read with data_timestamp when a result looks slow, sparse, or stale.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"openWorldHint\": true, \"idempotentHint\": true}', NULL, '6029752f0c162b1fc2150c53d966cda71e566b300cf5cc0520cb863ab2a19f56', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:28', 100, 1, '2026-09-29 11:29:28', 1, '2026-09-29 11:33:12', '0');
INSERT INTO `mcp_tool_info` VALUES (2104775540635963394, 2104774189336072193, 'openstreetmap_query_raw', 'openstreetmap-mcp:openstreetmap_query_raw', 'Execute a raw Overpass QL query', 'Run an arbitrary Overpass QL query for anything the convenience tools cannot express: multi-type or union queries, relation membership, historical queries, regex tag matching. The query must include [out:json], e.g. \"[out:json][timeout:15];node[\\\"natural\\\"=\\\"peak\\\"](47.5,-122.5,47.7,-122.2);out body;\"; scope to an OSM boundary with rel();map_to_area->.a; or way();map_to_area->.a; then (area.a) on each statement (the 2400000000 way-area offset is gone since Overpass 0.7.57; openstreetmap_query_bbox takes the same scope as within, without QL). The response is one page: page with limit and offset, read totalFound and truncated for the whole match, and an element over max_element_bytes arrives with its members, nodes or geometry array withheld whole and withheldNotice saying how to fetch it back. For plain \"near X\" or \"in this area\" questions use openstreetmap_query_nearby or openstreetmap_query_bbox.', '{\"type\": \"object\", \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"required\": [\"query\"], \"properties\": {\"limit\": {\"type\": \"integer\", \"default\": 20, \"maximum\": 500, \"minimum\": 1, \"description\": \"Maximum elements to return. Applied after the Overpass query — if the query matched more, they are truncated.\"}, \"query\": {\"type\": \"string\", \"description\": \"Overpass QL query string. Must include [out:json]. The server sets the endpoint and User-Agent; do not include those. Example: \\\"[out:json][timeout:15];node[\\\\\\\"natural\\\\\\\"=\\\\\\\"peak\\\\\\\"](47.5,-122.5,47.7,-122.2);out body;\\\"\"}, \"offset\": {\"type\": \"integer\", \"default\": 0, \"maximum\": 9007199254740991, \"minimum\": 0, \"description\": \"Elements to skip before applying limit, for paging a large result set. The full match set is cached ~10 minutes keyed by the query, so re-paging at a new offset is deterministic and costs no extra request; a result over 100000 elements is served uncached, so paging that far re-queries and depends on the endpoint returning the same order. Pass the nextOffset from a prior truncated response.\"}, \"timeout_seconds\": {\"type\": \"integer\", \"default\": 30, \"maximum\": 180, \"minimum\": 5, \"description\": \"How long Overpass may spend on the query. A [timeout:N] directive in the query string wins over this. The client waits the full value rather than cutting a long query off early, but the endpoint enforces its own budget and may answer HTTP 504 first.\"}, \"max_element_bytes\": {\"type\": \"integer\", \"default\": 20000, \"maximum\": 10000000, \"minimum\": 1000, \"description\": \"Serialized-byte budget for one element, in UTF-8 bytes, applied per element after limit and offset — the dimension limit cannot bound, a single relation or geometry-heavy way. An over-budget element keeps every scalar and its tags but has its members, nodes and geometry arrays withheld whole, never truncated to a prefix, and lists each under withheld_keys with its item count and byte size; withheldElements and withheldNotice then give the offset and raised budget that fetch it back whole in one more call. That disclosure is not counted against the budget, so a bounded element runs ~60 bytes per withheld key above it.\"}}, \"additionalProperties\": false}', '{\"type\": \"object\", \"anyOf\": [{\"not\": {\"required\": [\"error\"]}, \"required\": [\"elements\", \"total_elements\", \"attribution\", \"effectiveQuery\", \"totalFound\", \"truncated\"]}, {\"required\": [\"error\"]}], \"$schema\": \"https://json-schema.org/draft/2020-12/schema\", \"properties\": {\"error\": {\"type\": \"object\", \"required\": [\"code\", \"message\"], \"properties\": {\"code\": {\"type\": \"integer\", \"maximum\": 9007199254740991, \"minimum\": -9007199254740991, \"description\": \"JSON-RPC error code for this failure.\"}, \"data\": {\"type\": \"object\", \"properties\": {\"reason\": {\"type\": \"string\", \"examples\": [\"query_error\", \"query_timeout\", \"result_too_large\", \"rate_limited\", \"upstream_error\", \"overpass_gateway_timeout\", \"overpass_unavailable\", \"endpoints_exhausted\", \"endpoints_unavailable\"], \"description\": \"Machine-readable failure mode. Declared by this tool: `query_error`: Overpass returned HTTP 400 — malformed query syntax. `query_timeout`: The query exceeded its timeout. `result_too_large`: Overpass ran out of memory on this query. `rate_limited`: Every configured endpoint refused the query as throttled — HTTP 429, or a throttle document in place of JSON. `upstream_error`: Overpass reported a runtime error that is neither a timeout nor memory exhaustion. `overpass_gateway_timeout`: Overpass answered HTTP 504 — the query exceeded the endpoint\'s own time budget, not the [timeout:N] directive. `overpass_unavailable`: Overpass answered an HTTP 5xx other than 504 — the endpoint is down, restarting, or shedding load. `endpoints_exhausted`: No endpoint answered within its attempt window, or the total time budget ran out first. `endpoints_unavailable`: No configured endpoint would serve the call — connections refused, DNS failures, HTTP refusals such as 401/403/404, throttling, or instance faults, in some mix. Other values are possible when a failure originates below the handler.\"}, \"recovery\": {\"type\": \"object\", \"required\": [\"hint\"], \"properties\": {\"hint\": {\"type\": \"string\"}}, \"description\": \"Actionable next step for the caller.\", \"additionalProperties\": {}}, \"retryable\": {\"type\": \"boolean\", \"description\": \"Whether retrying may succeed.\"}}, \"additionalProperties\": {}}, \"message\": {\"type\": \"string\", \"description\": \"Human-readable description of what went wrong.\"}}, \"description\": \"Present when the call failed. Absent on success.\", \"additionalProperties\": {}}, \"notice\": {\"type\": \"string\", \"description\": \"Why this page is empty and what to try: nothing matched (check the query syntax or broaden the filter), or offset ran past the end (retry lower). Absent when results were returned.\"}, \"elements\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"propertyNames\": {\"type\": \"string\"}, \"additionalProperties\": {}}, \"description\": \"Raw Overpass elements for this page, up to the limit. Shape varies by type: nodes carry lat/lon, ways nodes[], relations members[]. An element over max_element_bytes swaps those heavy arrays for withheld_keys, each naming the key, its item count, and its byte size.\"}, \"truncated\": {\"type\": \"boolean\", \"description\": \"True if elements were cut at the limit. Narrow the query, or page with offset to retrieve the rest.\"}, \"nextOffset\": {\"type\": \"number\", \"description\": \"Offset to pass on the next call to retrieve the following page of elements. Present only when more elements remain beyond this page.\"}, \"totalFound\": {\"type\": \"number\", \"description\": \"Total elements returned by Overpass before limit truncation.\"}, \"attribution\": {\"type\": \"string\", \"description\": \"Required data attribution: Data © OpenStreetMap contributors, ODbL 1.0.\"}, \"data_timestamp\": {\"type\": \"string\", \"description\": \"OSM data freshness timestamp from the Overpass response. Absent when the endpoint reported no freshness metadata.\"}, \"effectiveQuery\": {\"type\": \"string\", \"description\": \"The Overpass QL string as sent to the API (after any timeout injection).\"}, \"total_elements\": {\"type\": \"number\", \"description\": \"Number of elements returned on this page. See totalFound for the full match count.\"}, \"withheldNotice\": {\"type\": \"string\", \"description\": \"How to retrieve the withheld arrays, one element per call. Absent when every element fit.\"}, \"servingEndpoint\": {\"type\": \"string\", \"description\": \"Overpass endpoint that answered, as origin and path. May name a failover mirror, or the endpoint that originally served a cached response. Read with data_timestamp when a result looks slow, sparse, or stale.\"}, \"withheldElements\": {\"type\": \"array\", \"items\": {\"type\": \"object\", \"required\": [\"type\", \"id\", \"keys\", \"offset\", \"maxElementBytes\"], \"properties\": {\"id\": {\"type\": \"number\", \"description\": \"OSM id of the bounded element.\"}, \"keys\": {\"type\": \"array\", \"items\": {\"type\": \"string\"}, \"description\": \"Keys withheld whole from this element: members, nodes, or geometry.\"}, \"type\": {\"type\": \"string\", \"description\": \"OSM element type of the bounded element.\"}, \"offset\": {\"type\": \"number\", \"description\": \"Absolute offset of this element in the full match set. Pass it with limit 1 to fetch this element alone.\"}, \"maxElementBytes\": {\"type\": \"number\", \"description\": \"Serialized UTF-8 byte size of this element whole, which is the smallest max_element_bytes that returns it. Pass it on the retrieval call when it is at or below the 10000000 ceiling; above that no accepted budget returns the element whole and withheldNotice names the narrower query to use instead.\"}}, \"additionalProperties\": false}, \"description\": \"Elements on this page that exceeded max_element_bytes, each with the arguments that fetch it back whole. Absent when every element fit.\"}}, \"additionalProperties\": false}', '{\"readOnlyHint\": true, \"openWorldHint\": true, \"idempotentHint\": true}', NULL, '82161cc73aa5ce67a712606c582085fa7d58f4bc6ea15c13f5b03e400d6e3123', 'IMPORTED', 'ACTIVE', '1', '1', 'LOW', '0', 30, '[]', '2026-09-29 11:29:28', 100, 1, '2026-09-29 11:29:28', 1, '2026-09-29 11:33:07', '0');

-- ----------------------------
-- Table structure for model
-- ----------------------------
DROP TABLE IF EXISTS `model`;
CREATE TABLE `model`  (
  `id` bigint NOT NULL COMMENT '主键',
  `category` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型分类',
  `model_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型名称',
  `provider_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型供应商',
  `model_describe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型描述',
  `model_dimension` int NULL DEFAULT NULL COMMENT '模型维度',
  `model_show` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'Y' COMMENT '是否在用户端显示（Y是 N否）',
  `api_host` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '请求地址',
  `api_mode` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'CHAT_COMPLETIONS' COMMENT 'API调用模式',
  `credential_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Python侧凭证别名',
  `published_revision` int NOT NULL DEFAULT 0 COMMENT '最近发布修订号',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '0正常 1停用',
  `capabilities` json NULL COMMENT '模型能力标签',
  `max_context_tokens` int NULL DEFAULT NULL COMMENT '最大上下文Token',
  `max_input_tokens` int NULL DEFAULT NULL COMMENT '最大输入Token',
  `max_output_tokens` int NULL DEFAULT NULL COMMENT '单次调用最大输出Token',
  `safety_margin_tokens` int NULL DEFAULT NULL COMMENT '上下文预算安全余量Token',
  `history_max_turns` int NULL DEFAULT NULL COMMENT '最近历史最大轮数',
  `knowledge_max_chunks` int NULL DEFAULT NULL COMMENT '知识库最大检索片段数',
  `knowledge_max_tokens` int NULL DEFAULT NULL COMMENT '知识库资料最大Token',
  `tool_result_max_tokens` int NULL DEFAULT NULL COMMENT '单次工具结果最大Token',
  `rate_limit_rpm` int NULL DEFAULT NULL COMMENT '每分钟请求限制',
  `input_cost_per_million` decimal(18, 6) NULL DEFAULT NULL COMMENT '输入成本/百万Token',
  `output_cost_per_million` decimal(18, 6) NULL DEFAULT NULL COMMENT '输出成本/百万Token',
  `gray_weight` int NOT NULL DEFAULT 100 COMMENT '灰度权重0-100',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '是否删除（0未删除 1已删除）',
  `input_modalities` json NULL COMMENT '输入模态：TEXT/IMAGE',
  `adapter_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Provider适配器编码',
  `normalized` tinyint(1) NULL DEFAULT NULL COMMENT '向量是否已归一化',
  `max_document_tokens` int NULL DEFAULT NULL COMMENT 'Rerank单文档最大输入Token',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_model_profile`(`provider_code`, `model_name`, `category`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '模型管理' ROW_FORMAT = DYNAMIC;

