INSERT INTO `model` VALUES (2092197679865614337, 'chat', 'doubao-seed-character-260628', 'doubao', '对话模型', NULL, 'Y', 'https://ark.cn-beijing.volces.com/api/v3', 'CHAT_COMPLETIONS', 'doubao-api-key', 21, '0', '[\"TOOL\", \"GENERAL\"]', 128000, 128000, 32000, 512, 10, 5, 3000, 1500, NULL, NULL, NULL, 100, NULL, NULL, NULL, 1, '2026-09-29 14:00:54', 'Doubao-Seed-Character-260628 面向虚拟陪伴，强化角色扮演、多模态理解与剧情演绎，带来自然沉浸的互动体验。', '0', NULL, NULL, NULL, NULL);
INSERT INTO `model` VALUES (2092198049236996097, 'chat', 'glm-5-2-260617', 'doubao', '对话模型', NULL, 'Y', 'https://ark.cn-beijing.volces.com/api/v3', 'RESPONSES', 'doubao-api-key', 9, '0', '[\"GENERAL\"]', 16384, 16384, 4096, 512, 10, 5, 3000, 1500, NULL, NULL, NULL, 100, NULL, NULL, NULL, 1, '2026-09-29 14:02:17', '在 Coding、长上下文理解和长程任务上有明显提升，支持 1M 上下文和更灵活的思考强度控制，尤其适合复杂开发、移动端全栈、代码迁移和科研复现等场景。', '0', NULL, NULL, NULL, NULL);
INSERT INTO `model` VALUES (2097233021324853249, 'chat', 'deepseek-v4-flash-ga-260731', 'doubao', '对话模型', NULL, 'Y', 'https://ark.cn-beijing.volces.com/api/v3', 'CHAT_COMPLETIONS', 'doubao-api-key', 3, '0', NULL, 1024000, 1024000, 384000, 512, 10, 5, 3000, 1500, NULL, NULL, NULL, 100, 100, 1, '2026-09-08 15:58:12', 1, '2026-09-22 15:42:26', 'DeepSeek-V4-Flash正式版 是深度求索推出的高效通用模型，Agent能力大幅增强，在代码修改、工具调用、多步骤任务执行等场景表现更优，支持思考与非思考双模式及百万Token上下文。', '0', NULL, NULL, NULL, NULL);
INSERT INTO `model` VALUES (2101869467612487681, 'vector', 'ep-20260921162750-b4ksr', 'doubao', '图文多模态向量化模型', 2048, 'Y', 'https://ark.cn-beijing.volces.com/api/v3', 'ARK_MULTIMODAL_EMBEDDINGS', 'doubao-api-key', 9, '0', NULL, NULL, 500000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, 100, 1, '2026-09-21 11:01:47', 1, '2026-09-22 15:40:55', 'Doubao-embedding-vision，新版本Seed-1.6-embedding图文多模态向量化模型全新上线，主要面向图文多模向量检索的使用场景，支持图片输入及中、英双语文本输入，最长 8K 上下文长度。', '0', '[\"TEXT\", \"IMAGE\"]', NULL, 0, NULL);
INSERT INTO `model` VALUES (2102301286833074177, 'vector', 'qwen3.7-text-embedding', 'qianwen', '处理纯文本或代码向量化模型', 1024, 'Y', 'https://llm-897pm1f5pljvo373.cn-beijing.maas.aliyuncs.com/compatible-mode/v1', 'OPENAI_EMBEDDINGS', 'aliyun-api-key', 6, '0', NULL, NULL, 50000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, 100, 1, '2026-09-22 15:37:40', 1, '2026-09-22 18:02:15', '处理纯文本或代码：推荐使用qwen3.7-text-embedding 。它是当前性能最强的模型，支持任务指令（instruct）、稀疏向量等高级功能，能覆盖绝大多数文本处理场景。若更关注成本与吞吐，可使用轻量版 qwen3.7-text-embedding-flash，它同样支持任务指令（instruct）与三种向量输出类型，并保持 201 种语言和 128K 上下文，向量维度可在 256~1024 范围内选择。', '0', '[\"TEXT\"]', NULL, 0, NULL);
INSERT INTO `model` VALUES (2102326500702896129, 'image', 'doubao-seed-2-1-turbo-260628', 'doubao', '识别图片', NULL, 'Y', 'https://ark.cn-beijing.volces.com/api/v3', 'RESPONSES', 'doubao-api-key', 5, '0', NULL, NULL, 500000, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, 100, 1, '2026-09-22 17:17:52', 1, '2026-09-23 11:07:28', NULL, '0', '[\"IMAGE\"]', NULL, NULL, NULL);
INSERT INTO `model` VALUES (2102947783069138946, 'rerank', 'doubao-seed-rerank', 'doubao', '豆包重排序', NULL, 'Y', 'https://api-knowledgebase.mlp.cn-beijing.volces.com', 'CHAT_COMPLETIONS', 'doubao-rerank-aksk', 6, '0', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 100, 100, 1, '2026-09-24 10:26:37', 1, '2026-09-29 14:34:10', NULL, '0', '[\"TEXT\", \"IMAGE\"]', 'VOLCENGINE_KNOWLEDGE_RERANK', NULL, 50000);

