-- ----------------------------
-- Table structure for token_quota_log
-- ----------------------------
DROP TABLE IF EXISTS `token_quota_log`;
CREATE TABLE `token_quota_log`  (
  `id` bigint NOT NULL COMMENT '流水ID',
  `account_id` bigint NOT NULL COMMENT '额度账户ID',
  `user_id` bigint NOT NULL COMMENT 'CDP员工ID',
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '操作类型',
  `change_tokens` bigint NOT NULL DEFAULT 0 COMMENT '本次额度变化量',
  `before_total` bigint NOT NULL DEFAULT 0 COMMENT '操作前累计额度',
  `after_total` bigint NOT NULL DEFAULT 0 COMMENT '操作后累计额度',
  `before_remaining` bigint NOT NULL DEFAULT 0 COMMENT '操作前剩余额度',
  `after_remaining` bigint NOT NULL DEFAULT 0 COMMENT '操作后剩余额度',
  `operator_id` bigint NOT NULL COMMENT '操作人CDP员工ID',
  `reason` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '操作原因',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_ai_token_quota_log_user_time`(`user_id`, `create_time`) USING BTREE,
  INDEX `idx_ai_token_quota_log_account_time`(`account_id`, `create_time`) USING BTREE,
  INDEX `idx_ai_token_quota_log_operator_time`(`operator_id`, `create_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = 'Token额度调整流水' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of token_quota_log
-- ----------------------------
