-- ----------------------------
-- Table structure for token_usage
-- ----------------------------
DROP TABLE IF EXISTS `token_usage`;
CREATE TABLE `token_usage`  (
  `id` bigint NOT NULL COMMENT '用量记录ID',
  `request_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务请求ID',
  `call_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '模型调用幂等ID',
  `user_id` bigint NOT NULL COMMENT 'CDP员工ID',
  `account_id` bigint NULL DEFAULT NULL COMMENT '额度账户ID',
  `session_id` bigint NULL DEFAULT NULL COMMENT '会话ID',
  `agent_id` bigint NULL DEFAULT NULL COMMENT '智能体ID',
  `model_id` bigint NOT NULL COMMENT '模型ID',
  `provider_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '厂商编码快照',
  `model_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '模型名称快照',
  `model_revision` int NULL DEFAULT NULL COMMENT '模型发布修订号快照',
  `input_tokens` bigint NOT NULL DEFAULT 0 COMMENT '输入Token',
  `output_tokens` bigint NOT NULL DEFAULT 0 COMMENT '输出Token',
  `cache_tokens` bigint NOT NULL DEFAULT 0 COMMENT '缓存Token',
  `reasoning_tokens` bigint NOT NULL DEFAULT 0 COMMENT '推理Token',
  `actual_tokens` bigint NOT NULL DEFAULT 0 COMMENT '实际Token合计',
  `charged_tokens` bigint NOT NULL DEFAULT 0 COMMENT '按权重计费后的Token',
  `reserved_tokens` bigint NOT NULL DEFAULT 0 COMMENT '本次预占Token',
  `input_weight` decimal(10, 4) NULL DEFAULT NULL COMMENT '输入Token权重快照',
  `output_weight` decimal(10, 4) NULL DEFAULT NULL COMMENT '输出Token权重快照',
  `cache_weight` decimal(10, 4) NULL DEFAULT NULL COMMENT '缓存Token权重快照',
  `reasoning_weight` decimal(10, 4) NULL DEFAULT NULL COMMENT '推理Token权重快照',
  `estimated_cost` decimal(18, 6) NOT NULL DEFAULT 0.000000 COMMENT '预估成本',
  `usage_source` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT 'Token来源：PROVIDER/ESTIMATE',
  `usage_unit` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '原始计量单位：TOKENS/REQUESTS/DOCUMENT_PAIRS/UNKNOWN',
  `usage_quantity` bigint NULL DEFAULT NULL COMMENT '原始计量数量，UNKNOWN时为空',
  `measurement_quality` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '计量质量：ACTUAL/ESTIMATED/UNKNOWN',
  `status` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态：RESERVED/SUCCESS/FAILED/CANCELED/EXPIRED',
  `error_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '错误码',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '错误摘要',
  `start_time` datetime(0) NOT NULL COMMENT '调用开始时间',
  `finish_time` datetime(0) NULL DEFAULT NULL COMMENT '调用完成时间',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ai_token_usage_call`(`call_id`) USING BTREE,
  INDEX `idx_ai_token_usage_user_time`(`user_id`, `start_time`) USING BTREE,
  INDEX `idx_ai_token_usage_model_time`(`model_id`, `start_time`) USING BTREE,
  INDEX `idx_ai_token_usage_status_time`(`status`, `start_time`) USING BTREE,
  INDEX `idx_ai_token_usage_request`(`request_id`) USING BTREE,
  INDEX `idx_ai_token_usage_user_time_id`(`user_id`, `start_time`, `id`) USING BTREE,
  INDEX `idx_ai_token_usage_user_status_time`(`user_id`, `status`, `start_time`, `id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '模型Token使用明细' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of token_usage
-- ----------------------------
