-- ----------------------------
-- Table structure for trace_node
-- ----------------------------
DROP TABLE IF EXISTS `trace_node`;
CREATE TABLE `trace_node`  (
  `id` bigint NOT NULL COMMENT '主键',
  `trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '链路ID',
  `node_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '节点ID',
  `parent_node_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '父节点ID',
  `node_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '节点名称',
  `node_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '节点类型',
  `depth` int NULL DEFAULT 0 COMMENT '节点深度',
  `sort_order` int NULL DEFAULT 0 COMMENT '排序',
  `class_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '类名',
  `method_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '方法名',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态',
  `start_time` datetime(0) NOT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `duration_ms` bigint NULL DEFAULT NULL COMMENT '耗时毫秒',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '错误摘要',
  `input_payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '输入JSON',
  `output_payload` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '输出JSON',
  `metadata` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '元数据JSON',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_trace_node_trace_id`(`trace_id`) USING BTREE,
  INDEX `idx_trace_node_parent`(`trace_id`, `parent_node_id`) USING BTREE,
  INDEX `idx_trace_node_time`(`trace_id`, `start_time`) USING BTREE,
  INDEX `idx_trace_node_start_time`(`start_time`) USING BTREE,
  INDEX `idx_trace_node_type_status`(`node_type`, `status`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '链路追踪节点记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of trace_node
-- ----------------------------

-- ----------------------------
-- Table structure for trace_run
-- ----------------------------
DROP TABLE IF EXISTS `trace_run`;
CREATE TABLE `trace_run`  (
  `id` bigint NOT NULL COMMENT '主键',
  `trace_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '链路ID',
  `trace_name` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '链路名称',
  `business_type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '业务类型',
  `business_id` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '业务ID',
  `user_id` bigint NULL DEFAULT NULL COMMENT '用户ID',
  `status` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '状态',
  `start_time` datetime(0) NOT NULL COMMENT '开始时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '结束时间',
  `duration_ms` bigint NULL DEFAULT NULL COMMENT '耗时毫秒',
  `error_message` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '错误摘要',
  `metadata` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '元数据JSON',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '删除标志（0代表存在 2代表删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_trace_run_trace_id`(`trace_id`) USING BTREE,
  INDEX `idx_trace_run_business`(`business_type`, `business_id`) USING BTREE,
  INDEX `idx_trace_run_status_time`(`status`, `start_time`) USING BTREE,
  INDEX `idx_trace_run_time`(`start_time`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '链路追踪运行记录表' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of trace_run
-- ----------------------------

-- ----------------------------
-- Table structure for user_token_account
-- ----------------------------
DROP TABLE IF EXISTS `user_token_account`;
CREATE TABLE `user_token_account`  (
  `id` bigint NOT NULL COMMENT '额度账户ID',
  `user_id` bigint NOT NULL COMMENT 'CDP员工ID（不建跨库外键）',
  `cycle_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'MANUAL' COMMENT '周期类型，当前固定MANUAL',
  `cycle_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'MANUAL' COMMENT '周期编号，当前固定MANUAL',
  `total_tokens` bigint NOT NULL DEFAULT 0 COMMENT '累计分配额度',
  `used_tokens` bigint NOT NULL DEFAULT 0 COMMENT '已结算额度，预留给Python执行面更新',
  `reserved_tokens` bigint NOT NULL DEFAULT 0 COMMENT '预占额度，预留给Python执行面更新',
  `unlimited` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '是否不限额：0否 1是',
  `warning_threshold` int NOT NULL DEFAULT 80 COMMENT '告警阈值百分比',
  `cycle_start` datetime(0) NULL DEFAULT NULL COMMENT '周期开始时间',
  `cycle_end` datetime(0) NULL DEFAULT NULL COMMENT '周期结束时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态：0正常 1冻结 2关闭',
  `version` int NOT NULL DEFAULT 0 COMMENT '乐观锁版本',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `create_dept` bigint NULL DEFAULT NULL COMMENT '创建部门',
  `create_by` bigint NULL DEFAULT NULL COMMENT '创建者',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `update_by` bigint NULL DEFAULT NULL COMMENT '更新者',
  `update_time` datetime(0) NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_ai_token_account_user_cycle`(`user_id`, `cycle_no`) USING BTREE,
  INDEX `idx_ai_token_account_status`(`status`, `unlimited`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '用户Token额度账户' ROW_FORMAT = Dynamic;

