-- ----------------------------
-- Procedure structure for add_ai_column_if_missing
-- ----------------------------
DROP PROCEDURE IF EXISTS `add_ai_column_if_missing`;
delimiter ;;
CREATE PROCEDURE `add_ai_column_if_missing`(IN target_table varchar(64),
    IN target_column varchar(64),
    IN column_definition text)
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = DATABASE()
          AND table_name = target_table
          AND column_name = target_column
    ) THEN
        SET @column_sql = CONCAT('ALTER TABLE `', target_table, '` ADD COLUMN `',
            target_column, '` ', column_definition);
        PREPARE column_stmt FROM @column_sql;
        EXECUTE column_stmt;
        DEALLOCATE PREPARE column_stmt;
    END IF;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
